import { Book } from "@/lib/types";

export const deuteronomy: Book = {
  id: "deuteronomy",
  name: "5. Mose",
  shortName: "5.Mose",
  testament: "old",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Dies sind die Worte, die Mose zu ganz Israel geredet hat* jenseits des Jordan, in der Wüste*, in der Ebene*, Suf gegenüber, zwischen Paran und Tofel, Laban, Hazerot und Di-Sahab.", heading: "Weg Israels vom Sinai bis Kadesch", footnotes: ["℘ Kap. 5,1; 27,1; 29,1; 31,1.2.30", "℘ Apg 7,38", "hebr. Araba; die Niederung, die zu beiden Seiten des Jordan und des Toten Meeres liegt und sich bis zum Golf von Akaba hin erstreckt"] },
      { number: 2, text: "Elf Tage sind es vom Horeb, auf dem Weg zum Gebirge Seïr, bis Kadesch-Barnea*.", footnotes: ["℘ V. 19; Kap. 9,23"] },
      { number: 3, text: "Und es geschah im vierzigsten Jahr, im elften Monat, am Ersten des Monats*, da redete Mose zu den Söhnen Israel nach allem, was ihm der HERR für sie geboten hatte*,", footnotes: ["℘ 4Mo 1,1; 33,38", "℘ 3Mo 27,34"] },
      { number: 4, text: "nachdem er Sihon, den König der Amoriter, der in Heschbon wohnte*, geschlagen hatte und Og, den König von Baschan, der in Aschtarot und in Edreï wohnte*.", footnotes: ["o. thronte; d. h. herrschte", "o. thronte; d. h. herrschte\n℘ Kap. 3,1; 4Mo 21,24.26.33; Jos 12,2.4"] },
      { number: 5, text: "Jenseits des Jordan, im Land Moab, fing Mose an, dieses Gesetz auszulegen*, indem er sprach:", footnotes: ["℘ Kap. 4,44.46"] },
      { number: 6, text: "Der HERR, unser Gott, redete zu uns am Horeb* und sprach: Lange genug seid ihr an diesem Berg geblieben.", footnotes: ["℘ Kap. 5,2; 9,8; 18,16; 2Mo 3,1; Mal 3,22"] },
      { number: 7, text: "Wendet euch, brecht auf* und zieht zum Gebirge der Amoriter und zu allen ihren Nachbarn in der Ebene*, auf dem Gebirge, in der Niederung* und im Süden und an der Küste des Meeres, in das Land der Kanaaniter und zum Libanon*, bis an den großen Strom, den Euphratstrom*!", footnotes: ["w. reißt euch die Zeltpflöcke heraus\n℘ V. 19; 4Mo 10,12.13", "hebr. Araba; die Niederung, die zu beiden Seiten des Jordan und des Toten Meeres liegt und sich bis zum Golf von Akaba hin erstreckt", "hebr. Schefelah; d. i. der Küstenstreifen zwischen Jafo und Gaza\n℘ Jos 9,1; 1Chr 27,29", "℘ Jos 11,16.17", "℘ 1Mo 15,18"] },
      { number: 8, text: "Siehe, ich habe das Land vor euch dahingegeben. Geht hinein und nehmt das Land in Besitz, von dem der HERR euren Vätern, Abraham, Isaak und Jakob geschworen hat, es ihnen und ihren Nachkommen nach ihnen zu geben*!", footnotes: ["℘ V. 35; Kap. 2,29; 4,1; 6,10; 7,8.12.13; 8,1.18; 9,5; 10,11; 11,9.21; 26,3.15; 28,11; 30,20; 31,7.21; 34,4; 1Mo 12,7; 2Mo 33,1; Jos 1,6; Ri 2,1; Neh 9,15; Jer 32,22"] },
      { number: 9, text: "Und in jener Zeit sprach ich zu euch: Ich allein kann euch nicht tragen*.", footnotes: ["℘ 2Mo 18,18"] },
      { number: 10, text: "Der HERR, euer Gott, hat euch zahlreich werden lassen, und siehe, ihr seid heute wie die Sterne des Himmels an Menge*.", footnotes: ["℘ Kap. 10,22; 28,62; 1Mo 22,17; Hes 16,7"] },
      { number: 11, text: "Der HERR, der Gott eurer Väter, füge zu euch noch tausendmal so viel, wie ihr seid, hinzu* und segne euch, wie er zu euch geredet hat*!", footnotes: ["℘ 2Sam 24,3", "℘ Kap. 10,22; 28,62; 1Mo 22,17; Hes 16,7"] },
      { number: 12, text: "Wie könnte ich allein eure Bürde und eure Last und euren Rechtsstreit tragen?" },
      { number: 13, text: "Bringt weise und verständige und anerkannte* Männer für eure Stämme, dass ich sie als Oberhäupter über euch einsetze*!", footnotes: ["w. und für den Dienst als befähigt erkannte", "℘ 1Mo 41,33"] },
      { number: 14, text: "Und ihr antwortetet mir und sagtet: Gut ist die Sache, die zu tun du angekündigt hast." },
      { number: 15, text: "Und ich nahm die Oberhäupter eurer Stämme, weise und anerkannte* Männer, und setzte sie als Oberhäupter über euch ein, als Oberste über Tausend und Oberste über Hundert und Oberste über Fünfzig und Oberste über Zehn und als Verwalter für eure Stämme*.", footnotes: ["w. und für den Dienst als befähigt erkannte", "o. entsprechend euren Stämmen\n℘ 2Mo 18,21; 24,1.9"] },
      { number: 16, text: "Und ich gebot euren Richtern in jener Zeit: Hört die Streitsachen zwischen euren Brüdern und richtet gerecht zwischen einem Mann und seinem Bruder* und dem Fremden bei ihm*!", footnotes: ["℘ Kap. 16,18", "℘ 3Mo 24,22; Joh 7,24.51"] },
      { number: 17, text: "Ihr sollt im Gericht nicht die Person ansehen*; den Kleinen wie den Großen sollt ihr hören*. Ihr sollt euch vor niemandem fürchten*, denn das Gericht ist Gottes Sache*. Die Sache aber, die zu schwer für euch ist, bringt vor mich, dass ich sie höre*!", footnotes: ["℘ Kap. 16,19; 2Mo 23,2.3.6; Spr 28,21; Jak 2,1.9", "℘ Ps 82,2-4", "℘ Spr 29,25; 1Tim 5,21", "℘ 1Sam 2,25; 2Chr 19,6", "℘ Kap. 17,8.9; 2Mo 18,26"] },
      { number: 18, text: "So gebot ich euch in jener Zeit all die Dinge, die ihr tun solltet." },
      { number: 19, text: "*Und wir brachen auf vom Horeb und zogen durch diese ganze große und schreckliche Wüste, die ihr gesehen habt auf dem Weg zum Gebirge der Amoriter, wie der HERR, unser Gott, es uns geboten hatte; und wir kamen bis Kadesch-Barnea*.", footnotes: ["℘ V. 19-46: 4Mo 13; 14", "℘ V. 2; Jos 10,41"] },
      { number: 20, text: "Und ich sagte zu euch: Ihr seid bis zu dem Gebirge der Amoriter gekommen, das der HERR, unser Gott, uns gibt." },
      { number: 21, text: "Siehe, der HERR, dein Gott, hat das Land vor dir dahingegeben. Zieh hinauf, nimm in Besitz, wie der HERR, der Gott deiner Väter, zu dir geredet hat! Fürchte dich nicht und sei nicht niedergeschlagen*!", footnotes: ["℘ Kap. 7,18.21; 20,3; 31,6.8; 4Mo 14,9; Jos 1,9"] },
      { number: 22, text: "Da tratet ihr alle zu mir und sagtet: Lasst uns Männer vor uns hersenden, dass sie das Land für uns erkunden und uns Bericht erstatten über den Weg, auf dem wir hinaufziehen, und über die Städte, zu denen wir kommen sollen!" },
      { number: 23, text: "Und die Sache war gut in meinen Augen. Und ich nahm zwölf Männer von euch, je einen Mann für den Stamm*.", footnotes: ["℘ 4Mo 32,8"] },
      { number: 24, text: "Und sie wandten sich und zogen ins Gebirge hinauf, und sie kamen bis zum Tal Eschkol und kundschafteten es* aus.", footnotes: ["d. h. das Land"] },
      { number: 25, text: "Und sie nahmen von den Früchten des Landes in ihre Hand und brachten sie zu uns herab. Und sie erstatteten uns Bericht und sagten: Das Land ist gut, das der HERR, unser Gott, uns gibt*.", footnotes: ["℘ 2Mo 3,8"] },
      { number: 26, text: "Aber ihr wolltet nicht hinaufziehen und wart widerspenstig gegen den Befehl des HERRN, eures Gottes*.", footnotes: ["℘ V. 43; Ps 106,24; Jes 63,10; Hebr 3,18"] },
      { number: 27, text: "Und ihr murrtet in euren Zelten* und sagtet: Weil der HERR uns hasst, hat er uns aus dem Land Ägypten herausgeführt, um uns in die Hand der Amoriter zu geben, damit sie uns vernichten*.", footnotes: ["Mit Umstellung zweier Buchstaben lesen andere: ihr verleumdetet euren Gott", "℘ Kap. 9,28"] },
      { number: 28, text: "Wohin ziehen wir? Unsere Brüder haben unser Herz verzagt gemacht*, indem sie sagten: Ein Volk, größer und höher gewachsen* als wir, Städte, groß und bis an den Himmel befestigt, und sogar Enakitersöhne haben wir dort gesehen*!", footnotes: ["℘ Jos 14,8", "LXX: zahlreicher", "℘ Kap. 2,10; 7,17; 9,2"] },
      { number: 29, text: "Da sagte ich zu euch: Erschreckt nicht und fürchtet euch nicht vor ihnen*!", footnotes: ["℘ Kap. 7,18; 20,1; Neh 4,8"] },
      { number: 30, text: "Der HERR, euer Gott, der vor euch herzieht, er wird für euch kämpfen* nach allem, was er in Ägypten vor euren Augen für euch getan hat*,", footnotes: ["℘ Kap. 20,4; 31,3.6.22; 2Mo 14,14.25; Röm 8,31", "℘ Kap. 4,34; 7,18.19; 11,3.7; 29,2; 34,11.12; 2Mo 10,21; 15,11; 19,4"] },
      { number: 31, text: "und in der Wüste, wo du gesehen hast, dass der HERR, dein Gott, dich getragen hat, wie ein Mann seinen Sohn trägt*, auf dem ganzen Weg, den ihr gezogen seid, bis ihr an diesen Ort kamt*.", footnotes: ["℘ 4Mo 11,12", "℘ Kap. 8,5; 2Mo 19,4; Jes 46,3.4; Hos 11,3.4; Apg 13,18"] },
      { number: 32, text: "Aber trotzdem* hatte niemand von euch Vertrauen in den HERRN, euren Gott*,", footnotes: ["w. In dieser Sache", "℘ Ps 106,24; Hebr 3,19"] },
      { number: 33, text: "der auf dem Weg vor euch herzog, um euch einen Ort auszusuchen, damit ihr euch lagern konntet*: bei Nacht im Feuer, damit ihr auf dem Weg sehen konntet, auf dem ihr zoget, und bei Tag in der Wolke*.", footnotes: ["℘ 4Mo 10,33", "℘ 2Mo 13,21; Neh 9,12.19"] },
      { number: 34, text: "Der HERR aber hatte den Lärm eurer Reden gehört. Da wurde er zornig und schwor:" },
      { number: 35, text: "Wenn irgendjemand unter diesen Männern, von dieser bösen Generation, das gute Land sehen wird, das ich euren Vätern zu geben geschworen habe*!", footnotes: ["Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde.\n℘ Kap. 2,14; Ps 95,11; Hes 20,15"] },
      { number: 36, text: "Nur Kaleb, der Sohn des Jefunne, er soll es sehen, und ihm und seinen Söhnen werde ich das Land geben, das er betreten hat, dafür, dass er ganz und gar hinter dem HERRN stand*. —", footnotes: ["℘ Jos 14,8.9"] },
      { number: 37, text: "Auch gegen mich wurde der HERR zornig euretwegen und sprach: Auch du sollst nicht dort hineinkommen*!", footnotes: ["℘ Kap. 3,26.27; 4,21.22; 31,2; 32,52; 34,4; 4Mo 20,12; Ps 106,32"] },
      { number: 38, text: "Josua, der Sohn des Nun, der vor dir steht, er soll dorthin kommen! Ihn stärke, denn er soll es Israel als Erbe austeilen*! —", footnotes: ["℘ Kap. 3,28; 31,7; 4Mo 34,17"] },
      { number: 39, text: "Und eure kleinen Kinder, von denen ihr sagtet: »Sie werden zur Beute werden!«, und eure Söhne, die heute weder Gutes noch Böses kennen, sie sollen dorthin kommen, und ihnen werde ich es geben, und sie sollen es in Besitz nehmen*.", footnotes: ["℘ Jos 5,7"] },
      { number: 40, text: "Ihr aber, wendet euch und brecht auf* zur Wüste, auf dem Weg zum Schilfmeer!*", footnotes: ["w. reißt euch die Zeltpflöcke heraus", "℘ Kap. 2,1"] },
      { number: 41, text: "Da antwortetet ihr und sagtet zu mir: Wir haben gegen den HERRN gesündigt! Wir wollen hinaufziehen und kämpfen nach allem, was der HERR, unser Gott, uns geboten hat. Und ihr gürtetet ein jeder seine Waffen um und hieltet es für ein Leichtes, ins Gebirge hinaufzuziehen." },
      { number: 42, text: "Da sprach der HERR zu mir: Sprich zu ihnen: Zieht nicht hinauf und kämpft nicht, denn ich bin nicht in eurer Mitte; damit ihr nicht vor euren Feinden geschlagen werdet!" },
      { number: 43, text: "So redete ich zu euch, aber ihr hörtet nicht. Und ihr wart widerspenstig gegen den Befehl des HERRN und handeltet vermessen und zogt in das Gebirge hinauf." },
      { number: 44, text: "Da zogen die Amoriter aus, die auf jenem Gebirge wohnten, euch entgegen und jagten euch nach*, wie es die Bienen tun, und zersprengten euch in Seïr bis nach Horma.", footnotes: ["℘ Jos 7,5; Ps 118,12"] },
      { number: 45, text: "Und ihr kehrtet zurück und weintet vor dem HERRN. Aber der HERR hörte nicht auf eure Stimme und neigte sein Ohr nicht zu euch*. —", footnotes: ["℘ Spr 1,25-28"] },
      { number: 46, text: "Und ihr bliebet in Kadesch viele Tage; eben die Zeit*, die ihr dort bliebet.*", footnotes: ["w. entsprechend den Tagen", "℘ 4Mo 20,1; Ri 11,16.17"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "Und wir wandten uns und brachen auf zur Wüste, auf dem Weg zum Schilfmeer, wie der HERR zu mir geredet hatte*. Und wir umzogen das Gebirge Seïr viele Tage lang.", heading: "Weg Israels durch die Wüste — Sieg über Sihon", footnotes: ["℘ Kap. 1,40"] },
      { number: 2, text: "Und der HERR redete zu mir und sprach:" },
      { number: 3, text: "Lange genug habt ihr dieses Gebirge umzogen. Wendet euch nach Norden!" },
      { number: 4, text: "Und gebiete dem Volk und sage: Ihr werdet nun das Gebiet eurer Brüder, der Söhne Esau, durchziehen, die in Seïr wohnen, und sie werden sich vor euch fürchten*. Aber hütet euch wohl!", footnotes: ["℘ 2Mo 15,15"] },
      { number: 5, text: "Lasst euch nicht in Streit mit ihnen ein, denn ich werde euch von ihrem Land auch nicht die Breite einer Fußsohle* geben! Denn das Gebirge Seïr habe ich dem Esau zum Besitz gegeben*.", footnotes: ["℘ Apg 7,5", "℘ 1Mo 36,8.9.43; Hes 35,2"] },
      { number: 6, text: "Nahrung sollt ihr für Geld von ihnen kaufen, damit ihr zu essen habt, und auch Wasser sollt ihr für Geld von ihnen kaufen, damit ihr zu trinken habt*.", footnotes: ["℘ 4Mo 20,19"] },
      { number: 7, text: "Denn der HERR, dein Gott, hat dich in allem Tun deiner Hand gesegnet*. Er gab acht auf* deine Wanderung durch diese große Wüste: Diese vierzig Jahre* ist der HERR, dein Gott, mit dir gewesen; es hat dir an nichts gemangelt*.", footnotes: ["℘ 1Mo 39,3; 4Mo 22,12", "o. kannte", "℘ Kap. 8,2-4; 29,4; 2Mo 16,35; Jer 2,2; Am 2,10", "℘ Neh 9,21; Hos 13,5"] },
      { number: 8, text: "Und wir zogen von unseren Brüdern, den Söhnen Esau, die in Seïr wohnen*, weiter weg von der Arabastraße*, von Elat* und von Ezjon-Geber* und wandten uns und zogen auf dem Weg zur Wüste Moabs.", footnotes: ["℘ 4Mo 20,21; Ri 11,18", "zu Araba s. Anm. zu Kap. 1,1", "℘ 2Kö 14,22", "℘ 4Mo 33,35"] },
      { number: 9, text: "Da sprach der HERR zu mir: Befehde Moab nicht und lass dich nicht in einen Krieg mit ihnen ein, denn ich werde dir von seinem Land keinen Besitz geben*! Denn Ar habe ich den Söhnen Lot* zum Besitz gegeben*. —", footnotes: ["℘ Ri 11,15; Jes 15,1", "℘ 1Mo 19,37", "℘ 4Mo 21,15"] },
      { number: 10, text: "Früher wohnten die Emiter darin*, ein großes und zahlreiches und hochgewachsenes Volk wie die Enakiter*.", footnotes: ["℘ 1Mo 14,5", "℘ Kap. 1,28"] },
      { number: 11, text: "Auch sie werden für Riesen* gehalten* wie die Enakiter; die Moabiter aber nennen sie Emiter.", footnotes: ["hebr. Refaïm", "℘ 1Mo 6,4; 2Sam 21,16"] },
      { number: 12, text: "Und in Seïr wohnten früher die Horiter. Aber die Söhne Esau verdrängten sie und vernichteten sie vor sich her und wohnten an ihrer Stelle*, so wie Israel es mit dem Land seines Besitzes getan hat, das der HERR ihnen gegeben hat. —", footnotes: ["℘ 1Mo 36,20-30"] },
      { number: 13, text: "Nun macht euch auf und zieht über den Bach* Sered*! Und wir zogen über den Bach Sered.", footnotes: ["o. das Bachtal. — Das hebr. Wort bezeichnet sowohl den Wasserlauf als auch das gesamte Tal, in dem der Bach fließt.", "℘ 4Mo 21,12.13"] },
      { number: 14, text: "Die Tage aber, die wir von Kadesch-Barnea wanderten, bis wir über den Bach Sered zogen, betrugen 38 Jahre*, bis die Generation der kriegstüchtigen Männer* aus dem Lager vollständig aufgerieben war*, so wie der HERR ihnen geschworen hatte*.", footnotes: ["℘ 4Mo 1,1", "w. das ganze Geschlecht der Männer des Krieges", "℘ 4Mo 26,64.65", "℘ Kap. 1,35"] },
      { number: 15, text: "Und zwar war die Hand des HERRN gegen sie, um sie aus dem Lager vollständig auszutilgen*.", footnotes: ["℘ Ps 78,33; 1Kor 10,5"] },
      { number: 16, text: "Und es geschah, als die kriegstüchtigen Männer* aus der Mitte des Volkes vollständig weggestorben waren,", footnotes: ["w. die Männer des Krieges"] },
      { number: 17, text: "da redete der HERR zu mir und sprach:" },
      { number: 18, text: "Du wirst heute das Gebiet von Moab, von Ar*, durchziehen", footnotes: ["℘ 4Mo 21,13"] },
      { number: 19, text: "und dich den Söhnen Ammon nähern, bis du ihrer Grenze gegenüberstehst. Du sollst sie nicht befehden und dich nicht in Streit mit ihnen einlassen, denn ich werde dir von dem Land der Söhne Ammon keinen Besitz geben*! Denn ich habe es den Söhnen Lot zum Besitz gegeben*. —", footnotes: ["℘ Ri 11,15; Jes 15,1", "℘ V. 37; 1Mo 19,38; Jos 13,10; 2Chr 20,10"] },
      { number: 20, text: "Auch dieses wird für ein Land der Riesen* gehalten. Riesen wohnten früher darin, und die Ammoniter nennen sie Samsummiter*:", footnotes: ["hebr. Refaïm", "℘ 1Mo 14,5"] },
      { number: 21, text: "ein großes und zahlreiches und hochgewachsenes Volk, wie die Enakiter. Und der HERR vernichtete sie vor ihnen, und sie verdrängten sie und wohnten an ihrer Stelle," },
      { number: 22, text: "so wie er es für die Söhne Esau getan hat, die in Seïr wohnen, vor denen er die Horiter vernichtete, so dass sie sie verdrängten und an ihrer Stelle wohnten bis auf diesen Tag*.", footnotes: ["℘ 1Mo 36,20-30"] },
      { number: 23, text: "Und was die Awiter betrifft*, die in Dörfern bis Gaza* hin wohnten; die Kaftoriter, die aus Kaftor ausgezogen waren*, haben sie vernichtet und wohnten an ihrer Stelle. —", footnotes: ["℘ Jos 13,3", "℘ 1Mo 10,19; Jos 10,41; 11,22; 15,47; Ri 1,18", "℘ 1Mo 10,14; Am 9,7"] },
      { number: 24, text: "Macht euch auf, brecht auf* und zieht über den Fluss Arnon*! Siehe, ich habe den Amoriter Sihon, den König von Heschbon, und sein Land in deine Hand gegeben. Fang an, nimm es in Besitz und lass dich in einen Krieg mit ihm ein!", footnotes: ["w. reißt euch die Zeltpflöcke heraus", "℘ 4Mo 21,12.13"] },
      { number: 25, text: "An diesem Tag will ich anfangen, Schrecken und Furcht vor dir auf die Völker unter dem ganzen Himmel zu legen: Wenn sie die Nachricht von dir hören, werden sie vor dir zittern und beben*.", footnotes: ["℘ Kap. 11,25; 28,10; 4Mo 22,3; Jos 10,2"] },
      { number: 26, text: "Da sandte ich Boten aus der Wüste Kedemot* an Sihon, den König von Heschbon, mit Worten des Friedens* und ließ ihm sagen:", footnotes: ["℘ Jos 13,18", "℘ Kap. 20,10"] },
      { number: 27, text: "Ich möchte durch dein Land ziehen auf der Straße! Nur auf der Straße will ich gehen, ich will weder zur Rechten noch zur Linken abweichen*.", footnotes: ["℘ 4Mo 21,21.22"] },
      { number: 28, text: "Nahrung sollst du mir für Geld verkaufen, dass ich esse, und Wasser sollst du mir für Geld geben, dass ich trinke. Ich will nur hindurchziehen* mit meinen Füßen —", footnotes: ["℘ 4Mo 20,17.19"] },
      { number: 29, text: "wie mir die Söhne Esau getan haben, die in Seïr wohnen, und die Moabiter, die in Ar wohnen* —, bis ich über den Jordan hinüberziehe in das Land, das der HERR, unser Gott, uns gibt*.", footnotes: ["℘ Kap. 23,4.5", "℘ Kap. 1,8"] },
      { number: 30, text: "Aber Sihon, der König von Heschbon, wollte uns nicht bei sich durchziehen lassen*. Denn der HERR, dein Gott, hatte seinen Geist verhärtet und sein Herz verstockt*, damit er ihn in deine Hand gäbe, so wie es heute ist.", footnotes: ["℘ 4Mo 21,23.33.34", "℘ 2Mo 4,21; 7,14; Jos 11,20; 2Chr 10,15"] },
      { number: 31, text: "Und der HERR sprach zu mir: Siehe, ich habe begonnen, Sihon und sein Land vor dir dahinzugeben. Fang an, nimm es in Besitz, damit dir sein Land gehört*!", footnotes: ["w. um sein Land in Besitz zu nehmen. — Andere halten das vorherstehende »nimm in Besitz« für versehentliche Doppelschreibung (vgl. V. 24c), streichen die Befehlsform und üs. V. 31b: Fang an, sein Land in Besitz zu nehmen"] },
      { number: 32, text: "*Und Sihon zog zum Kampf aus, uns entgegen nach Jahaz*, er und all sein Volk.", footnotes: ["℘ V. 32-37: Kap. 3,1-10; Jos 12,1-6", "℘ 4Mo 21,23"] },
      { number: 33, text: "Aber der HERR, unser Gott, gab ihn vor uns dahin; und wir schlugen ihn und seine Söhne und all sein Volk*.", footnotes: ["℘ Kap. 29,6; 4Mo 21,24"] },
      { number: 34, text: "In jener Zeit nahmen wir alle seine Städte ein, und wir vollstreckten den Bann an jeder Stadt, an Männern, Frauen und Kindern; wir ließen keinen übrig, der entkam*.", footnotes: ["w. wir ließen keinen Entkommenen übrig\n℘ Jos 6,21; 8,26; 10,28-40"] },
      { number: 35, text: "Nur das Vieh erbeuteten wir für uns und die Beute der Städte, die wir einnahmen*.", footnotes: ["℘ Kap. 20,14; Jos 8,2.27"] },
      { number: 36, text: "Von Aroër*, das am Ufer des Flusses Arnon liegt, und von der Stadt, die im Flusstal* liegt, bis Gilead gab es keine Stadt, die uns zu stark* gewesen wäre; alles gab der HERR, unser Gott, vor uns dahin*.", footnotes: ["℘ Ri 11,26", "o. im Bachtal; vgl. Anm. zu V. 13", "w. hoch", "℘ Jos 21,44"] },
      { number: 37, text: "Nur dem Land der Söhne Ammon, dem ganzen Gebiet am Fluss Jabbok*, hast du dich nicht genähert noch den Städten des Gebirges, nach allem*, was der HERR, unser Gott, geboten hatte*.", footnotes: ["w. an der ganzen Seite des Flusses Jabbok", "so mit einer aram. Üs.; Mas. T.: und allem hast du dich nicht genähert", "℘ V. 19"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "*Und wir wandten uns und zogen den Weg nach Baschan hinauf. Und Og, der König von Baschan, zog zum Kampf aus, uns entgegen nach Edreï*, er und all sein Volk.", heading: "Sieg über Og von Baschan", footnotes: ["℘ V. 1-10: Kap. 2,32-37; V. 1-17: Jos 12,1-6", "℘ Kap. 1,4"] },
      { number: 2, text: "Und der HERR sprach zu mir: Fürchte ihn nicht*, denn in deine Hand habe ich ihn und all sein Volk und sein Land gegeben! Und tu mit ihm, wie du mit Sihon, dem König der Amoriter, getan hast, der in Heschbon wohnte*!", footnotes: ["℘ Jos 10,8", "o. thronte; d. h. herrschte"] },
      { number: 3, text: "Und der HERR, unser Gott, gab auch Og, den König von Baschan, und all sein Volk in unsere Hand. Und wir schlugen ihn, bis ihm keiner übrig blieb, der entkam*.", footnotes: ["℘ Kap. 29,6; 4Mo 21,35"] },
      { number: 4, text: "Und alle seine Städte nahmen wir in jener Zeit ein. Es gab keine Stadt, die wir ihnen nicht nahmen: sechzig Städte, den ganzen Landstrich Argob, das Königreich des Og in Baschan*;", footnotes: ["℘ Jos 13,30; 1Kö 4,13"] },
      { number: 5, text: "alle diese Städte waren befestigt mit hohen Mauern, Toren und Riegeln; abgesehen von den sehr vielen offenen Landstädten." },
      { number: 6, text: "Und wir vollstreckten den Bann an ihnen, wie wir es bei Sihon, dem König von Heschbon, getan hatten. Wir vollstreckten an ihrer ganzen Bevölkerung den Bann: an Männern, Frauen und Kindern." },
      { number: 7, text: "Aber alles Vieh und die Beute der Städte erbeuteten wir für uns." },
      { number: 8, text: "*So nahmen wir in jener Zeit aus der Hand der beiden Könige der Amoriter das Land, das jenseits des Jordan ist, vom Fluss* Arnon bis an den Berg Hermon*", footnotes: ["℘ V. 8-17: 4Mo 32,33-42; Jos 13,8-33", "o. Bachtal; vgl. Anm. zu Kap. 2,13", "℘ Kap. 4,47-49; Ps 42,7"] },
      { number: 9, text: "— die Sidonier nennen den Hermon Sirjon*, und die Amoriter nennen ihn Senir —*:", footnotes: ["℘ Ps 29,6", "℘ 1Chr 5,23; Hl 4,8; Hes 27,5"] },
      { number: 10, text: "alle Städte der Ebene und das ganze Gilead und das ganze Baschan bis nach Salcha und Edreï, den Städten im Königreich des Og in Baschan*.", footnotes: ["℘ Jos 13,30; 1Kö 4,13"] },
      { number: 11, text: "Denn nur Og, der König von Baschan, war von dem Rest der Riesen* noch übrig geblieben*. Siehe, sein Bett*, ein Bett aus Eisen, ist es nicht in Rabba, der Hauptstadt der Söhne Ammon?* Seine Länge beträgt neun Ellen und seine Breite vier Ellen, nach der Elle eines Mannes*.", footnotes: ["hebr. Refaïm", "℘ 1Mo 14,5; Jos 12,4", "d. i. wohl sein Sarg", "℘ 2Sam 11,1; Jer 49,2", "d. h. nach dem gewöhnlichen Ellenmaß\n℘ 1Sam 17,4"] },
      { number: 12, text: "Dieses Land nahmen wir zu jener Zeit in Besitz. Das Land von Aroër an, das am Fluss* Arnon liegt, und die Hälfte des Gebirges Gilead und seine Städte gab ich den Rubenitern und den Gaditern.", heading: "Verteilung des Ostjordanlandes", footnotes: ["o. Bachtal; vgl. Anm. zu Kap. 2,13"] },
      { number: 13, text: "Und den Rest von Gilead und das ganze Baschan, das Königreich des Og, gab ich dem halben Stamm Manasse*, den ganzen Landstrich Argob. Dieses ganze Baschan wird das Land der Riesen* genannt.", footnotes: ["℘ Kap. 29,7; 2Kö 10,33", "hebr. Refaïm"] },
      { number: 14, text: "Jaïr, der Sohn Manasses, nahm den ganzen Landstrich Argob bis zur Grenze der Geschuriter und der Maachatiter* und nannte sie, die Ortschaften von Baschan, nach seinem Namen: Zeltdörfer Jaïrs*; so heißen sie bis auf diesen Tag.", footnotes: ["℘ 2Sam 10,6; 23,34", "℘ 2Sam 20,26"] },
      { number: 15, text: "Und dem Machir gab ich Gilead*.", footnotes: ["℘ Jos 17,1; 1Chr 2,22"] },
      { number: 16, text: "Und den Rubenitern und den Gaditern gab ich das Land von Gilead bis zum Fluss* Arnon, und zwar bis zur Mitte des Flusstales als Grenze* und bis zum Fluss* Jabbok, der Grenze der Söhne Ammon,", footnotes: ["o. Bachtal; vgl. Anm. zu Kap. 2,13", "o. bis zur Mitte des Flusses und das Angrenzende; d. h. dann: bis zum Uferrand", "o. bis zur Mitte des Flusses und das Angrenzende; d. h. dann: bis zum Uferrand"] },
      { number: 17, text: "und die Ebene* mit dem Jordan als Grenze*, von Kinneret* bis zum Meer der Ebene, dem Salzmeer*, unterhalb der Abhänge des Pisga nach Osten zu*.", footnotes: ["s. Anm. zu Kap. 1,1", "o. mit dem Jordan und das Angrenzende; d. h. dann: bis zum Uferrand", "℘ 4Mo 34,11", "℘ Jos 3,16; 2Kö 14,25", "℘ Kap. 4,49"] },
      { number: 18, text: "Und ich gebot euch zu jener Zeit und sagte: Der HERR, euer Gott, hat euch dieses Land gegeben, es in Besitz zu nehmen*. Gerüstet sollt ihr vor euren Brüdern, den Söhnen Israel, hinüberziehen, alle Kriegstüchtigen.", footnotes: ["℘ Kap. 5,31; 6,1; 9,6; 12,1; 15,4; 19,2.14; 21,1; 25,19; 1Mo 15,7; 4Mo 33,53; Jos 1,11.15"] },
      { number: 19, text: "Nur eure Frauen und eure Kinder und euer Vieh — ich weiß, dass ihr viel Vieh habt — sollen in euren Städten bleiben, die ich euch gegeben habe*,", footnotes: ["℘ 4Mo 32,16.26"] },
      { number: 20, text: "bis der HERR euren Brüdern Ruhe verschafft wie euch und auch sie das Land in Besitz nehmen, das der HERR, euer Gott, ihnen jenseits des Jordan gibt. Dann sollt ihr zurückkehren, jeder zu seinem Besitz, den ich euch gegeben habe*.", footnotes: ["℘ 4Mo 32,18; Jos 22,2.9"] },
      { number: 21, text: "Und dem Josua* gebot ich zu jener Zeit und sprach: Deine Augen haben alles gesehen, was der HERR, euer Gott, diesen beiden Königen getan hat. So wird der HERR allen Königreichen tun, zu denen du hinüberziehst*.", footnotes: ["℘ 4Mo 27,18-23", "℘ Kap. 7,19"] },
      { number: 22, text: "Fürchtet sie nicht! Denn der HERR, euer Gott, er ist es, der für euch kämpft*.", footnotes: ["℘ Kap. 1,30; Jos 23,10; 2Chr 20,17"] },
      { number: 23, text: "Und ich flehte zu jener Zeit zum HERRN um Erbarmen:", heading: "Mose darf nicht nach Kanaan kommen" },
      { number: 24, text: "Herr, HERR, du hast begonnen, deinen Knecht deine Größe und deine starke Hand sehen zu lassen*. Denn wo im Himmel und auf Erden ist ein Gott, der so etwas wie deine Werke und wie deine Machttaten tun könnte*?", footnotes: ["℘ Kap. 11,2", "℘ 2Mo 15,11; 4Mo 23,23; 2Sam 7,22; Ps 71,19; 86,8"] },
      { number: 25, text: "Ich möchte doch auch hinüberziehen und das gute Land sehen, das jenseits des Jordan liegt, dieses gute Bergland und den Libanon*.", footnotes: ["℘ Hes 20,6"] },
      { number: 26, text: "Aber der HERR war euretwegen über mich erzürnt* und hörte nicht auf mich. Und der HERR sprach zu mir: Lass es genug sein! Rede mir nicht mehr weiter von dieser Sache!*", footnotes: ["℘ Kap. 1,37.38", "℘ 2Kor 12,8.9"] },
      { number: 27, text: "Steige auf den Gipfel des Pisga* und erhebe deine Augen nach Westen und nach Norden, nach Süden und nach Osten und sieh mit deinen Augen! Denn du wirst nicht über diesen Jordan gehen*.", footnotes: ["℘ Kap. 34,1; 4Mo 27,12", "℘ Kap. 1,37.38"] },
      { number: 28, text: "Und beauftrage Josua, stärke ihn und festige ihn! Denn er soll vor diesem Volk hinüberziehen*, und er soll ihnen das Land, das du sehen wirst, als Erbe austeilen*. —", footnotes: ["℘ Jos 1,2", "℘ Kap. 1,37.38"] },
      { number: 29, text: "Und wir blieben im Tal, Bet-Peor gegenüber*.", footnotes: ["℘ Kap. 4,46; 34,6"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "Und nun, Israel, höre auf die Ordnungen und auf die Rechtsbestimmungen, die ich euch zu tun lehre*, damit ihr lebt* und hineinkommt und das Land in Besitz nehmt, das der HERR, der Gott eurer Väter, euch gibt*!", heading: "Aufforderung zum Gehorsam — Warnung vor Götzendienst", footnotes: ["℘ V. 40; Kap. 5,1.31; 6,1; 7,11; 8,11; 11,32; 3Mo 19,19.37; Jer 11,6", "℘ Kap. 6,24; 3Mo 18,5", "℘ Kap. 1,8"] },
      { number: 2, text: "Ihr sollt nichts hinzufügen zu dem Wort, das ich euch gebiete, und sollt nichts davon wegnehmen*, damit ihr die Gebote des HERRN, eures Gottes, haltet, die ich euch gebiete*!", footnotes: ["℘ Kap. 13,1; Jer 26,2", "℘ Kap. 5,29.32; Jos 1,7"] },
      { number: 3, text: "Eure Augen haben gesehen, was der HERR wegen des Baal-Peor* getan hat. Denn jeden, der dem Baal-Peor nachgelaufen ist, den hat der HERR, dein Gott, aus deiner Mitte vernichtet*.", footnotes: ["o. gegen den Baal-Peor; o. in Baal-Peor", "℘ 4Mo 25,3-9; Jos 22,17"] },
      { number: 4, text: "Ihr aber, die ihr dem HERRN, eurem Gott, anhinget, ihr seid heute alle am Leben*.", footnotes: ["℘ Kap. 30,20; Jos 23,8"] },
      { number: 5, text: "Siehe, ich habe euch Ordnungen und Rechtsbestimmungen gelehrt, so wie der HERR, mein Gott, mir geboten hat*, damit ihr danach handelt mitten in dem Land*, in das ihr kommt, um es in Besitz zu nehmen.", footnotes: ["℘ Hes 20,11; Hebr 3,5", "℘ V. 40; Kap. 5,1.31; 6,1; 7,11; 8,11; 11,32; 3Mo 19,19.37; Jer 11,6"] },
      { number: 6, text: "So bewahrt und tut sie! Denn das ist eure Weisheit und eure Einsicht* in den Augen der Völker, die all diese Ordnungen hören. Und sie werden sagen: Ein wahrhaft weises und verständiges Volk ist diese große Nation*!", footnotes: ["℘ Hi 28,28; Ps 19,8; Spr 1,4-7", "℘ Ps 119,98; Spr 14,34"] },
      { number: 7, text: "Denn wo gibt es eine große Nation, die Götter hätte, die* ihr so nahe wären wie der HERR, unser Gott, in allem, worin wir zu ihm rufen*?", footnotes: ["o. einen Gott hätte, der", "℘ Kap. 33,29; Ps 145,18; 148,14"] },
      { number: 8, text: "Und wo gibt es eine große Nation, die so gerechte Ordnungen und Rechtsbestimmungen hätte wie dieses ganze Gesetz, das ich euch heute vorlege*?", footnotes: ["℘ Neh 9,13; Ps 119,138; Jes 42,21; Röm 7,12"] },
      { number: 9, text: "Nur hüte dich und hüte deine Seele* sehr, dass du die Dinge nicht vergisst, die deine Augen gesehen haben, und dass sie nicht aus deinem Herzen schwinden alle Tage deines Lebens!* Und tue sie deinen Kindern und deinen Kindeskindern kund*:", footnotes: ["o. dein Leben\n℘ Jos 23,11; Jer 17,21", "℘ Spr 4,21", "o. Und gib sie deinen Kindern . . . zu erkennen\n℘ Kap. 6,7; 11,19; 1Mo 18,19; Jes 38,19"] },
      { number: 10, text: "An dem Tag, an dem du vor dem HERRN, deinem Gott, am Horeb standest, als der HERR zu mir sprach: »Versammle mir das Volk, dass ich sie meine Worte hören lasse*, die sie lernen sollen, um mich zu fürchten all die Tage, solange sie auf dem Erdboden leben*, und die sie ihre Kinder lehren sollen*!«", footnotes: ["℘ 2Mo 19,9-11", "℘ Kap. 5,29; 6,2; 14,23; 17,19; 31,12", "o. damit sie mich fürchten lernen . . . und ihre Kinder belehren\n℘ Kap. 6,7; 11,19; 1Mo 18,19; Jes 38,19"] },
      { number: 11, text: "Da tratet ihr hinzu und standet unten am Berg. Der Berg aber brannte im Feuer bis ins Herz des Himmels, und da war Finsternis, Gewölk und Dunkel*.", footnotes: ["℘ 2Mo 19,9.17.18; 2Sam 22,10"] },
      { number: 12, text: "Und der HERR redete zu euch mitten aus dem Feuer*. Die Stimme der Worte hörtet ihr, aber ihr saht keine Gestalt, nur eine Stimme war zu hören*.", footnotes: ["℘ Kap. 5,4.22; 9,10; 10,4; 1Kö 19,12", "℘ V. 36"] },
      { number: 13, text: "Und er verkündigte euch seinen Bund*, den zu halten er euch gebot: die zehn Worte. Und er schrieb sie auf zwei steinerne Tafeln*.", footnotes: ["℘ Kap. 5,2", "℘ Kap. 5,22; 9,10; 2Mo 31,18; 1Kö 8,9"] },
      { number: 14, text: "Und mir gebot der HERR zu jener Zeit, euch Ordnungen und Rechtsbestimmungen zu lehren, damit ihr sie hieltet in dem Land, in das ihr hinüberzieht, um es in Besitz zu nehmen*.", footnotes: ["℘ Kap. 11,8; 2Mo 21,1; Mal 3,22"] },
      { number: 15, text: "So hütet eure Seelen* sehr* — denn ihr habt keinerlei Gestalt gesehen an dem Tag, als der HERR am Horeb mitten aus dem Feuer* zu euch redete* —,", footnotes: ["o. euer Leben", "℘ V. 36", "℘ V. 36", "℘ V. 36"] },
      { number: 16, text: "dass ihr nicht zu eurem Verderben handelt* und euch ein Götterbild* macht* in Gestalt irgendeines Götzenbildes, das Abbild eines männlichen oder eines weiblichen Wesens,", footnotes: ["℘ 2Mo 32,7", "d. i. ein aus Stein gehauenes o. aus Holz geschnitztes Bild", "℘ Kap. 16,22; 27,15; 2Mo 20,4; Hes 8,10"] },
      { number: 17, text: "das Abbild irgendeines Tieres, das es auf der Erde gibt, das Abbild irgendeines geflügelten Vogels, der am Himmel fliegt," },
      { number: 18, text: "das Abbild von irgendetwas, das auf dem Erdboden kriecht, das Abbild irgendeines Fisches, der im Wasser unter der Erde ist*,", footnotes: ["℘ Röm 1,23"] },
      { number: 19, text: "und dass du deine Augen nicht zum Himmel erhebst und, wenn du die Sonne und den Mond und die Sterne, das ganze Heer des Himmels siehst, dich verleiten lässt und dich vor ihnen niederwirfst und ihnen dienst*, die doch der HERR, dein Gott, allen Völkern unter dem ganzen Himmel zugeteilt hat*!", footnotes: ["℘ Kap. 17,3; 2Kö 17,16; 2Chr 33,3; Hi 31,26.27; Jer 8,2; Zef 1,5", "℘ 1Mo 1,14.15"] },
      { number: 20, text: "Euch aber hat der HERR genommen und euch herausgeführt aus dem eisernen Schmelzofen, aus Ägypten*, damit ihr das Volk seines Erbteils wäret*, so wie es heute ist.", footnotes: ["℘ 2Mo 1,14; 1Kö 8,51; Jer 11,4", "w. ihm zum Erbteilsvolk würdet\n℘ 2Mo 19,5.6"] },
      { number: 21, text: "Und der HERR war euretwegen über mich erzürnt, und er schwor, dass ich nicht über den Jordan gehen und nicht in das gute Land kommen sollte, das der HERR, dein Gott, dir als Erbteil gibt*.", footnotes: ["℘ Kap. 15,4; 19,3.10; 20,16; 21,23; 24,4"] },
      { number: 22, text: "Denn ich sterbe in diesem Land*, ich gehe nicht über den Jordan*. Ihr aber werdet hinüberziehen und dieses gute Land in Besitz nehmen.", footnotes: ["℘ 4Mo 31,2", "℘ Kap. 1,37"] },
      { number: 23, text: "Hütet euch, dass ihr ja nicht den Bund des HERRN, eures Gottes, vergesst*, den er mit euch geschlossen hat*, und euch ein Götterbild* macht* in der Gestalt von irgendetwas, das der HERR, dein Gott, dir verboten hat*.", footnotes: ["℘ 2Kö 17,38", "℘ Röm 1,23", "d. i. ein aus Stein gehauenes o. aus Holz geschnitztes Bild", "℘ Röm 1,23", "℘ Röm 1,23"] },
      { number: 24, text: "Denn der HERR, dein Gott, ist ein verzehrendes Feuer*, ein eifersüchtiger Gott*!", footnotes: ["℘ Kap. 9,3; 2Mo 24,17; Jes 10,17; 30,33", "℘ Kap. 5,9; 6,15; Nah 1,2"] },
      { number: 25, text: "Wenn du Kinder und Kindeskinder zeugst und ihr im Lande alteingesessen seid und ihr zu eurem Verderben handelt und euch ein Götterbild* macht* in der Gestalt irgendeines Lebewesens und tut, was böse ist in den Augen des HERRN, deines Gottes, ihn zu reizen*,", footnotes: ["d. i. ein aus Stein gehauenes o. aus Holz geschnitztes Bild", "℘ Kap. 16,22; 27,15; 2Mo 20,4; Hes 8,10", "℘ Ri 2,11.12; Ps 78,58"] },
      { number: 26, text: "so rufe ich heute den Himmel und die Erde als Zeugen gegen euch auf*, dass ihr mit Sicherheit schnell weggerafft werdet aus dem Land, in das ihr über den Jordan zieht, um es in Besitz zu nehmen. Ihr werdet eure Tage darin nicht verlängern, sondern völlig vernichtet werden*.", footnotes: ["℘ Kap. 30,19; 31,28; 32,1", "℘ Kap. 8,19; 28,20; 30,18.19; Jos 23,16"] },
      { number: 27, text: "Und der HERR wird euch unter die Völker zerstreuen, und ihr werdet übrig bleiben, ein geringes Häuflein* unter den Nationen, wohin der HERR euch führen wird*.", footnotes: ["w. gezählte Männer", "℘ Kap. 28,62-64; 3Mo 26,33; Neh 1,8; Hes 11,16; Hos 9,17"] },
      { number: 28, text: "Dort werdet ihr Göttern dienen, dem Werk von Menschenhänden, aus Holz und Stein*, die nicht sehen und nicht hören, nicht essen und nicht riechen können*.", footnotes: ["℘ Kap. 28,36.64; Jer 16,13", "℘ Ps 115,4-6; Jes 44,9; Jer 10,5"] },
      { number: 29, text: "Dann werdet ihr von dort aus den HERRN, deinen Gott, suchen. Und du wirst ihn finden, wenn du mit deinem ganzen Herzen und mit deiner ganzen Seele nach ihm fragen wirst*.", footnotes: ["o. denn du wirst mit deinem ganzen Herzen und mit deiner ganzen Seele nach ihm fragen\n℘ 1Sam 7,3; 2Chr 15,2; Ps 119,2; Jer 29,13; Joe 2,12"] },
      { number: 30, text: "Wenn du in Not bist und wenn alle diese Dinge dich getroffen haben am Ende der Tage*, wirst du zum HERRN, deinem Gott, umkehren und auf seine Stimme hören*.", footnotes: ["℘ Dan 10,14", "℘ Neh 1,9; Kla 3,40"] },
      { number: 31, text: "Denn ein barmherziger Gott ist der HERR, dein Gott*. Er wird dich nicht aufgeben und dich nicht vernichten und wird den Bund deiner Väter nicht vergessen, den er ihnen geschworen hat*.", footnotes: ["℘ 2Mo 34,6; Neh 9,31", "℘ 2Mo 6,8; 3Mo 26,42.45"] },
      { number: 32, text: "Denn frage doch nach den früheren Tagen, die vor dir gewesen sind*, von dem Tag an, als Gott den Menschen auf der Erde geschaffen hat, und von einem Ende des Himmels bis zum anderen Ende des Himmels, ob je eine solch große Sache geschehen oder ob dergleichen gehört worden sei.", footnotes: ["℘ Hi 8,8"] },
      { number: 33, text: "Hat je ein Volk die Stimme Gottes mitten aus dem Feuer reden hören, wie du sie gehört hast, und ist am Leben geblieben?* —", footnotes: ["℘ Kap. 5,22-24"] },
      { number: 34, text: "Oder hat je ein Gott versucht hinzugehen, um sich eine Nation mitten aus einer anderen Nation zu holen durch Prüfungen, durch Zeichen und durch Wunder* und durch Krieg und mit starker Hand und mit ausgestrecktem Arm und durch große Schreckenstaten nach allem, was der HERR, euer Gott, in Ägypten vor deinen Augen für euch getan hat?*", footnotes: ["o. Wahrzeichen", "℘ Kap. 1,30; 26,8; 2Mo 6,6.7; 10,21; Jos 24,7; Ps 78,12; Jer 32,21"] },
      { number: 35, text: "Du hast es zu sehen bekommen, damit du erkennst, dass der HERR der alleinige Gott ist. Außer ihm gibt es sonst keinen*.", footnotes: ["℘ Kap. 6,4; 7,9; 1Sam 2,2; 2Sam 7,22; 1Chr 17,20; Jes 43,10; Mk 12,32"] },
      { number: 36, text: "Vom Himmel her hat er dich seine Stimme hören lassen, um dich zu unterweisen*. Und auf der Erde hat er dich sein großes Feuer sehen lassen*, und mitten aus dem Feuer *hast du seine Worte gehört*.", footnotes: ["℘ 2Mo 20,22", "℘ 2Mo 19,18", "Mit geringfügiger Korrektur üs. andere: hast du seine Worte gehört 37 und bist am Leben geblieben. Weil er", "℘ V. 12.15"] },
      { number: 37, text: "Und weil er* deine Väter geliebt* und ihre Nachkommen nach ihnen erwählt hat, hat er dich mit seinem Angesicht, mit seiner großen Kraft aus Ägypten herausgeführt*,", footnotes: ["Mit geringfügiger Korrektur üs. andere: hast du seine Worte gehört 37 und bist am Leben geblieben. Weil er", "℘ Jes 43,4; Mal 1,2; Röm 11,28", "℘ Kap. 7,6-8; 10,15; 2Mo 12,41.51; 4Mo 20,16"] },
      { number: 38, text: "um Nationen vor dir zu vertreiben, größer und stärker als du*, um dich herzubringen und dir ihr Land als Erbteil zu geben*, so wie es heute ist.", footnotes: ["℘ Kap. 7,1; 9,1; 11,23", "℘ 2Chr 20,7; Ps 44,2.3"] },
      { number: 39, text: "So erkenne denn heute und nimm dir zu Herzen, dass der HERR der alleinige Gott ist im Himmel oben und auf der Erde unten*, keiner sonst*!", footnotes: ["℘ Jos 2,11", "℘ Kap. 6,4; 7,9; 1Sam 2,2; 2Sam 7,22; 1Chr 17,20; Jes 43,10; Mk 12,32"] },
      { number: 40, text: "Und halte seine Ordnungen und seine Gebote*, die ich dir heute gebiete, damit es dir und deinen Kindern nach dir gut geht und damit du deine Tage verlängerst in dem Land, das der HERR, dein Gott, dir für immer* gibt*.", footnotes: ["℘ V. 1.5; Kap. 5,10", "w. für alle Tage", "℘ Kap. 11,9.21; 25,15; 2Mo 20,12; Jer 7,23; 35,18.19"] },
      { number: 41, text: "Damals sonderte Mose drei Städte aus jenseits des Jordan, gegen Sonnenaufgang*,", heading: "Zufluchtsstädte im Ostjordanland", footnotes: ["℘ 4Mo 35,14"] },
      { number: 42, text: "damit ein Totschläger dahin fliehen kann, der seinen Nächsten unabsichtlich* erschlagen hat und ihn nicht schon vorher* hasste — dass er in eine von diesen Städten fliehen und am Leben bleiben kann*:", footnotes: ["w. ohne Wissen", "w. seit gestern und vorgestern", "℘ Kap. 19,2-7"] },
      { number: 43, text: "Bezer in der Wüste, im Land der Ebene, für die Rubeniter* und Ramot in Gilead für die Gaditer* und Golan in Baschan für die Manassiter*.", footnotes: ["℘ Jos 20,8; 1Kö 22,3; 1Chr 6,63.65", "℘ Kap. 6,4; 7,9; 1Sam 2,2; 2Sam 7,22; 1Chr 17,20; Jes 43,10; Mk 12,32", "℘ Jos 21,27"] },
      { number: 44, text: "*Und dies ist das Gesetz, das Mose den Söhnen Israel vorlegte.", heading: "Einleitung zum Gesetz", footnotes: ["℘ V. 46-49: Jos 12,1-6"] },
      { number: 45, text: "Dies sind die Zeugnisse, die Ordnungen und die Rechtsbestimmungen, die Mose zu den Söhnen Israel redete, als sie aus Ägypten zogen," },
      { number: 46, text: "jenseits des Jordan im Tal, Bet-Peor gegenüber*, im Land des Sihon, des Königs der Amoriter, der in Heschbon wohnte*, den Mose und die Söhne Israel geschlagen haben, als sie aus Ägypten zogen*.", footnotes: ["℘ Kap. 1,5; 3,29; 34,6", "o. thronte; d. h. herrschte", "℘ 4Mo 21,23.24"] },
      { number: 47, text: "Und sie nahmen sein Land in Besitz und das Land des Og, des Königs von Baschan*, das Land der beiden Könige der Amoriter, die jenseits des Jordan wohnten, gegen Sonnenaufgang,", footnotes: ["℘ 4Mo 21,33-35; Jos 24,12; Neh 9,22"] },
      { number: 48, text: "von Aroër an, das am Ufer des Flusses Arnon liegt, bis an den Berg Sion, das ist der Hermon*,", footnotes: ["℘ Kap. 3,8"] },
      { number: 49, text: "und die ganze Ebene* jenseits des Jordan, nach Osten zu* und bis an das Meer der Ebene* unterhalb der Abhänge des Pisga*.", footnotes: ["s. Anm. zu Kap. 1,1", "w. zum Aufgang der Sonne", "d. i. das Tote Meer\n℘ Hes 47,8", "℘ Kap. 3,17"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "Und Mose rief ganz Israel herbei und sprach zu ihnen*: Höre, Israel, die Ordnungen und die Rechtsbestimmungen, die ich heute vor euren Ohren rede! Lernt sie und achtet darauf, sie zu tun*!", heading: "Die Zehn Gebote", footnotes: ["℘ Kap. 1,1", "℘ Kap. 4,1; 11,1; 12,1; 28,15.45; 2Mo 15,26"] },
      { number: 2, text: "Der HERR, unser Gott, hat am Horeb einen Bund mit uns geschlossen*.", footnotes: ["℘ Kap. 1,6; 4,13; 28,69; 2Mo 24,8; 34,10; 2Kö 17,35; Jer 34,13"] },
      { number: 3, text: "Nicht mit unsern Vätern hat der HERR diesen Bund geschlossen, sondern mit uns, die wir heute hier alle am Leben sind*.", footnotes: ["℘ Kap. 29,9-14"] },
      { number: 4, text: "Von Angesicht zu Angesicht hat der HERR auf dem Berg mitten aus dem Feuer mit euch geredet* —", footnotes: ["℘ V. 22; Kap. 4,12; 4Mo 14,14"] },
      { number: 5, text: "ich stand zwischen dem HERRN und euch zu jener Zeit, um euch das Wort des HERRN zu verkünden*; denn ihr fürchtetet euch vor dem Feuer und stieget nicht auf den Berg* —, indem er sprach:", footnotes: ["℘ 2Mo 19,25; Gal 3,20", "℘ 2Mo 19,16"] },
      { number: 6, text: "*Ich bin der HERR, dein Gott, der ich dich aus dem Land Ägypten, aus dem Sklavenhaus, herausgeführt habe*.", footnotes: ["℘ V. 6-21: 2Mo 20,1-17", "℘ Kap. 7,8; 8,14; Jer 11,4; Mi 6,4"] },
      { number: 7, text: "Du sollst keine anderen Götter haben neben mir*. —", footnotes: ["s. die Anmerkungen zu 2Mo 20,3\n℘ Kap. 6,14; 11,16"] },
      { number: 8, text: "Du sollst dir kein Götterbild* machen, irgendein Abbild dessen, was oben im Himmel oder was unten auf der Erde oder was im Wasser unter der Erde ist.", footnotes: ["d. i. ein aus Stein gehauenes o. aus Holz geschnitztes Bild"] },
      { number: 9, text: "Du sollst dich vor ihnen nicht niederwerfen und ihnen nicht dienen. Denn ich, der HERR, dein Gott, bin ein eifersüchtiger Gott*, der die Schuld der Väter heimsucht an den Kindern und an der dritten und vierten Generation von denen, die mich hassen*,", footnotes: ["℘ Kap. 4,24", "℘ Kap. 7,10"] },
      { number: 10, text: "der aber Gnade erweist auf Tausende hin denen, die mich lieben und meine Gebote halten*. —", footnotes: ["℘ Kap. 4,40; 7,9.12"] },
      { number: 11, text: "Du sollst den Namen des HERRN, deines Gottes, nicht zu Nichtigem* aussprechen. Denn der HERR wird den nicht ungestraft lassen, der seinen Namen zu Nichtigem* ausspricht. —", footnotes: ["o. zu Falschem; o. zu Lügenhaftem", "o. zu Falschem; o. zu Lügenhaftem"] },
      { number: 12, text: "Beachte den Sabbattag, um ihn heilig zu halten, so wie der HERR, dein Gott, es dir geboten hat!" },
      { number: 13, text: "Sechs Tage sollst du arbeiten und all deine Arbeit tun*;", footnotes: ["℘ Lk 13,14"] },
      { number: 14, text: "aber der siebte Tag ist Sabbat für den HERRN, deinen Gott. Du sollst an ihm keinerlei Arbeit tun, du und dein Sohn und deine Tochter und dein Sklave und deine Sklavin und dein Rind und dein Esel und all dein Vieh und der Fremde bei dir, der innerhalb deiner Tore wohnt, damit dein Sklave und deine Sklavin ruhen wie du*.", footnotes: ["℘ Mk 2,27"] },
      { number: 15, text: "Und denke daran, dass du Sklave warst im Land Ägypten und dass der HERR, dein Gott, dich mit starker Hand und mit ausgestrecktem Arm von dort herausgeführt hat*! Darum hat der HERR, dein Gott, dir geboten*, den Sabbattag zu feiern. —", footnotes: ["℘ Kap. 9,12; 26,8; 2Mo 6,6; 13,3", "℘ Kap. 15,15; 16,12; 24,18.22"] },
      { number: 16, text: "Ehre deinen Vater und deine Mutter, wie der HERR, dein Gott, es dir geboten hat, damit deine Tage lange währen* und damit es dir gut geht in dem Land, das der HERR, dein Gott, dir gibt*! —", footnotes: ["℘ Kap. 6,2", "℘ V. 29.33; Spr 3,1.2"] },
      { number: 17, text: "Du sollst nicht töten. —" },
      { number: 18, text: "Und du sollst nicht ehebrechen. —" },
      { number: 19, text: "Und du sollst nicht stehlen. —" },
      { number: 20, text: "Und du sollst kein falsches Zeugnis gegen deinen Nächsten ablegen*. —", footnotes: ["w. du sollst nicht als falscher Zeuge antworten\n℘ Kap. 19,16-19"] },
      { number: 21, text: "Und du sollst die Frau deines Nächsten nicht begehren*. Und du sollst dich nicht gelüsten lassen* nach dem Haus deines Nächsten noch nach seinem Feld noch nach seinem Knecht noch nach seiner Magd noch nach seinem Rind noch nach seinem Esel noch nach allem, was dein Nächster hat.", footnotes: ["℘ Hi 31,9; 2Sam 11,2-4; Spr 6,25", "℘ Röm 7,7"] },
      { number: 22, text: "Diese Worte redete der HERR auf dem Berg zu eurer ganzen Versammlung mitten aus dem Feuer*, dem Gewölk und dem Dunkel mit gewaltiger Stimme* und fügte nichts hinzu. Und er schrieb sie auf zwei steinerne Tafeln* und gab sie mir.", footnotes: ["℘ V. 4", "℘ 2Mo 19,18.19", "℘ Kap. 4,13; 2Mo 31,18"] },
      { number: 23, text: "Und es geschah, als ihr die Stimme mitten aus der Finsternis hörtet, während der Berg im Feuer brannte*, da tratet ihr zu mir heran, alle Oberhäupter eurer Stämme und eure Ältesten*,", heading: "Mose als Mittler zwischen Gott und Israel", footnotes: ["℘ Kap. 9,15", "℘ 2Mo 20,18.19"] },
      { number: 24, text: "und sagtet: Siehe, der HERR, unser Gott, hat uns seine Herrlichkeit und seine Größe sehen lassen*, und wir haben seine Stimme mitten aus dem Feuer gehört. An diesem Tag haben wir gesehen, dass Gott mit dem Menschen reden kann und der am Leben bleibt.*", footnotes: ["℘ 4Mo 14,14", "℘ Kap. 4,33; 1Mo 32,31"] },
      { number: 25, text: "Und nun, wozu sollen wir sterben? Denn dieses große Feuer wird uns verzehren. Wenn wir die Stimme des HERRN, unseres Gottes, noch weiter hören, dann werden wir sterben.*", footnotes: ["℘ Kap. 18,16"] },
      { number: 26, text: "Denn wer ist unter allen Sterblichen*, der die Stimme des lebendigen Gottes* mitten aus dem Feuer hätte reden hören wie wir und wäre am Leben geblieben?*", footnotes: ["w. wer ist unter allem Fleisch", "℘ Jos 3,10; Ps 42,3; Hebr 3,12; 10,31", "℘ Kap. 4,33; 1Mo 32,31"] },
      { number: 27, text: "Tritt du hinzu und höre alles, was der HERR, unser Gott, sagen wird*. Und du, du sollst alles zu uns reden*, was der HERR, unser Gott, zu dir reden wird, und wir wollen es hören und tun.*", footnotes: ["℘ Apg 10,33", "℘ 2Mo 20,18.19", "℘ 2Mo 18,20; 19,8; Jer 42,5"] },
      { number: 28, text: "Und der HERR hörte die Stimme eurer Worte, als ihr zu mir redetet. Da sprach der HERR zu mir: Ich habe die Stimme der Worte dieses Volkes gehört, die sie zu dir geredet haben. Sie haben recht geredet mit allem, was sie gesagt haben*.", footnotes: ["℘ Kap. 18,17"] },
      { number: 29, text: "Möge doch diese ihre Gesinnung bleiben*, mich allezeit zu fürchten* und alle meine Gebote zu halten*, damit es ihnen und ihren Kindern ewig gut geht*!", footnotes: ["o. Möge doch dieses ihr Herz sein", "℘ Kap. 4,10; 8,6; 10,12.20; 1Chr 29,18", "℘ Kap. 4,2; 6,17; Ps 19,12", "℘ V. 16"] },
      { number: 30, text: "Geh, sage zu ihnen: Kehrt in eure Zelte zurück!" },
      { number: 31, text: "Du aber bleibe hier bei mir stehen*! Und ich will all die Gebote und die Ordnungen und die Rechtsbestimmungen zu dir reden, die du sie lehren sollst, damit sie sie tun in dem Land, das ich ihnen gebe, es in Besitz zu nehmen*. —", footnotes: ["℘ 2Mo 24,18", "℘ Kap. 3,18; 6,1"] },
      { number: 32, text: "Achtet nun darauf, zu tun, wie der HERR, euer Gott, es euch geboten hat*! Weicht nicht davon ab zur Rechten noch zur Linken*!", footnotes: ["℘ Kap. 4,2; 6,17; Ps 19,12", "℘ Kap. 17,20; 28,14; Jos 1,7; 2Kö 22,2; Ps 80,19; Spr 4,27; Jes 30,21; Hes 20,19"] },
      { number: 33, text: "Auf dem ganzen Weg, den der HERR, euer Gott, euch geboten hat, sollt ihr gehen, damit ihr lebt und es euch gut geht und ihr eure Tage verlängert in dem Land, das ihr in Besitz nehmen werdet*.", footnotes: ["℘ V. 16; Kap. 8,1; 10,12; 29,8; 30,16; 1Kö 3,14; 2Kö 17,37; 1Chr 28,8; Ps 37,9; Spr 3,1.2"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "Und dies ist das Gebot, die Ordnungen und die Rechtsbestimmungen, die der HERR, euer Gott, geboten hat, euch zu lehren, damit ihr sie tut in dem Land*, in das ihr hinüberzieht, um es in Besitz zu nehmen*,", heading: "Aufforderung zur Verehrung des einen Gottes", footnotes: ["℘ Kap. 4,1; 12,1", "℘ Kap. 5,31; Hes 37,24"] },
      { number: 2, text: "damit du den HERRN, deinen Gott, fürchtest alle Tage deines Lebens*, um alle seine Ordnungen und seine Gebote zu bewahren, die ich dir gebiete — du und dein Sohn und deines Sohnes Sohn —, und damit deine Tage lange währen*.", footnotes: ["℘ V. 24; Kap. 4,10; 15,5; Jos 4,24; Jer 32,39", "℘ Kap. 5,16.33; 30,19.20"] },
      { number: 3, text: "Höre nun, Israel, und achte darauf, sie zu tun, damit es dir gut geht und ihr sehr zahlreich werdet — wie der HERR, der Gott deiner Väter*, zu dir geredet hat — in einem Land, das von Milch und Honig* überfließt*!", footnotes: ["℘ 2Mo 3,6.15", "d. i. Trauben- oder Dattelhonig", "℘ Kap. 8,8; 11,9; 26,9.15; 27,3; 31,20; 2Mo 3,8.17"] },
      { number: 4, text: "Höre, Israel: Der HERR ist unser Gott, der HERR allein*!*", footnotes: ["o. ist als Einziger der HERR", "℘ Kap. 4,35.39; Ps 86,10; Sach 14,9; Mk 12,29"] },
      { number: 5, text: "Und du sollst den HERRN, deinen Gott, lieben mit deinem ganzen Herzen und mit deiner ganzen Seele* und mit deiner ganzen Kraft*.", footnotes: ["o. Person", "℘ Kap. 10,12; 11,1.13; Jos 22,5; 2Kö 23,25; 2Chr 15,12; 34,31; Mt 22,37"] },
      { number: 6, text: "Und diese Worte, die ich dir heute gebiete, sollen in deinem Herzen sein.*", footnotes: ["℘ Ps 37,31; Spr 3,1; Jes 51,7"] },
      { number: 7, text: "Und du sollst sie deinen Kindern einschärfen*, und du sollst davon reden, wenn du in deinem Hause sitzt und wenn du auf dem Weg gehst, wenn du dich hinlegst und wenn du aufstehst.", footnotes: ["℘ Kap. 4,9.10; Ps 78,5; 119,13.30; Eph 6,4"] },
      { number: 8, text: "Und du sollst sie als Zeichen auf deine Hand binden, und sie sollen als Merkzeichen zwischen deinen Augen sein,*", footnotes: ["℘ 2Mo 13,9; Spr 7,3"] },
      { number: 9, text: "und du sollst sie auf die Pfosten deines Hauses und an deine Tore* schreiben.*", footnotes: ["Der SamPent liest: an die Pfosten deiner Häuser und Tore", "℘ Kap. 11,18-20"] },
      { number: 10, text: "Und es soll geschehen, wenn der HERR, dein Gott, dich in das Land bringt, das er deinen Vätern, Abraham, Isaak und Jakob, geschworen hat, dir zu geben*: große und gute Städte, die du nicht gebaut hast,", footnotes: ["℘ V. 18.23; Kap. 1,8"] },
      { number: 11, text: "und Häuser voll von allem Guten, die du nicht gefüllt hast, und ausgehauene Zisternen, die du nicht ausgehauen hast, Weinberge und Olivenbäume, die du nicht gepflanzt hast*, und wenn du dann essen und satt werden wirst*,", footnotes: ["℘ Jos 24,13", "℘ Kap. 11,15; Neh 9,25"] },
      { number: 12, text: "so hüte dich, dass du den HERRN ja nicht vergisst*, der dich herausgeführt hat aus dem Land Ägypten, aus dem Sklavenhaus.*", footnotes: ["℘ Kap. 8,10-14; Spr 30,9; Jes 17,10", "℘ 2Mo 13,3.14; Ri 2,12"] },
      { number: 13, text: "Den HERRN, deinen Gott, sollst du fürchten und ihm dienen*, und bei seinem Namen sollst du schwören*.", footnotes: ["℘ 2Mo 23,25; Jos 24,14; 1Sam 7,3; Mt 4,10", "℘ Kap. 10,20; 13,5; 1Mo 24,3; Ps 63,12; Jes 65,16; Jer 4,2"] },
      { number: 14, text: "Ihr sollt nicht anderen Göttern, von den Göttern der Völker, die rings um euch her sind*, nachlaufen —", footnotes: ["℘ Kap. 5,7; Jos 23,7; 2Kö 17,35.36; Jer 7,6; 25,6"] },
      { number: 15, text: "denn als ein eifersüchtiger Gott ist der HERR, dein Gott*, in deiner Mitte* —, damit nicht der Zorn des HERRN, deines Gottes, gegen dich entbrennt und er dich vom Erdboden weg vernichtet*.", footnotes: ["℘ Kap. 4,24", "℘ 4Mo 35,34", "℘ Kap. 7,4; 11,17; Jos 23,12.13.16"] },
      { number: 16, text: "Ihr sollt den HERRN, euren Gott, nicht prüfen*, wie ihr ihn zu Massa geprüft* habt*.", footnotes: ["o. versuchen; o. auf die Probe stellen", "o. versucht; o. auf die Probe gestellt", "℘ 2Mo 17,2-7; Mt 4,7"] },
      { number: 17, text: "Halten, ja, halten sollt ihr die Gebote des HERRN, eures Gottes, und seine Zeugnisse und seine Ordnungen, die er dir geboten hat*.", footnotes: ["℘ Kap. 5,1.32; 27,1; Ps 119,2"] },
      { number: 18, text: "Und du sollst tun, was recht und gut ist in den Augen des HERRN, damit es dir gut geht und du hineinkommst und das gute Land in Besitz nimmst, das der HERR deinen Vätern zugeschworen hat*,", footnotes: ["℘ V. 10"] },
      { number: 19, text: "um alle deine Feinde vor dir hinauszustoßen, so wie der HERR geredet hat*.", footnotes: ["℘ 2Mo 23,27-31"] },
      { number: 20, text: "Wenn dein Sohn dich künftig fragt: Was bedeuten die Zeugnisse und die Ordnungen und die Rechtsbestimmungen, die der HERR, unser Gott, euch geboten hat*?,", footnotes: ["℘ 2Mo 12,26"] },
      { number: 21, text: "dann sollst du deinem Sohn sagen: Sklaven waren wir beim Pharao in Ägypten. Der HERR aber hat uns mit starker Hand aus Ägypten herausgeführt*,", footnotes: ["℘ 2Mo 13,3.8.14"] },
      { number: 22, text: "und der HERR tat vor unseren Augen große und unheilvolle Zeichen und Wunder* an Ägypten, an dem Pharao und an seinem ganzen Haus.*", footnotes: ["o. Wahrzeichen", "℘ 2Mo 3,20; 10,2; Ps 135,9"] },
      { number: 23, text: "Uns aber führte er von dort heraus, um uns herzubringen, uns das Land zu geben, das er unsern Vätern zugeschworen hat*.", footnotes: ["℘ V. 10"] },
      { number: 24, text: "Und der HERR hat uns geboten, alle diese Ordnungen zu tun, den HERRN, unsern Gott, zu fürchten, damit es uns gut geht alle Tage und er uns am Leben erhält*, so wie es heute ist.", footnotes: ["℘ V. 2; Kap. 4,1; Ps 41,3"] },
      { number: 25, text: "Und es wird unsere Gerechtigkeit sein, wenn wir darauf achten, dieses ganze Gebot vor dem HERRN, unserm Gott, zu tun, so wie er es uns befohlen hat*.", footnotes: ["℘ Kap. 24,13; Ps 78,7; Hes 18,9; Röm 2,13; 1Jo 3,7"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "Wenn der HERR, dein Gott, dich in das Land bringt, in das du jetzt hineinkommst, um es in Besitz zu nehmen, und wenn er dann viele Nationen vor dir hinaustreibt*: die Hetiter und die Girgasiter und die Amoriter und die Kanaaniter und die Perisiter und die Hewiter und die Jebusiter*, sieben Nationen, größer und stärker als du*,", heading: "Keine Gemeinschaft mit den Kanaanäern — Gottes Segenszusage", footnotes: ["℘ Kap. 9,3; 31,3", "℘ 1Mo 15,21; 2Chr 8,7; Apg 13,19", "℘ Kap. 4,38; 9,1"] },
      { number: 2, text: "und wenn der HERR, dein Gott, sie vor dir dahingibt, und du sie schlägst, dann sollst du unbedingt an ihnen den Bann vollstrecken. Du sollst keinen Bund mit ihnen schließen noch ihnen gnädig sein*.", footnotes: ["℘ Kap. 9,3; 13,9; 20,16; 31,5; 2Mo 23,32; 4Mo 21,2; Jos 6,21; 11,8.14; 1Kö 20,34"] },
      { number: 3, text: "Und du sollst dich nicht mit ihnen verschwägern. Deine Tochter darfst du nicht seinem Sohn geben, und seine Tochter darfst du nicht für deinen Sohn nehmen*.", footnotes: ["℘ 1Mo 24,3; Esr 9,2.12; Neh 13,25; 2Kor 6,14"] },
      { number: 4, text: "Denn er würde deinen Sohn von mir* abwenden, dass er andern Göttern dient*, und der Zorn des HERRN würde gegen euch entbrennen, und er würde dich schnell vernichten*.", footnotes: ["w. von der Nachfolge hinter mir her", "so mit einer hebr. Handschr., dem SamPent, der LXX und Vulg.; Mas. T.: dass sie andern Göttern dienen\n℘ Kap. 20,18; 2Mo 34,16; 1Kö 16,31", "℘ Kap. 6,15"] },
      { number: 5, text: "Sondern so sollt ihr an ihnen tun: Ihre Altäre sollt ihr niederreißen und ihre Gedenksteine* zerbrechen und ihre Ascherim umhauen und ihre Götterbilder* mit Feuer verbrennen.*", footnotes: ["hebr. mazzebot; das sind aufrecht hingestellte Steine, die zu Ehren eines Gottes kultisch verehrt wurden", "das sind aus Stein gehauene o. aus Holz geschnitzte Bilder", "℘ Kap. 12,2.3; 2Mo 23,24; 1Chr 14,12"] },
      { number: 6, text: "Denn du bist dem HERRN, deinem Gott, ein heiliges Volk*. Dich hat der HERR, dein Gott, erwählt, dass du ihm zum Volk seines Eigentums wirst aus allen Völkern, die auf dem Erdboden sind.*", footnotes: ["℘ Esr 9,2; Jer 2,3", "℘ Kap. 26,18; 28,9; 3Mo 20,26; 1Sam 12,22; 1Kö 3,8; Jes 41,8"] },
      { number: 7, text: "Nicht weil ihr mehr wäret als alle Völker, hat der HERR sich euch zugeneigt und euch erwählt* — ihr seid ja das geringste unter allen Völkern* —,", footnotes: ["℘ Kap. 14,2; Ps 105,6; Hes 20,5", "℘ 1Kor 1,26.27"] },
      { number: 8, text: "sondern wegen der Liebe des HERRN zu euch*, und weil er den Eid hielt, den er euren Vätern geschworen*, hat der HERR euch mit starker Hand herausgeführt und dich erlöst aus dem Sklavenhaus, aus der Hand des Pharao, des Königs von Ägypten*.", footnotes: ["℘ Kap. 4,37; 23,6; 33,3; 1Kö 10,9; 1Jo 4,10", "℘ Kap. 1,8; 1Chr 16,16; Ps 105,8-10", "℘ Kap. 5,6; 2Mo 13,3.14.16; Jes 63,9"] },
      { number: 9, text: "So erkenne denn, dass der HERR, dein Gott, der Gott ist*, der treue Gott*, der den Bund und die Güte* bis auf tausend Generationen denen bewahrt, die ihn lieben* und seine Gebote halten*,", footnotes: ["℘ Kap. 4,35; 32,39", "℘ Ps 36,6; 1Kor 1,9", "o. Gnade", "℘ Ri 5,31", "℘ Kap. 5,10; 2Mo 20,6; 1Kö 8,23; Neh 1,5; 9,32; Ps 103,18; 105,8; Dan 9,4"] },
      { number: 10, text: "und der denen, die ihn hassen, ins Angesicht vergilt, um sie* umkommen zu lassen. Nicht zögert er gegenüber dem, der ihn hasst*, ins Angesicht vergilt er ihm*!", footnotes: ["T.; Mas. T.: ihn", "℘ Kap. 5,9", "℘ Kap. 32,41; Nah 1,2"] },
      { number: 11, text: "So sollst du das Gebot und die Ordnungen und die Rechtsbestimmungen halten, die zu tun ich dir heute befehle.*", footnotes: ["℘ Kap. 4,1.5; 8,11"] },
      { number: 12, text: "Und es wird geschehen: Dafür, dass ihr diesen Rechtsbestimmungen gehorcht, sie bewahrt und sie tut, wird der HERR, dein Gott, dir den Bund und die Güte* bewahren*, die er deinen Vätern geschworen hat*.", footnotes: ["o. Gnade", "℘ Kap. 5,10; 1Kö 8,23; Neh 1,5; 9,32; Ps 103,18; 105,8; Dan 9,4", "℘ Kap. 1,8; Neh 9,32"] },
      { number: 13, text: "Und er wird dich lieben* und dich segnen und dich zahlreich werden lassen. Er wird die Frucht deines Leibes segnen und die Frucht deines Landes, dein Getreide, deinen Most und dein Öl, den Wurf deiner Rinder und den Zuwachs deiner Schafe*, in dem Land, das er deinen Vätern geschworen hat, dir zu geben*.", footnotes: ["℘ Joh 14,21", "℘ Kap. 28,1-4.11; Hi 1,10; Ps 107,38; 144,12-14", "℘ Kap. 1,8; Neh 9,32"] },
      { number: 14, text: "Gesegnet wirst du sein vor allen Völkern.* Kein Unfruchtbarer und keine Unfruchtbare wird bei dir sein* noch bei deinem Vieh*.", footnotes: ["℘ 4Mo 22,12; Ps 67,8", "℘ 2Mo 23,26", "℘ Kap. 30,9"] },
      { number: 15, text: "Und der HERR wird jede Krankheit von dir abwenden. Und keine der bösen Seuchen Ägyptens, die du kennst, wird er auf dich legen*, sondern er wird sie auf alle deine Hasser bringen.", footnotes: ["℘ Kap. 28,60; 2Mo 15,26; Ps 91,10"] },
      { number: 16, text: "Und du wirst alle Völker verzehren, die der HERR, dein Gott, dir preisgibt. Du sollst ihretwegen nicht betrübt sein*, und du sollst ihren Göttern nicht dienen; denn das wäre ein Fallstrick* für dich*.", footnotes: ["w. Dein Auge soll ihretwegen nicht fließen", "w. ein Stellholz des Vogelfängers", "℘ Kap. 12,30"] },
      { number: 17, text: "Wenn du in deinem Herzen sagst: Diese Nationen sind größer als ich; wie könnte ich sie vertreiben?* —", footnotes: ["℘ Kap. 1,28"] },
      { number: 18, text: "fürchte dich nicht vor ihnen!* Denk doch daran, was der HERR*, dein Gott, dem Pharao und allen Ägyptern angetan hat,", footnotes: ["℘ Kap. 1,21.29; 4Mo 13,9; 21,34; Jos 8,1; Ps 27,1-3", "℘ Kap. 1,30"] },
      { number: 19, text: "an die großen Prüfungen, die deine Augen gesehen, und an die Zeichen und die Wunder* und die starke Hand und den ausgestreckten Arm, womit der HERR, dein Gott, dich herausgeführt hat!* Ebenso wird der HERR, dein Gott, an all den Völkern tun, vor denen du dich fürchtest*.", footnotes: ["o. Wahrzeichen\n℘ Jos 24,17; Ps 77,12", "℘ 2Mo 6,6; Neh 9,10; Ps 44,4", "℘ Kap. 3,21; Jos 10,25"] },
      { number: 20, text: "Und auch die Hornissen* wird der HERR, dein Gott, gegen sie senden*, bis alle, die übrig geblieben sind und die sich vor dir versteckt haben, umgekommen sind.", footnotes: ["nach anderen: Angst und Schrecken", "℘ 2Mo 23,28"] },
      { number: 21, text: "Erschrick nicht vor ihnen!* Denn der HERR, dein Gott, ist in deiner Mitte*, ein großer und furchtbarer Gott*.", footnotes: ["℘ Kap. 1,21.29; 4Mo 13,9; 21,34; Jos 8,1; Ps 27,1-3", "℘ Kap. 20,1; 31,17; Jos 3,10; Ps 46,6", "℘ Kap. 10,17; Neh 1,5; Ps 95,3"] },
      { number: 22, text: "Und der HERR, dein Gott, wird diese Nationen nach und nach vor dir hinaustreiben. Du wirst sie nicht schnell vernichten können, damit sich das Wild des Feldes nicht gegen dich vermehrt*.", footnotes: ["℘ 2Mo 23,29"] },
      { number: 23, text: "Und der HERR, dein Gott, wird sie vor dir dahingeben und sie in große Bestürzung versetzen, bis sie vernichtet sind*.", footnotes: ["℘ Kap. 9,3; Jos 10,10"] },
      { number: 24, text: "Und er wird ihre Könige in deine Hand geben, und du wirst ihre Namen ausrotten unter dem Himmel*. Kein Mensch wird vor dir bestehen*, bis du sie vernichtet hast.", footnotes: ["℘ Jos 11,17", "℘ Kap. 11,25; Jos 1,5; 23,3"] },
      { number: 25, text: "Die Bilder* ihrer Götter sollt ihr mit Feuer verbrennen. Du sollst nicht das Silber und das Gold, das an ihnen ist, begehren und es dir nehmen*, damit du dadurch nicht verstrickt wirst*; denn ein Gräuel für den HERRN, deinen Gott, ist es*.", footnotes: ["das sind aus Stein gehauene o. aus Holz geschnitzte Bilder", "℘ Jes 30,22", "℘ 3Mo 19,4; Ri 8,27", "℘ Kap. 27,15"] },
      { number: 26, text: "Und du sollst keinen Gräuel in dein Haus bringen, damit du nicht gleich ihm dem Bann verfällst*. Du sollst es als abscheulich verabscheuen und es für einen gräulichen Gräuel halten, denn Gebanntes ist es.*", footnotes: ["w. so dass du gleich ihm Gebanntes wirst", "℘ Kap. 13,18; Jos 6,18; Jes 41,24"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "Das ganze Gebot, das ich dir heute gebiete, sollt ihr halten, es zu tun, damit ihr lebt und zahlreich werdet und hineinkommt und das Land in Besitz nehmt, das der HERR euren Vätern zugeschworen hat*.", heading: "Ermahnung zur Dankbarkeit", footnotes: ["℘ V. 18; Kap. 1,8; 5,32.33"] },
      { number: 2, text: "Und du sollst an den ganzen Weg denken*, den der HERR, dein Gott, dich diese vierzig Jahre* in der Wüste hat wandern lassen*, um dich zu demütigen, um dich zu prüfen* und um zu erkennen, was in deinem Herzen ist*, ob du seine Gebote halten würdest oder nicht.", footnotes: ["℘ Kap. 32,7; Ps 103,2", "℘ Kap. 2,7; 2Mo 16,35; Hebr 3,9", "℘ Ps 136,16; Am 2,10", "℘ 2Mo 15,25; 20,20; Spr 17,3", "℘ 2Chr 32,31"] },
      { number: 3, text: "Und er demütigte dich und ließ dich hungern*. Und er speiste dich mit dem Man*, das du nicht kanntest und das deine Väter nicht kannten, um dich erkennen zu lassen, dass der Mensch nicht von Brot allein lebt. Sondern von allem, was aus dem Mund des HERRN hervorgeht, lebt der Mensch.*", footnotes: ["℘ Kap. 29,5; 2Mo 16,3", "griech. Manna\n℘ 2Mo 16,15.31; Joh 6,31", "℘ Kap. 32,47; Mt 4,4"] },
      { number: 4, text: "Deine Kleidung* an dir ist nicht verschlissen, und dein Fuß ist nicht geschwollen* diese vierzig Jahre*.", footnotes: ["w. Dein Obergewand; vgl. Anm. zu 2Mo 3,22", "℘ Kap. 2,7", "℘ Kap. 2,7; 2Mo 16,35; Hebr 3,9"] },
      { number: 5, text: "So erkenne in deinem Herzen, dass der HERR, dein Gott, dich erzieht, wie ein Mann seinen Sohn erzieht*!*", footnotes: ["o. züchtigt", "℘ Kap. 1,31; Hi 5,17; Spr 3,11.12; Hebr 12,5-7"] },
      { number: 6, text: "Halte nun die Gebote des HERRN, deines Gottes, indem du auf seinen Wegen gehst und ihn fürchtest.*", footnotes: ["℘ Kap. 5,29"] },
      { number: 7, text: "Denn der HERR, dein Gott, bringt dich in ein gutes Land, ein Land von Wasserbächen, Quellen und Gewässern*, die in der Ebene und im Gebirge entspringen;*", footnotes: ["w. Tiefen, o. Fluten", "℘ Kap. 11,10.11; Ps 104,10"] },
      { number: 8, text: "ein Land des Weizens und der Gerste, der Weinstöcke, Feigenbäume und Granatbäume*; ein Land mit ölreichen Olivenbäumen und Honig*;", footnotes: ["℘ 4Mo 13,23; Jer 2,7", "℘ Kap. 6,3; 2Kö 18,32"] },
      { number: 9, text: "ein Land, in dem du nicht in Armut dein Brot essen wirst, in dem es dir an nichts fehlen wird; ein Land, dessen Steine Eisen sind und aus dessen Bergen du Kupfer hauen wirst*.", footnotes: ["℘ Ri 18,10; 1Chr 22,3"] },
      { number: 10, text: "Und du wirst essen und satt werden, und du sollst den HERRN, deinen Gott, für das gute Land preisen*, das er dir gegeben hat*.", footnotes: ["o. segnen; o. danken", "℘ Jes 5,1; Joe 2,26"] },
      { number: 11, text: "Hüte dich, dass du den HERRN, deinen Gott, nicht vergisst*, indem du seine Gebote und seine Rechtsbestimmungen und seine Ordnungen, die ich dir heute gebe*, nicht hältst! —", footnotes: ["℘ Kap. 6,11.12; Ri 3,7; Jer 23,27", "w. gebiete\n℘ Kap. 4,1.5; 7,11; 11,32"] },
      { number: 12, text: "dass nicht, wenn du isst und satt wirst* und schöne Häuser baust und bewohnst", footnotes: ["℘ Kap. 6,10.12"] },
      { number: 13, text: "und deine Rinder und deine Schafe sich vermehren und dein Silber und Gold sich mehren und alles, was du hast, sich mehrt," },
      { number: 14, text: "dass dann nicht dein Herz sich erhebt* und du den HERRN, deinen Gott, vergisst*, der dich aus dem Land Ägypten, aus dem Sklavenhaus, herausführte*;", footnotes: ["℘ 2Kö 14,10", "℘ Kap. 6,11.12; Ri 3,7; Jer 23,27", "℘ Kap. 5,6; 13,6.11; 2Mo 13,3.14"] },
      { number: 15, text: "der dich wandern ließ in der großen und schrecklichen Wüste, wo feurige Schlangen* und Skorpione sind, in dem dürren Land, wo kein Wasser ist; der dir Wasser aus dem Kieselfelsen hervorbrachte*;", footnotes: ["℘ 4Mo 21,6", "℘ 2Mo 17,6; Jer 2,6; Hos 13,5"] },
      { number: 16, text: "der dich in der Wüste mit Man* speiste*, das deine Väter nicht kannten, um dich zu demütigen und um dich zu prüfen*, damit er dir am Ende* wohltue*", footnotes: ["griech. Manna", "℘ 2Mo 15,25; 20,20; Spr 17,3", "℘ 2Mo 15,25; 20,20; Spr 17,3", "o. in deiner Zukunft; w. an deinem Ende", "℘ Hi 42,12; Röm 8,28"] },
      { number: 17, text: "und du dann nicht in deinem Herzen sagst: Meine Kraft und die Stärke meiner Hand hat mir dieses Vermögen verschafft*!", footnotes: ["℘ Ri 7,2; 1Sam 30,23; Hi 31,25; Jer 9,22; Hes 28,5; Dan 4,27; 1Kor 4,7"] },
      { number: 18, text: "Sondern du sollst an den HERRN, deinen Gott, denken*, dass er es ist, der dir Kraft gibt, Vermögen zu schaffen*; — damit er seinen Bund aufrechterhält, den er deinen Vätern geschworen hat, so wie es heute ist*.", footnotes: ["℘ Kap. 6,11.12; Ri 3,7; Jer 23,27", "℘ 1Chr 29,12; Ps 127,1.2; Pred 12,1", "℘ V. 1"] },
      { number: 19, text: "Und es wird geschehen, wenn du je den HERRN, deinen Gott, vergisst und andern Göttern nachläufst und ihnen dienst und dich vor ihnen niederwirfst, so bezeuge ich heute gegen euch, dass ihr ganz gewiss umkommen werdet.*", footnotes: ["℘ Kap. 4,26; 11,16; 1Sam 12,25"] },
      { number: 20, text: "Wie die Nationen, die der HERR vor euch umkommen lässt*, so werdet ihr umkommen, dafür, dass ihr auf die Stimme des HERRN, eures Gottes, nicht hört*.", footnotes: ["℘ Jos 23,8.9", "℘ 3Mo 26,27.38.39; Jer 7,26.33; Dan 9,11-14"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "*Höre, Israel!* Du gehst heute über den Jordan*, um hineinzuziehen, das Land von Nationen in Besitz zu nehmen, die größer und stärker sind als du*, Städte, groß und bis an den Himmel befestigt,", heading: "Die Gabe des Landes: Ergebnis von Gottes, nicht von Israels Treue", footnotes: ["℘ 2Mo 32,1-35", "℘ Kap. 4,1; 7,1", "℘ 4Mo 33,51; Jos 1,11", "℘ Kap. 4,38"] },
      { number: 2, text: "ein großes und hochgewachsenes Volk, die Söhne der Enakiter, die du kennst und von denen du gehört hast: Wer kann vor den Söhnen Enak bestehen?*", footnotes: ["℘ Kap. 1,28; Jos 11,21; Am 2,9"] },
      { number: 3, text: "So erkenne denn heute, dass der HERR, dein Gott, es ist, der vor dir her hinübergeht* als ein verzehrendes Feuer*. Er selbst wird sie vernichten* und er selbst wird sie vor dir demütigen. Und du wirst sie vertreiben und sie schnell umkommen lassen, so wie der HERR zu dir geredet hat*.", footnotes: ["℘ Kap. 20,1; Jos 3,11; Ri 4,14", "℘ Kap. 4,24", "℘ Kap. 7,1; 2Mo 23,23; Jos 11,8.14", "℘ Kap. 7,22.23; Jos 14,12"] },
      { number: 4, text: "Wenn der HERR, dein Gott, sie vor dir hinausstößt, sprich nicht in deinem Herzen*: Wegen meiner Gerechtigkeit hat der HERR mich hierher gebracht, um dieses Land in Besitz zu nehmen. Denn wegen der Gottlosigkeit dieser Nationen wird der HERR sie vor dir vertreiben*.", footnotes: ["℘ Röm 10,6", "℘ Kap. 18,12; 1Mo 15,16; 3Mo 18,24.25"] },
      { number: 5, text: "Nicht wegen deiner Gerechtigkeit und der Aufrichtigkeit deines Herzens* kommst du hinein, um ihr Land in Besitz zu nehmen. Sondern wegen der Gottlosigkeit dieser Nationen vertreibt der HERR, dein Gott, sie vor dir* und damit er das Wort aufrechterhält, das der HERR deinen Vätern, Abraham, Isaak und Jakob, geschworen hat*.", footnotes: ["℘ Hes 36,22", "℘ Kap. 18,12; 1Mo 15,16; 3Mo 18,24.25", "℘ Kap. 1,8"] },
      { number: 6, text: "So erkenne denn, dass nicht wegen deiner Gerechtigkeit der HERR, dein Gott, dir dieses gute Land gibt, es in Besitz zu nehmen*! Denn ein halsstarriges Volk bist du*.", footnotes: ["℘ Kap. 3,18", "℘ V. 24; Kap. 10,16; Ps 78,8"] },
      { number: 7, text: "Denke daran, vergiss nicht, wie du den HERRN, deinen Gott, in der Wüste erzürnt hast! Von dem Tag an, als du aus dem Land Ägypten herausgezogen bist, bis ihr an diesen Ort kamt, seid ihr widerspenstig gegen den HERRN gewesen.*", heading: "Bundesbruch und Bundeserneuerung am Horeb", footnotes: ["℘ Kap. 31,27; Ps 78,40; Jer 44,9; Hes 20,13"] },
      { number: 8, text: "Und am Horeb* erzürntet ihr den HERRN, und der HERR ergrimmte über euch, so dass er euch vernichten wollte*.", footnotes: ["℘ Kap. 1,6", "℘ V. 19.25; Ps 106,19.23; Hebr 12,21"] },
      { number: 9, text: "Als ich auf den Berg gestiegen war, um die steinernen Tafeln zu empfangen, die Tafeln des Bundes, den der HERR mit euch geschlossen hatte, da blieb ich vierzig Tage und vierzig Nächte auf dem Berg — Brot aß ich nicht, und Wasser trank ich nicht* —,", footnotes: ["℘ Lk 4,1.2"] },
      { number: 10, text: "und der HERR gab mir die beiden steinernen Tafeln, beschrieben mit dem Finger Gottes. Auf ihnen standen all die Worte*, die der HERR auf dem Berg mitten aus dem Feuer* mit euch geredet hatte am Tag der Versammlung.", footnotes: ["w. Und auf ihnen war es gemäß all den Worten", "℘ Kap. 4,12-15; 10,4"] },
      { number: 11, text: "Und es geschah am Ende der vierzig Tage und vierzig Nächte, da gab mir der HERR die beiden steinernen Tafeln, die Tafeln des Bundes*.", footnotes: ["℘ 2Mo 31,18"] },
      { number: 12, text: "Und der HERR sprach zu mir: Mache dich auf, steig schnell von hier hinab! Denn dein Volk, das du aus Ägypten herausgeführt hast*, hat sich versündigt. Sie sind schnell von dem Weg abgewichen, den ich ihnen geboten habe; sie haben sich ein gegossenes Bild gemacht.", footnotes: ["℘ V. 26.29; 2Mo 13,3.14"] },
      { number: 13, text: "Und der HERR sprach zu mir und sagte: Ich habe dieses Volk gesehen, und siehe, ein halsstarriges Volk ist es." },
      { number: 14, text: "Lass mich*, dass ich sie vernichte und ihren Namen unter dem Himmel auslösche*! Dich aber will ich zu einer Nation machen, stärker und größer als sie.", footnotes: ["w. Lass ab von mir", "℘ Kap. 32,26; Jes 48,19"] },
      { number: 15, text: "Da wandte ich mich und stieg vom Berg herab, die zwei Tafeln des Bundes in meinen beiden Händen, der Berg aber brannte mit Feuer*.", footnotes: ["℘ Kap. 5,23.24"] },
      { number: 16, text: "Und ich sah, und siehe, ihr hattet gegen den HERRN, euren Gott, gesündigt. Ihr hattet euch ein gegossenes Kalb gemacht. Ihr wart schnell von dem Weg abgewichen, den der HERR euch geboten hatte." },
      { number: 17, text: "Da fasste ich die beiden Tafeln und warf sie aus meinen beiden Händen und zerbrach sie vor euren Augen." },
      { number: 18, text: "Und ich warf mich vor dem HERRN nieder wie das erste Mal vierzig Tage und vierzig Nächte — Brot aß ich nicht, und Wasser trank ich nicht* — wegen all eurer Sünden, die ihr begangen hattet, indem ihr tatet, was in den Augen des HERRN böse war, ihn zu reizen*.", footnotes: ["℘ Lk 4,1.2", "℘ Esr 10,6"] },
      { number: 19, text: "Denn ich fürchtete mich vor dem Zorn und dem Grimm, mit dem der HERR über euch erzürnt war, so dass er euch vernichten wollte*. Und der HERR erhörte mich auch dieses Mal*.", footnotes: ["℘ V. 19.25; Ps 106,19.23; Hebr 12,21", "℘ Kap. 10,10; 2Mo 33,17; 4Mo 11,2"] },
      { number: 20, text: "Auch über Aaron zürnte der HERR sehr, so dass er ihn vernichten wollte. Und ich bat zu jener Zeit auch für Aaron." },
      { number: 21, text: "Euer Sündenwerk* aber, das ihr gemacht hattet, das Kalb, nahm ich, verbrannte es mit Feuer und zerstieß es, indem ich es völlig zermalmte, bis es zu feinem Staub wurde. Und ich warf seinen Staub in den Bach, der vom Berg herabfließt*. —", footnotes: ["w. Eure Sünde", "℘ 1Kö 15,13; 2Chr 34,7"] },
      { number: 22, text: "Auch bei Tabera* und bei Massa* und bei Kibrot-Hattaawa* erzürntet ihr den HERRN*. —", footnotes: ["℘ 4Mo 11,1-3", "℘ 2Mo 17,2.7", "d. h. Lustgräber", "℘ Kap. 33,8; 4Mo 11,4.10.34"] },
      { number: 23, text: "Und als der HERR euch aus Kadesch-Barnea* sandte und sprach: Zieht hinauf und nehmt das Land in Besitz, das ich euch gegeben habe! — da wart ihr widerspenstig gegen den Befehl des HERRN, eures Gottes, und ihr glaubtet ihm nicht und gehorchtet seiner Stimme nicht*.", footnotes: ["℘ Kap. 1,2", "℘ 4Mo 14,1.2; Hebr 3,9"] },
      { number: 24, text: "Widerspenstige seid ihr gegen den HERRN gewesen von dem Tag an, da ich euch kenne.*", footnotes: ["℘ 4Mo 32,14; Jes 48,8; Jer 4,17; Hes 20,8; Apg 7,51"] },
      { number: 25, text: "Und ich warf mich vor dem HERRN nieder die vierzig Tage und die vierzig Nächte, die ich dalag*. Denn der HERR hatte gesagt, dass er euch vernichten wollte.", footnotes: ["w. die ich mich niederwarf\n℘ 2Mo 34,28"] },
      { number: 26, text: "Und ich betete zum HERRN und sprach: Herr, HERR! Vernichte nicht* dein Volk und dein Erbteil, das du durch deine Größe erlöst, das du mit starker Hand aus Ägypten herausgeführt hast*!", footnotes: ["℘ Ps 57,1", "℘ V. 12; 4Mo 14,13; Ps 74,2"] },
      { number: 27, text: "Denke an deine Knechte, Abraham, Isaak und Jakob*! Kehre dich nicht an die Verstocktheit dieses Volkes und an seine Gottlosigkeit und an seine Sünde*,", footnotes: ["℘ 3Mo 26,42", "℘ Ps 130,3"] },
      { number: 28, text: "damit das Land, aus dem du uns herausgeführt hast, nicht sagt: Weil der HERR nicht imstande war, sie in das Land zu bringen, von dem er zu ihnen geredet hatte, und weil er sie hasste, hat er sie herausgeführt, um sie in der Wüste sterben zu lassen*!", footnotes: ["℘ Kap. 1,27; 32,27; 4Mo 14,16; Jos 7,9; Hes 20,9.14.22"] },
      { number: 29, text: "Sie sind ja dein Volk und dein Erbteil*, das du herausgeführt hast mit deiner großen Kraft und mit deinem ausgestreckten Arm.*", footnotes: ["℘ Kap. 32,9; 2Mo 19,5.6; 33,13; Jes 64,8", "℘ V. 12; 2Mo 6,6; 1Kö 8,51; Neh 1,10; Jes 11,11"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "In jener Zeit sprach der HERR zu mir: Haue dir zwei steinerne Tafeln aus, wie die ersten, und steige zu mir auf den Berg herauf*! Und mache dir eine Lade aus Holz*!", footnotes: ["℘ 2Mo 34,1.2", "℘ 2Mo 25,10"] },
      { number: 2, text: "Und ich werde auf die Tafeln die Worte schreiben, die auf den ersten Tafeln waren, die du zerbrochen hast*. Und du sollst sie in die Lade legen*.", footnotes: ["℘ 2Mo 32,19", "℘ 2Mo 25,16.21"] },
      { number: 3, text: "Und ich machte eine Lade aus Akazienholz* und hieb zwei steinerne Tafeln aus, wie die ersten. Und ich stieg auf den Berg, die zwei Tafeln in meiner Hand*.", footnotes: ["℘ 2Mo 25,10", "℘ 2Mo 34,4"] },
      { number: 4, text: "Und er schrieb auf die Tafeln, ebenso wie die erste Schrift war*, die zehn Worte, die der HERR auf dem Berg mitten aus dem Feuer* zu euch geredet hatte am Tag der Versammlung. Und der HERR gab sie mir.", footnotes: ["℘ 2Kor 3,7", "℘ Kap. 4,12.15"] },
      { number: 5, text: "Und ich wandte mich und stieg vom Berg herab.* Und ich legte die Tafeln in die Lade, die ich gemacht hatte; und dort blieben sie, wie der HERR mir geboten hatte.*", footnotes: ["℘ 2Mo 34,28.29", "℘ 2Mo 25,21; 40,20"] },
      { number: 6, text: "Und die Söhne Israel brachen auf* von Beerot-Bene-Jaakan nach Moser*. Dort starb Aaron, und dort wurde er begraben. Und an seiner Stelle übte sein Sohn, Eleasar, den Priesterdienst aus.*", footnotes: ["w. rissen sich die Zeltpflöcke heraus", "℘ 4Mo 33,30", "℘ 4Mo 20,28"] },
      { number: 7, text: "Von dort brachen sie auf nach Gudgoda und von Gudgoda nach Jotbata*, einem Land mit Wasserbächen.", footnotes: ["℘ 4Mo 33,33"] },
      { number: 8, text: "In jener Zeit sonderte der HERR den Stamm Levi dazu aus*, die Lade des Bundes des HERRN zu tragen*, vor dem HERRN zu stehen, um seinen Dienst zu verrichten* und in seinem Namen zu segnen*, bis auf diesen Tag*.", footnotes: ["℘ 4Mo 3,6; 8,5", "℘ Kap. 31,9.25; 4Mo 3,31; 1Chr 15,2", "℘ 4Mo 8,6.11", "℘ Kap. 21,5; 1Chr 23,13", "℘ Kap. 18,5"] },
      { number: 9, text: "Darum bekam Levi weder Anteil noch ein Erbe mit seinen Brüdern. Der HERR selbst ist sein Erbteil, so wie der HERR, dein Gott, ihm zugesagt hat*.", footnotes: ["℘ Kap. 12,12; 14,27.29; 18,1.2; 4Mo 18,20-24"] },
      { number: 10, text: "Ich aber stand auf dem Berg wie die vorigen Tage, vierzig Tage und vierzig Nächte, und der HERR erhörte mich auch dieses Mal*. Der HERR wollte dich nicht vernichten*.", footnotes: ["℘ Kap. 9,18.19", "℘ 2Mo 32,14"] },
      { number: 11, text: "Und der HERR sprach zu mir: Geh hin, stelle dich* zum Aufbruch vor das Volk, damit sie hineinziehen und das Land in Besitz nehmen, von dem ich ihren Vätern geschworen habe, es ihnen zu geben!*", footnotes: ["im Mas. T. andere Reihenfolge: Stelle dich, geh hin", "℘ Kap. 1,8"] },
      { number: 12, text: "Und nun, Israel, was fordert der HERR, dein Gott, von dir, als nur, den HERRN, deinen Gott, zu fürchten*, auf allen seinen Wegen zu gehen* und ihn zu lieben* und dem HERRN, deinem Gott, zu dienen mit deinem ganzen Herzen und mit deiner ganzen Seele*,", heading: "Israels Liebe zu Gott: Antwort auf Gottes Liebe zu Israel", footnotes: ["℘ Kap. 5,29; Pred 12,13", "℘ Kap. 5,33; Lk 1,6", "℘ Mi 6,8", "℘ Kap. 6,5; 26,16; 1Sam 12,20.24"] },
      { number: 13, text: "indem du die Gebote des HERRN und seine Ordnungen, die ich dir heute gebe*, hältst, dir zum Guten?", footnotes: ["w. gebiete"] },
      { number: 14, text: "Siehe, dem HERRN, deinem Gott, gehören die Himmel und die Himmel der Himmel*, die Erde und alles, was in ihr ist*.", footnotes: ["℘ 1Kö 8,27; Neh 9,6; Ps 115,16", "℘ 1Mo 14,19; 2Mo 9,29; 19,5; Ps 24,1"] },
      { number: 15, text: "Doch nur deinen Vätern hat der HERR sich zugeneigt, sie zu lieben. Und er hat ihre Nachkommen nach ihnen, nämlich euch, aus allen Völkern erwählt*, so wie es heute ist.", footnotes: ["℘ Kap. 4,37; Am 3,2"] },
      { number: 16, text: "So beschneidet denn die Vorhaut eures Herzens* und verhärtet euren Nacken nicht mehr*!", footnotes: ["℘ Kap. 30,6; Jer 4,4; Röm 2,29", "℘ Kap. 9,6; 2Chr 30,8"] },
      { number: 17, text: "Denn der HERR, euer Gott, er ist der Gott der Götter* und der Herr der Herren*, der große, mächtige und furchtbare Gott*, der niemanden bevorzugt* und kein Bestechungsgeschenk annimmt*,", footnotes: ["℘ Jos 22,22", "℘ 1Tim 6,15", "℘ Kap. 7,21; Jer 32,18", "w. der das Gesicht eines Menschen nicht erhebt", "℘ 2Chr 19,7; Kol 3,25; Jak 2,1"] },
      { number: 18, text: "der Recht schafft der Waise und der Witwe* und den Fremden liebt, so dass er ihm Brot und Kleidung gibt*.", footnotes: ["℘ 2Mo 22,21; Ps 68,6; Jer 49,11", "℘ 3Mo 25,35"] },
      { number: 19, text: "Auch ihr sollt den Fremden lieben; denn Fremde seid ihr im Land Ägypten gewesen*.", footnotes: ["℘ Kap. 23,8"] },
      { number: 20, text: "Den HERRN, deinen Gott, sollst du fürchten*, ihm sollst du dienen und ihm anhängen, und bei seinem Namen sollst du schwören*.", footnotes: ["℘ Kap. 5,29; Pred 12,13", "℘ Kap. 6,13"] },
      { number: 21, text: "Er ist dein Ruhm*, und er ist dein Gott*, der jene großen und furchtgebietenden Taten an dir erwiesen hat, die deine Augen gesehen haben*.", footnotes: ["℘ Jes 60,19; Jer 17,14", "℘ 2Mo 15,2; Jos 24,18", "℘ Kap. 4,34; 2Mo 34,10"] },
      { number: 22, text: "Mit siebzig Seelen zogen deine Väter nach Ägypten hinab*; doch jetzt hat der HERR, dein Gott, dich an Menge gemacht wie die Sterne des Himmels.*", footnotes: ["℘ Kap. 26,5; 1Mo 46,27", "℘ Kap. 1,10"] },
    ]},
    { number: 11, verses: [
      { number: 1, text: "So sollst du nun den HERRN, deinen Gott, lieben* und sollst alle Tage seine Vorschriften halten* und seine Ordnungen, seine Rechtsbestimmungen und seine Gebote.", footnotes: ["℘ V. 13; Kap. 6,5; 13,4; 30,6.10.16", "w. sein zu Bewahrendes bewahren\n℘ Kap. 5,1"] },
      { number: 2, text: "Und erkennt* heute — denn nicht mit euren Kindern rede ich, die die Zucht des HERRN, eures Gottes, nicht erfahren* und nicht gesehen haben — seine Größe, seine starke Hand und seinen ausgestreckten Arm*", footnotes: ["o. ihr erkennt", "w. erkannt", "℘ Kap. 3,24; 2Mo 6,6"] },
      { number: 3, text: "und seine Zeichen und seine Taten, die er mitten in Ägypten getan hat an Pharao, dem König von Ägypten, und an seinem ganzen Land*;", footnotes: ["℘ Kap. 1,30; Jer 32,20"] },
      { number: 4, text: "und was er getan hat an der Heeresmacht Ägyptens, an seinen Pferden und seinen Wagen, über die er das Wasser des Schilfmeeres hinfluten ließ, als sie euch nachjagten, und die der HERR so umkommen ließ bis auf diesen Tag*;", footnotes: ["℘ 2Mo 14,28"] },
      { number: 5, text: "und was er euch in der Wüste getan hat, bis ihr an diesen Ort kamt*;", footnotes: ["℘ Ps 136,16"] },
      { number: 6, text: "und was er an Datan und Abiram getan hat, den Söhnen des Eliab, des Sohnes Rubens, wie die Erde ihren Mund aufriss und sie mitten in ganz Israel verschlang samt ihren Familien* und ihren Zelten und allem Bestand, der in ihrem Gefolge war.* —", footnotes: ["w. ihren Häusern", "℘ 4Mo 16,31-33"] },
      { number: 7, text: "Sondern eure eigenen Augen haben das ganze große Werk des HERRN gesehen, das er getan hat*.", footnotes: ["℘ Kap. 4,3.9.35; 29,2; Jos 24,31"] },
      { number: 8, text: "So haltet das ganze Gebot, das ich dir heute befehle, damit ihr stark seid und hineinkommt und das Land in Besitz nehmt, in das ihr hinüberzieht, um es in Besitz zu nehmen*,", heading: "Segen und Fluch", footnotes: ["℘ Kap. 4,14"] },
      { number: 9, text: "und damit ihr eure Tage verlängert in dem Land, von dem der HERR euren Vätern geschworen hat, es ihnen und ihren Nachkommen zu geben*, ein Land, das von Milch und Honig überfließt*.", footnotes: ["℘ V. 21.31; Kap. 1,8; 4,40", "℘ Kap. 6,3"] },
      { number: 10, text: "Denn das Land, in das du kommst, um es in Besitz zu nehmen, ist nicht wie das Land Ägypten, von wo ihr ausgezogen seid, wo du deine Saat sätest und mit deinem Fuß* wässertest wie einen Gemüsegarten,", footnotes: ["d. h. durch Öffnen und Schließen des Wassergrabens bzw. durch das Treten des Schöpfrades"] },
      { number: 11, text: "sondern das Land, in das ihr hinüberzieht, um es in Besitz zu nehmen, ist ein Land mit Bergen und Tälern — vom Regen des Himmels trinkt es Wasser* —,", footnotes: ["℘ Kap. 8,7; 1Mo 27,28"] },
      { number: 12, text: "ein Land, auf das der HERR, dein Gott, achthat. Beständig sind die Augen des HERRN, deines Gottes, darauf gerichtet vom Anfang des Jahres bis zum Ende des Jahres*.", footnotes: ["℘ 1Kö 9,3; Ps 65,11-13"] },
      { number: 13, text: "Und es wird geschehen, wenn ihr genau auf meine Gebote hört, die ich euch heute gebiete, den HERRN, euren Gott, zu lieben und ihm zu dienen mit eurem ganzen Herzen und mit eurer ganzen Seele*,", footnotes: ["o. Person"] },
      { number: 14, text: "dann gebe ich den Regen eures Landes zu seiner Zeit*, den Frühregen und den Spätregen*, damit du dein Getreide und deinen Most und dein Öl einsammelst*.", footnotes: ["℘ Kap. 28,12; 3Mo 26,3.4", "℘ Jes 30,23; Jer 5,24; Jak 5,7", "℘ Joe 2,19.23"] },
      { number: 15, text: "Und ich werde für dein Vieh Kraut auf dem Feld geben*, und du wirst essen und satt werden*.", footnotes: ["℘ Ps 104,14", "℘ Kap. 6,11; 3Mo 26,5"] },
      { number: 16, text: "Hütet euch, dass euer Herz sich ja nicht betören lässt* und ihr abweicht und andern Göttern dient und euch vor ihnen niederwerft*", footnotes: ["℘ Kap. 12,30", "℘ Kap. 5,7; 8,19; 17,3; 28,14; 29,17; 30,17; 1Sam 12,21"] },
      { number: 17, text: "und der Zorn des HERRN gegen euch entbrennt* und er den Himmel verschließt, dass es keinen Regen gibt* und der Erdboden seinen Ertrag nicht bringt* und ihr bald aus dem guten Land weggerafft werdet, das der HERR euch gibt.", footnotes: ["℘ Kap. 6,15", "℘ 2Chr 6,26", "℘ 3Mo 26,19.20"] },
      { number: 18, text: "Und ihr sollt diese meine Worte auf euer Herz und auf eure Seele legen* und sie als Zeichen auf eure Hand binden, und sie sollen als Merkzeichen zwischen euren Augen sein*.", footnotes: ["℘ Spr 7,3", "℘ 2Mo 13,9.16"] },
      { number: 19, text: "Und ihr sollt sie eure Kinder lehren*, indem ihr davon redet, wenn du in deinem Haus sitzt und wenn du auf dem Weg gehst, wenn du dich niederlegst und wenn du aufstehst.", footnotes: ["℘ Kap. 4,9.10; 32,46"] },
      { number: 20, text: "Und du sollst sie auf die Pfosten deines Hauses und an deine Tore schreiben,*", footnotes: ["℘ Kap. 6,6-9"] },
      { number: 21, text: "damit eure Tage und die Tage eurer Kinder zahlreich werden in dem Land, von dem der HERR euren Vätern geschworen hat, es ihnen zu geben, wie die Tage des Himmels über der Erde*.", footnotes: ["℘ Ps 89,30; Spr 3,2.16"] },
      { number: 22, text: "Denn wenn ihr dieses ganze Gebot, das ich euch* zu tun gebiete, treu haltet, indem ihr den HERRN, euren Gott, liebt, auf all seinen Wegen geht und ihm anhängt*,", footnotes: ["4 Handschr. lesen: euch heute", "℘ Kap. 19,9"] },
      { number: 23, text: "dann wird der HERR alle diese Nationen vor euch vertreiben; und ihr werdet Nationen vertreiben, größer und stärker als ihr*.", footnotes: ["℘ Kap. 4,38; Jos 23,9"] },
      { number: 24, text: "Jeder Ort, auf den eure Fußsohle treten wird, wird euch gehören: von der Wüste und dem Libanon* und vom Strom, dem Strom Euphrat an, bis an das westliche Meer wird euer Gebiet sein*.", footnotes: ["℘ Jos 1,3.4", "℘ 2Mo 23,31"] },
      { number: 25, text: "Kein Mensch wird vor euch bestehen*. Schrecken vor euch und Furcht vor euch wird der HERR, euer Gott, auf das ganze Land legen, das ihr betreten werdet, wie er zu euch geredet hat.*", footnotes: ["℘ Kap. 7,24", "℘ Kap. 2,25; 1Chr 14,17"] },
      { number: 26, text: "Siehe, ich lege euch heute Segen und Fluch vor*:", footnotes: ["℘ Kap. 30,1.15.19"] },
      { number: 27, text: "den Segen, wenn ihr den Geboten des HERRN, eures Gottes, gehorcht, die ich euch heute gebiete,*", footnotes: ["℘ Kap. 28,2-14"] },
      { number: 28, text: "und den Fluch, wenn ihr den Geboten des HERRN, eures Gottes, nicht gehorcht und von dem Weg, den ich euch heute gebiete, abweicht, um andern Göttern nachzulaufen, die ihr nicht kennt*.", footnotes: ["℘ Kap. 28,15-68"] },
      { number: 29, text: "Und es soll geschehen, wenn der HERR, dein Gott, dich in das Land bringt, in das du kommst, um es in Besitz zu nehmen, dann sollst du den Segen auf dem Berg Garizim erteilen und den Fluch auf dem Berg Ebal.*", footnotes: ["o. den Segen auf den Berg Garizim legen und den Fluch auf den Berg Ebal\n℘ Kap. 27,4.12.13; Jos 8,33"] },
      { number: 30, text: "Sind sie nicht jenseits des Jordan, hinter dem Weg gegen Sonnenuntergang, im Land der Kanaaniter, die in der Ebene* wohnen, Gilgal gegenüber*, bei den Terebinthen More*?", footnotes: ["s. Anm. zu Kap. 1,1", "℘ Jos 4,19", "℘ 1Mo 12,6"] },
      { number: 31, text: "Denn ihr geht über den Jordan, um hineinzuziehen, das Land in Besitz zu nehmen, das der HERR, euer Gott, euch gibt; und ihr werdet es in Besitz nehmen und darin wohnen.*", footnotes: ["℘ Jos 21,43"] },
      { number: 32, text: "Und so achtet darauf, all die Ordnungen und die Rechtsbestimmungen zu tun, die ich euch heute vorlege!*", footnotes: ["℘ Kap. 4,1.5; 13,6"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "Dies sind die Ordnungen und die Rechtsbestimmungen, die ihr halten sollt, sie zu tun* in dem Land, das der HERR, der Gott deiner Väter, dir gegeben hat, es in Besitz zu nehmen*, all die Tage, die ihr auf dem Erdboden lebt*:", heading: "Ort und Art des Gottesdienstes in Kanaan", footnotes: ["℘ Kap. 5,1; 6,1", "℘ Kap. 3,18", "℘ Kap. 2,25; 1Chr 14,17"] },
      { number: 2, text: "Ihr sollt all die Stätten vollständig ausrotten, wo die Nationen, die ihr vertreiben werdet, ihren Göttern gedient haben auf den hohen Bergen, auf den Hügeln und unter jedem grünen Baum*.", footnotes: ["℘ 1Kö 14,23; Ps 78,58; Jer 2,20; 17,2"] },
      { number: 3, text: "Und ihr sollt ihre Altäre niederreißen und ihre Gedenksteine* zerbrechen und ihre Ascherim mit Feuer verbrennen und die Bilder* ihrer Götter umhauen. Und ihr sollt ihren Namen von jener Stätte ausrotten*.", footnotes: ["s. Anm. zu Kap. 7,5", "das sind aus Stein gehauene o. aus Holz geschnitzte Bilder", "℘ Kap. 7,5.25; 2Chr 14,2-4"] },
      { number: 4, text: "Den HERRN, euren Gott, dürft ihr so nicht verehren*.", footnotes: ["w. Dem HERRN, eurem Gott, dürft ihr so nicht tun"] },
      { number: 5, text: "Sondern ihr sollt die Stätte aufsuchen, die der HERR, euer Gott, aus all euren Stämmen erwählen wird, um seinen Namen dort niederzulegen, dass er dort wohne*, und dahin sollst du kommen*.", footnotes: ["℘ V. 18.21.26; Kap. 14,23; 15,20; 16,2.6.11; 17,8; 18,6; 31,11; 3Mo 17,4; Jos 9,27; 1Kö 8,29; 12,27; 2Kö 18,22; 1Chr 22,1", "℘ Kap. 26,2"] },
      { number: 6, text: "Und dahin sollt ihr eure Brandopfer bringen und eure Schlachtopfer, eure Zehnten und das Hebopfer* eurer Hand und eure Gelübde* und eure freiwilligen Gaben und die Erstgeburten eurer Rinder und Schafe*.", footnotes: ["d. i. ein Opfer, das durch Hochheben dem HERRN geweiht wird", "℘ 1Sam 1,21", "℘ Kap. 14,23; 15,19.20; 2Chr 7,12; Ps 116,17-19"] },
      { number: 7, text: "Und dort sollt ihr vor dem HERRN, eurem Gott, essen und euch freuen*, ihr und eure Familien, an allem, was eure Hand erworben hat, worin der HERR, dein Gott, dich gesegnet hat*.", footnotes: ["℘ 1Chr 29,22; Hes 44,3", "℘ Kap. 14,26; Jes 62,9"] },
      { number: 8, text: "Ihr dürft es nicht mehr so machen nach allem, wie wir es heute hier tun, dass jeder all das tut, was in seinen Augen recht ist*.", footnotes: ["℘ Ri 17,6"] },
      { number: 9, text: "Denn ihr seid bis jetzt noch nicht zu der Ruhe und zu dem Erbteil gekommen, das der HERR, dein Gott, dir gibt*.", footnotes: ["℘ Jer 31,2; Mi 2,10; Hebr 4,8.9"] },
      { number: 10, text: "Seid ihr aber über den Jordan gezogen und wohnt in dem Land, das der HERR, euer Gott, euch erben lässt*, und hat er euch Ruhe verschafft vor all euren Feinden ringsum*, dass ihr sicher wohnt*,", footnotes: ["℘ Jos 14,1; Apg 13,19", "℘ Jos 11,23; 1Chr 22,18", "℘ Kap. 33,28; 3Mo 25,18; Hes 38,11"] },
      { number: 11, text: "dann soll es geschehen: Die Stätte, die der HERR, euer Gott, erwählen wird, seinen Namen dort wohnen zu lassen*, dahin sollt ihr alles bringen, was ich euch gebiete: eure Brandopfer und eure Schlachtopfer, eure Zehnten und das Hebopfer eurer Hand und all das Auserlesene eurer Gelübde, die ihr dem HERRN geloben werdet*.", footnotes: ["℘ Kap. 14,23; 15,19.20; 2Chr 7,12; Ps 116,17-19", "℘ Kap. 14,23; 15,19.20; 2Chr 7,12; Ps 116,17-19"] },
      { number: 12, text: "Und ihr sollt euch vor dem HERRN, eurem Gott, freuen, ihr und eure Söhne und eure Töchter und eure Sklaven und eure Sklavinnen und der Levit, der in euren Toren wohnt*, denn er hat weder Anteil noch Erbe mit euch*.", footnotes: ["℘ Kap. 16,11.14; 26,11; 27,7; 3Mo 23,40; Neh 8,9-12; Phil 4,4", "℘ Kap. 10,9"] },
      { number: 13, text: "Hüte dich, dass du ja nicht deine Brandopfer an jeder Stätte opferst, die du siehst!*", footnotes: ["℘ 3Mo 17,3.4; Jos 22,29"] },
      { number: 14, text: "Sondern an der Stätte, die der HERR in einem deiner Stämme erwählen wird*, dort sollst du deine Brandopfer opfern, und dort sollst du alles tun, was ich dir gebiete.*", footnotes: ["℘ 3Mo 17,3.4; Jos 22,29", "℘ 3Mo 17,3.4; Jos 22,29"] },
      { number: 15, text: "Doch magst du ganz nach Herzenslust* schlachten und Fleisch essen in all deinen Toren nach dem Segen des HERRN, deines Gottes, den er dir gegeben hat. Der Unreine und der Reine mögen es essen, wie man die Gazelle und wie man den Hirsch isst*.", footnotes: ["w. mit dem ganzen Begehren deiner Seele", "Das waren Tiere, die nicht geopfert werden durften, aber rein waren und die jeder essen durfte.\n℘ Kap. 14,5; 15,22"] },
      { number: 16, text: "Nur das Blut dürft ihr nicht essen; auf die Erde sollt ihr es gießen wie Wasser.* —", footnotes: ["℘ Kap. 15,23; 3Mo 3,17"] },
      { number: 17, text: "In deinen Toren darfst du nicht essen den Zehnten deines Getreides und deines Mostes und deines Öles noch die Erstgeburten deiner Rinder und deiner Schafe noch irgendetwas von deinen Gelübden, die du geloben wirst, noch deine freiwilligen Gaben noch das Hebopfer deiner Hand." },
      { number: 18, text: "Sondern vor dem HERRN, deinem Gott, an der Stätte, die der HERR, dein Gott, erwählen wird, sollst du es essen, du und dein Sohn und deine Tochter und dein Sklave und deine Sklavin und der Levit, der in deinen Toren wohnt. Und du sollst dich vor dem HERRN, deinem Gott, freuen an allem, was deine Hand erworben hat." },
      { number: 19, text: "Hüte dich, dass du den Leviten ja nicht im Stich lässt all deine Tage, die du in deinem Land lebst!*", footnotes: ["℘ Kap. 14,27"] },
      { number: 20, text: "Wenn der HERR, dein Gott, dein Gebiet erweitern wird*, so wie er zu dir geredet hat, und du sagst: »Ich will Fleisch essen!«, weil deine Seele Fleisch zu essen begehrt, so magst du nach Herzenslust* Fleisch essen.", footnotes: ["℘ 2Mo 34,24", "w. nach allem Begehren deiner Seele"] },
      { number: 21, text: "Wenn die Stätte, die der HERR, dein Gott, erwählen wird, um seinen Namen dort niederzulegen, zu weit entfernt von dir ist, so magst du schlachten von deinen Rindern und von deinen Schafen, die der HERR dir gegeben hat, so wie ich dir geboten habe, und magst nach Herzenslust* in deinen Toren essen.", footnotes: ["w. nach allem Begehren deiner Seele"] },
      { number: 22, text: "Gerade* wie die Gazelle und der Hirsch* gegessen werden, so magst du es essen; der Unreine und der Reine mögen es gleichermaßen essen*.", footnotes: ["o. Nur", "Das waren Tiere, die nicht geopfert werden durften, aber rein waren und die jeder essen durfte.", "℘ Kap. 14,5; 15,22"] },
      { number: 23, text: "Nur halte fest daran, kein Blut zu essen! Denn das Blut ist die Seele*, und du sollst nicht die Seele mit dem Fleisch essen,", footnotes: ["o. das Leben\n℘ 3Mo 17,11"] },
      { number: 24, text: "du sollst es nicht essen; auf die Erde sollst du es gießen wie Wasser.*", footnotes: ["℘ Kap. 15,23; 3Mo 3,17"] },
      { number: 25, text: "Du sollst es nicht essen, damit es dir und deinen Kindern nach dir gut geht, weil du tust, was in den Augen des HERRN recht ist*.", footnotes: ["℘ Kap. 21,9"] },
      { number: 26, text: "Jedoch deine heiligen Gaben*, die dir aufgetragen sind, und deine Gelübde sollst du nehmen und zu der Stätte kommen, die der HERR erwählen wird.", footnotes: ["o. heiligen Dinge\n℘ 4Mo 5,9"] },
      { number: 27, text: "Und deine Brandopfer, das Fleisch und das Blut, sollst du auf dem Altar des HERRN, deines Gottes, zurichten. Und das Blut deiner Schlachtopfer soll an* den Altar des HERRN, deines Gottes, gegossen werden, und das Fleisch magst du essen*.", footnotes: ["o. auf", "℘ Jer 7,21"] },
      { number: 28, text: "Hab acht und höre auf all diese Worte, die ich dir gebiete, damit es dir und deinen Kindern nach dir für ewig gut geht, weil du tust, was gut und recht ist in den Augen des HERRN, deines Gottes*!", footnotes: ["℘ Kap. 13,19"] },
      { number: 29, text: "Wenn der HERR, dein Gott, die Nationen ausrottet, zu denen du kommst, um sie vor dir zu vertreiben, und du vertreibst sie und wohnst in ihrem Land*,", footnotes: ["℘ Kap. 19,1; Jos 21,43"] },
      { number: 30, text: "so hüte dich, dass du dich ja nicht verführen lässt*, es ihnen nachzutun, nachdem sie vor dir vernichtet sind, und dass du nicht nach ihren Göttern fragst, indem du sagst: Wie dienten diese Nationen ihren Göttern? Auch ich will es so tun*!", footnotes: ["w. fangen lässt\n℘ Kap. 11,16; 3Mo 18,3", "℘ Kap. 7,16; 18,9; 2Mo 23,24.33; 2Kö 16,10; 17,15; Ps 106,35-39; Hes 11,12"] },
      { number: 31, text: "Dem HERRN, deinem Gott, sollst du so etwas nicht antun. Denn alles, was dem HERRN ein Gräuel ist, was er hasst, haben sie für ihre Götter getan*; denn sogar ihre Söhne und ihre Töchter haben sie für ihre Götter im Feuer verbrannt*.", footnotes: ["℘ Kap. 20,18; 3Mo 18,30; 2Chr 33,2", "℘ Kap. 18,9.10; 3Mo 18,21; 20,2; 2Kö 3,27"] },
    ]},
    { number: 13, verses: [
      { number: 1, text: "Das ganze Wort, das ich euch gebiete, das sollt ihr bewahren, um es zu tun. Du sollst zu ihm nichts hinzufügen und nichts von ihm wegnehmen.*", footnotes: ["℘ Kap. 4,1.2; Spr 30,6"] },
      { number: 2, text: "Wenn in deiner Mitte ein Prophet aufsteht oder einer, der Träume hat*, und er gibt dir ein Zeichen oder ein Wunder*,", heading: "Ahndung aller Versuche, Israel zur Verehrung eines anderen Gottes zu bewegen", footnotes: ["℘ Jer 27,9; Sach 10,2; Mt 7,15", "o. Wahrzeichen"] },
      { number: 3, text: "und das Zeichen oder das Wunder* trifft ein, von dem er zu dir geredet hat, indem er sagte: »Lass uns anderen Göttern — die du nicht gekannt hast — nachlaufen und ihnen dienen*!«,", footnotes: ["o. Wahrzeichen", "℘ 1Sam 26,19"] },
      { number: 4, text: "dann sollst du nicht auf die Worte dieses Propheten hören* oder auf den, der die Träume hat. Denn der HERR, euer Gott, prüft euch, um zu erkennen, ob ihr den HERRN, euren Gott, mit eurem ganzen Herzen und mit eurer ganzen Seele* liebt*.", footnotes: ["℘ 2Petr 2,1; Offb 13,14", "o. eurem ganzen Leben", "℘ Kap. 6,5; 11,1.13"] },
      { number: 5, text: "Dem HERRN, eurem Gott, sollt ihr nachfolgen*, und ihn sollt ihr fürchten. Seine Gebote sollt ihr halten und seiner Stimme gehorchen; ihm sollt ihr dienen und ihm anhängen.", footnotes: ["℘ Kap. 6,13; Jos 23,8; 1Sam 12,14; 2Chr 34,31; Jer 7,23"] },
      { number: 6, text: "Und jener Prophet oder der, der die Träume hat, soll getötet werden*. Denn er hat Abfall vom HERRN, eurem Gott, gepredigt, der euch aus dem Land Ägypten herausgeführt und dich erlöst hat aus dem Sklavenhaus*, um dich abzubringen von dem Weg, auf dem zu gehen der HERR, dein Gott, dir geboten hat*. Und du sollst das Böse aus deiner Mitte wegschaffen.*", footnotes: ["℘ Kap. 18,20; 1Kö 18,40; Jer 28,15-17", "℘ 2Mo 13,3.14", "℘ Kap. 11,32", "℘ Kap. 17,7.12; 19,19; 21,21; 22,21.22.24; 24,7; Jos 7,13; Ri 20,13; 1Kor 5,13"] },
      { number: 7, text: "Wenn dein Bruder, der Sohn deiner Mutter, oder dein Sohn oder deine Tochter oder die Frau an deinem Busen* oder dein Freund, der dir wie dein Leben* ist, dich heimlich verführt*, indem er sagt: Lass uns gehen und anderen Göttern dienen! — die du nicht gekannt hast, weder du noch deine Väter,", footnotes: ["w. die Frau deines Schoßes", "o. wie deine Seele", "℘ 2Chr 22,3; Jer 44,15"] },
      { number: 8, text: "von den Göttern der Völker, die rings um euch her sind, nahe bei dir oder fern von dir, von einem Ende der Erde* bis zum anderen Ende der Erde* —,", footnotes: ["o. des Landes", "o. des Landes\n℘ Kap. 28,64; 32,17; Ri 10,6"] },
      { number: 9, text: "dann darfst du ihm nicht zu Willen sein, und du sollst seinetwegen nicht betrübt sein*, nicht auf ihn hören und nicht schonen noch Mitleid mit ihm haben, noch ihn decken*;", footnotes: ["w. dein Auge soll seinetwegen nicht fließen", "℘ Kap. 7,16; 25,12"] },
      { number: 10, text: "sondern du sollst ihn unbedingt umbringen*. Deine Hand soll zuerst gegen ihn sein, ihn zu töten, und danach die Hand des ganzen Volkes*.", footnotes: ["LXX und SamPent lesen: unbedingt anzeigen\n℘ Kap. 17,5; 2Mo 32,27", "℘ Kap. 17,7; 2Kö 11,18"] },
      { number: 11, text: "Und du sollst ihn steinigen, dass er stirbt*. Denn er hat versucht, dich vom HERRN, deinem Gott, abzubringen, der dich herausgeführt hat aus dem Land Ägypten, aus dem Sklavenhaus*.", footnotes: ["℘ 3Mo 20,2; 4Mo 25,4; Jos 7,25; Mt 10,37", "℘ 2Mo 13,3.14"] },
      { number: 12, text: "Und ganz Israel soll es hören, dass sie sich fürchten und in deiner Mitte nicht länger so etwas wie diese böse Sache tun*.", footnotes: ["℘ Kap. 17,13; 19,20; 21,21; Hes 23,48; 2Tim 5,20"] },
      { number: 13, text: "Wenn du von einer deiner Städte, die der HERR, dein Gott, dir gibt, dort zu wohnen, hörst:" },
      { number: 14, text: "Es sind Männer, ruchlose Leute*, aus deiner Mitte hervorgetreten und haben die Bewohner ihrer Stadt verleitet*, indem sie sagten: Lasst uns gehen und anderen Göttern dienen — die ihr nicht gekannt habt —,", footnotes: ["w. Söhne der Bosheit\n℘ 1Sam 1,16; 2,12; 2Kor 6,15", "℘ Apg 20,30"] },
      { number: 15, text: "dann sollst du untersuchen und nachforschen und genau fragen. Und siehe, ist es Wahrheit, steht die Sache fest, ist dieser Gräuel in deiner Mitte verübt worden*,", footnotes: ["℘ Kap. 17,4; Ri 20,3.12; Esr 10,16"] },
      { number: 16, text: "dann sollst du die Bewohner dieser Stadt unbedingt mit der Schärfe des Schwertes erschlagen*. Du sollst an ihnen und an allem, was in ihr ist, den Bann vollstrecken*, auch an ihrem Vieh, mit der Schärfe des Schwertes.", footnotes: ["℘ 2Mo 22,19; Jos 6,21", "℘ 4Mo 21,2"] },
      { number: 17, text: "Und alle Beute in ihr sollst du mitten auf ihren Platz zusammentragen und die Stadt und alle Beute in ihr dem HERRN, deinem Gott, als Ganzopfer mit Feuer verbrennen. Ewig soll sie ein Schutthaufen sein, sie soll nie mehr aufgebaut werden*.", footnotes: ["℘ Jos 6,24.26; 8,28"] },
      { number: 18, text: "Und nichts von dem Gebannten soll an deiner Hand haften bleiben*, damit der HERR sich von der Glut seines Zornes abwende* und dir Barmherzigkeit erweise und sich über dich erbarme und dich mehre, wie er es deinen Vätern geschworen hat*,", footnotes: ["℘ Kap. 7,26", "℘ Jos 7,26", "℘ 1Mo 22,17"] },
      { number: 19, text: "wenn du der Stimme des HERRN, deines Gottes, gehorchst, alle seine Gebote zu bewahren, die ich dir heute gebiete, dass du tust, was recht ist in den Augen des HERRN, deines Gottes.*", footnotes: ["℘ Kap. 12,28; 26,14"] },
    ]},
    { number: 14, verses: [
      { number: 1, text: "Ihr seid Kinder für den HERRN, euren Gott*. Ihr dürft euch nicht wegen eines Toten Schnittwunden beibringen* und euch nicht zwischen euren Augen kahl scheren*.", heading: "Verbot heidnischer Trauerbräuche — Reine und unreine Tiere", footnotes: ["℘ Kap. 32,6; Jes 63,16; Jer 3,19; 31,9; Röm 9,4.8", "o. euch nicht . . . ritzen", "w. keine Glatze machen; d. h. keine Stirnglatze scheren\n℘ 3Mo 19,28; 21,5"] },
      { number: 2, text: "Denn ein heiliges Volk bist du dem HERRN, deinem Gott*. Und dich hat der HERR erwählt, dass du ihm zum Volk seines Eigentums wirst aus allen Völkern, die auf dem Erdboden sind.*", footnotes: ["℘ V. 21; 3Mo 20,24.26", "℘ Kap. 7,6.7; 26,18.19"] },
      { number: 3, text: "Du sollst keinerlei Gräuel essen*.", footnotes: ["℘ Jes 65,4; Hes 4,14; Apg 10,14"] },
      { number: 4, text: "*Das sind die Tiere, die ihr essen dürft: Rind, Schaf und Ziege,", footnotes: ["℘ V. 4-19: 3Mo 11"] },
      { number: 5, text: "Hirsch und Gazelle und Damhirsch* und Steinbock und Wisent und Antilope und Wildschaf.", footnotes: ["℘ Kap. 12,15.22; 1Kö 5,3"] },
      { number: 6, text: "Und jedes Tier, das gespaltene Hufe hat, und zwar wirklich aufgespaltene Hufe, und das wiederkäut* unter den Tieren, das dürft ihr essen.", footnotes: ["w. das das Gekaute wieder aufsteigen lässt"] },
      { number: 7, text: "Nur diese dürft ihr nicht essen von den wiederkäuenden und von denen, die mit gespaltenen und zwar aufgespaltenen Hufen versehen sind: das Kamel und den Hasen und den Klippdachs; denn sie käuen wieder, aber sie haben keine gespaltenen Hufe: unrein sollen sie für euch sein;" },
      { number: 8, text: "und das Schwein, denn es hat gespaltene Hufe, aber es käut nicht wieder: unrein soll es für euch sein. Von ihrem Fleisch dürft ihr nicht essen, und ihr Aas dürft ihr nicht berühren." },
      { number: 9, text: "Dieses dürft ihr essen von allem, was im Wasser ist: Alles, was Flossen und Schuppen hat, dürft ihr essen;" },
      { number: 10, text: "aber alles, was keine Flossen und Schuppen hat, dürft ihr nicht essen: unrein soll es für euch sein." },
      { number: 11, text: "Alle reinen Vögel dürft ihr essen." },
      { number: 12, text: "Aber diese sind es, von denen ihr nicht essen dürft: der Adler* und der Lämmergeier und der Mönchsgeier", footnotes: ["o. der Gänsegeier"] },
      { number: 13, text: "und die Gabelweihe* und die Königsweihe und der Geier nach seiner Art", footnotes: ["SamPent und LXX lassen dieses Wort aus und lesen stattdessen in V. 12 für »der Lämmergeier« »die Gabelweihe«."] },
      { number: 14, text: "und alle Raben nach ihrer Art" },
      { number: 15, text: "und die Straußenhenne und der Falke und die Seemöwe und der Habicht nach seiner Art," },
      { number: 16, text: "der Steinkauz und der Ibis und die Schleiereule" },
      { number: 17, text: "und der Wüstenkauz und der Aasgeier und die Fischeule" },
      { number: 18, text: "und der Storch und der Fischreiher nach seiner Art und der Wiedehopf und die Fledermaus." },
      { number: 19, text: "Und alles geflügelte Kleingetier* soll für euch unrein sein; es darf nicht gegessen werden.", footnotes: ["w. Gewimmel"] },
      { number: 20, text: "Alle reinen Vögel dürft ihr essen." },
      { number: 21, text: "Ihr dürft keinerlei Aas essen*. Dem Fremden, der in deinen Toren wohnt, magst du es geben, dass er es isst, oder du magst es einem Ausländer verkaufen; denn ein heiliges Volk bist du dem HERRN, deinem Gott.* — Du sollst ein Böckchen nicht in der Milch seiner Mutter kochen.*", footnotes: ["℘ 2Mo 22,30", "℘ V. 2", "℘ 2Mo 23,19"] },
      { number: 22, text: "Du sollst gewissenhaft allen Ertrag deiner Saat verzehnten, was auf dem Feld wächst, Jahr für Jahr,*", heading: "Der Zehnte", footnotes: ["℘ 1Mo 47,24.26; Neh 10,38.39; Mt 23,23"] },
      { number: 23, text: "und sollst essen vor dem HERRN, deinem Gott, an der Stätte, die er erwählen wird, um seinen Namen dort wohnen zu lassen*, nämlich den Zehnten deines Getreides, deines Mostes und deines Öles und die Erstgeborenen deiner Rinder und deiner Schafe*, damit du lernst, den HERRN, deinen Gott, alle Tage zu fürchten*.", footnotes: ["℘ Kap. 12,5.11", "℘ Kap. 12,6", "℘ Kap. 4,10"] },
      { number: 24, text: "Wenn aber der Weg zu weit für dich ist, dass du es nicht hinbringen kannst, weil die Stätte für dich zu fern ist, die der HERR, dein Gott, erwählen wird, um seinen Namen dort hinzulegen, wenn der HERR, dein Gott, dich segnet," },
      { number: 25, text: "dann sollst du es für Geld geben*. Und dann binde das Geld in deine Hand zusammen und geh an die Stätte, die der HERR, dein Gott, erwählen wird!", footnotes: ["o. es zu Geld machen"] },
      { number: 26, text: "Und gib das Geld für alles, was deine Seele begehrt, für Rinder und Schafe, für Wein und Rauschtrank und für alles, was deine Seele wünscht*! Und iss dort vor dem HERRN, deinem Gott, und freue dich, du und dein Haus*!", footnotes: ["℘ Mt 21,12; Joh 2,14", "℘ Kap. 12,7"] },
      { number: 27, text: "Und den Leviten, der in deinen Toren wohnt, den sollst du nicht verlassen; denn er hat keinen Anteil noch Erbe mit dir.*", footnotes: ["℘ Kap. 10,9; 12,12.19"] },
      { number: 28, text: "Am Ende von drei Jahren sollst du den ganzen Zehnten deines Ertrages von jenem Jahr aussondern und ihn in deinen Toren niederlegen*.", footnotes: ["d. h. in deiner Ortschaft abliefern\n℘ Kap. 26,12"] },
      { number: 29, text: "Und der Levit — denn er hat keinen Anteil noch Erbe mit dir* — und der Fremde und die Waise und die Witwe, die in deinen Toren wohnen, sollen kommen und essen und sich sättigen*, damit der HERR, dein Gott, dich in allem Werk deiner Hand, das du tust, segnet*.", footnotes: ["℘ Kap. 10,9; 12,12.19", "℘ Kap. 16,11.14", "℘ Kap. 15,10.18; 23,21; 24,19; 28,8; Ps 41,2-4; Spr 3,9.10; Lk 14,13; 2Kor 9,6"] },
    ]},
    { number: 15, verses: [
      { number: 1, text: "Am Ende von sieben Jahren sollst du einen Schulderlass halten*.", heading: "Das Erlassjahr", footnotes: ["℘ Kap. 31,10; Jer 34,14"] },
      { number: 2, text: "Das aber ist die Sache mit dem Schulderlass: Jeder Gläubiger* soll das Darlehen seiner Hand, das er seinem Nächsten geliehen hat, erlassen. Er soll seinen Nächsten und seinen Bruder nicht drängen; denn man hat für den HERRN einen Schulderlass ausgerufen*.", footnotes: ["w. Herr eines Darlehens", "℘ Neh 5,10"] },
      { number: 3, text: "Den Ausländer magst du drängen. Was du aber bei deinem Bruder hast, soll deine Hand erlassen*,", footnotes: ["℘ Kap. 23,21"] },
      { number: 4, text: "damit nur ja kein Armer unter dir ist. Denn der HERR wird dich reichlich segnen in dem Land, das der HERR, dein Gott, dir als Erbteil gibt, es in Besitz zu nehmen*,", footnotes: ["℘ Kap. 3,18; 4,21; Jes 58,10.11"] },
      { number: 5, text: "wenn du nur der Stimme des HERRN, deines Gottes, genau gehorchst, darauf zu achten, dieses ganze Gebot zu tun, das ich dir heute befehle*.", footnotes: ["℘ Kap. 6,2; 26,14"] },
      { number: 6, text: "Denn der HERR, dein Gott, wird dich segnen*, wie er zu dir geredet hat*. Und du wirst vielen Nationen ausleihen, du aber wirst dir nichts leihen. Und du wirst über viele Nationen herrschen, über dich aber werden sie nicht herrschen.*", footnotes: ["w. hat dich gesegnet", "℘ 1Chr 17,27", "℘ Kap. 28,12.13"] },
      { number: 7, text: "Wenn es einen Armen bei dir geben wird, irgendeinen deiner Brüder in einem deiner Tore in deinem Land, das der HERR, dein Gott, dir gibt, dann sollst du dein Herz nicht verhärten und deine Hand vor deinem Bruder, dem Armen, nicht verschließen.*", footnotes: ["℘ 3Mo 25,35; Est 9,22; Lk 6,30; 1Jo 3,17"] },
      { number: 8, text: "Sondern du sollst ihm deine Hand weit öffnen und ihm willig ausleihen, was für den Mangel ausreicht, den er hat*.", footnotes: ["℘ 3Mo 25,35; Mt 5,42"] },
      { number: 9, text: "Hüte dich, dass in deinem Herzen nicht der boshafte Gedanke entsteht: Das siebte Jahr, das Erlassjahr*, ist nahe! — und dass dein Auge dann böse auf deinen Bruder, den Armen, sieht und du ihm nichts gibst. Er aber würde über dich zum HERRN schreien, und Sünde wäre an dir*!", footnotes: ["℘ Kap. 31,10; Jer 34,14", "℘ Kap. 24,15; 2Mo 22,22.23; Spr 14,21"] },
      { number: 10, text: "Willig sollst du ihm geben, und dein Herz soll nicht böse sein, wenn du ihm gibst*. Denn wegen dieser Sache wird der HERR, dein Gott, dich segnen in all deinem Tun und in allem Geschäft deiner Hand*.", footnotes: ["℘ 2Kor 8,2; 9,7", "℘ V. 18; Kap. 14,29; Spr 11,24"] },
      { number: 11, text: "Denn der Arme wird nicht aus dem Land verschwinden*. Darum befehle ich dir: Deinem Bruder, deinem Elenden und deinem Armen in deinem Land sollst du deine Hand weit öffnen*.", footnotes: ["℘ Mt 26,11\nw. wird nicht aufhören aus der Mitte des Landes", "℘ 2Mo 23,11; Spr 19,17; 1Tim 6,18.19; Jak 2,15"] },
      { number: 12, text: "*Wenn dein Bruder, ein Hebräer oder eine Hebräerin, sich dir verkauft*, dann soll er dir sechs Jahre dienen, und im siebten Jahr sollst du ihn von dir als Freien entlassen*.", heading: "Freilassung gekaufter Sklaven", footnotes: ["℘ 2Mo 21,1-11", "o. dir verkauft wird", "℘ 3Mo 25,40.41"] },
      { number: 13, text: "Und wenn du ihn als Freien von dir entlässt, sollst du ihn nicht mit leeren Händen entlassen;" },
      { number: 14, text: "du sollst ihm reichlich aufladen von deinen Schafen, von deiner Tenne und von deiner Kelterkufe. Von allem, womit der HERR, dein Gott, dich gesegnet hat, sollst du ihm geben*.", footnotes: ["℘ Ps 112,9"] },
      { number: 15, text: "Und du sollst daran denken, dass auch du im Land Ägypten Sklave warst und dass der HERR, dein Gott, dich erlöst hat; darum befehle ich dir heute diese Sache*.", footnotes: ["℘ Kap. 5,15"] },
      { number: 16, text: "Und es soll geschehen, wenn er zu dir sagt: Ich will nicht von dir weggehen — weil er dich und dein Haus liebt, weil es ihm bei dir gut geht* —,", footnotes: ["o. weil ihm wohl bei dir ist"] },
      { number: 17, text: "dann sollst du einen Pfriem nehmen und ihn durch sein Ohr in die Tür stechen, und er wird für immer dein Sklave sein; und auch deine Sklavin sollst du so behandeln." },
      { number: 18, text: "Es soll nicht schwer sein in deinen Augen, wenn du ihn als Freien von dir entlässt. Denn das Doppelte des Lohnes eines Tagelöhners hat er dir sechs Jahre lang erarbeitet. Und der HERR, dein Gott, wird dich segnen in allem, was du tust*.", footnotes: ["℘ V. 10"] },
      { number: 19, text: "Alles männliche Erstgeborene, das unter deinen Rindern und unter deinen Schafen geboren wird, sollst du dem HERRN, deinem Gott, heiligen*. Du sollst mit dem Erstgeborenen deines Rindes nicht arbeiten, und du sollst das Erstgeborene deiner Schafe nicht scheren;", heading: "Heiligung der Erstgeburt vom Vieh", footnotes: ["℘ 2Mo 13,2.12; 4Mo 18,15.17"] },
      { number: 20, text: "vor dem HERRN, deinem Gott, sollst du es essen, du und dein Haus, Jahr für Jahr, an der Stätte, die der HERR erwählen wird*.", footnotes: ["℘ Kap. 12,5.11"] },
      { number: 21, text: "Wenn aber ein Makel an ihm ist, dass es lahm oder blind ist, irgendein schlimmer Makel, darfst du es dem HERRN, deinem Gott, nicht opfern.*", footnotes: ["℘ 3Mo 22,20"] },
      { number: 22, text: "In deinen Toren magst du es essen, der Unreine und der Reine gleichermaßen, wie die Gazelle und wie den Hirsch*.", footnotes: ["℘ Kap. 12,15.16"] },
      { number: 23, text: "Nur sein Blut darfst du nicht essen; auf die Erde sollst du es gießen wie Wasser*.", footnotes: ["℘ Kap. 12,15.16"] },
    ]},
    { number: 16, verses: [
      { number: 1, text: "*Beachte den Monat Abib* und feiere Passah dem HERRN, deinem Gott*! Denn im Monat Abib hat der HERR, dein Gott, dich nachts aus Ägypten herausgeführt*.", heading: "Verordnungen über das Passah, das Fest der Wochen und das Fest der Laubhütten", footnotes: ["℘ 2Mo 23,14-19", "d. h. Ährenmonat", "℘ 2Mo 12,11.14", "℘ 2Mo 12,51; 13,4; 3Mo 23,5"] },
      { number: 2, text: "Und du sollst für den HERRN, deinen Gott, das Passah schlachten, Schafe und Rinder*, an der Stätte, die der HERR erwählen wird, um seinen Namen dort wohnen zu lassen*.", footnotes: ["℘ 4Mo 28,19", "℘ Kap. 12,5.11; Joh 2,13"] },
      { number: 3, text: "Du sollst kein Gesäuertes dazu essen*. Sieben Tage sollst du ungesäuerte Brote dazu essen, Brot des Elends — denn in Hast bist du aus dem Land Ägypten ausgezogen —, damit du an den Tag deines Auszugs aus dem Land Ägypten denkst alle Tage deines Lebens*.", footnotes: ["℘ 2Mo 12,8.17-20", "℘ 2Mo 13,3.4; Jos 4,7"] },
      { number: 4, text: "Und sieben Tage lang soll kein Sauerteig bei dir gesehen werden in deinem ganzen Gebiet*. Und von dem Fleisch, das du am ersten Tag abends schlachtest, soll nichts über Nacht bleiben bis zum Morgen*. —", footnotes: ["℘ 2Mo 13,7", "℘ 2Mo 12,10"] },
      { number: 5, text: "Du kannst das Passah nicht in einem deiner Tore schlachten, die der HERR, dein Gott, dir gibt." },
      { number: 6, text: "Sondern an der Stätte, die der HERR, dein Gott, erwählen wird; um seinen Namen dort wohnen zu lassen*, sollst du das Passah schlachten am Abend, beim Untergang der Sonne, zur Zeit deines Auszugs aus Ägypten*.", footnotes: ["℘ Kap. 12,5.11; Joh 2,13", "℘ 2Mo 12,6"] },
      { number: 7, text: "Und du sollst es braten* und essen an der Stätte, die der HERR, dein Gott, erwählen wird*. Und am nächsten Morgen sollst du dich wenden und zu deinen Zelten gehen.", footnotes: ["o. kochen; so die normale Bedeutung des Wortes, z. B. 2Mo 12,9 (etwa im Wasser gekocht)\n℘ 2Mo 12,9", "℘ Kap. 12,5.11; Joh 2,13"] },
      { number: 8, text: "Sechs Tage sollst du ungesäuerte Brote essen. Am siebten Tag aber ist eine Festversammlung für den HERRN, deinen Gott; du sollst keine Arbeit tun." },
      { number: 9, text: "Sieben Wochen sollst du dir abzählen: Von da an, wo man beginnt, die Sichel an die Saat zu legen, sollst du anfangen, sieben Wochen* zu zählen.", footnotes: ["℘ 3Mo 23,15"] },
      { number: 10, text: "Dann sollst du das Fest der Wochen* für den HERRN, deinen Gott, feiern*, je nach der freiwilligen Gabe deiner Hand, die du geben wirst, so wie der HERR, dein Gott, dich segnen wird*.", footnotes: ["℘ 3Mo 23,15", "℘ 4Mo 28,26", "℘ 1Chr 29,14; 2Kor 8,12"] },
      { number: 11, text: "Und du sollst dich vor dem HERRN, deinem Gott, freuen, du und dein Sohn und deine Tochter und dein Sklave und deine Sklavin und der Levit, der in deinen Toren wohnt, und der Fremde und die Waise und die Witwe, die in deiner Mitte wohnen*, an der Stätte, die der HERR, dein Gott, erwählen wird, um seinen Namen dort wohnen zu lassen*.", footnotes: ["℘ Kap. 12,12; 14,29; Joe 1,16", "℘ Kap. 12,5.11; Joh 2,13"] },
      { number: 12, text: "Und du sollst daran denken, dass du Sklave in Ägypten warst*, und sollst diese Ordnungen bewahren und tun.", footnotes: ["℘ Kap. 5,15"] },
      { number: 13, text: "Das Fest der Laubhütten sollst du sieben Tage lang feiern, wenn du den Ertrag von deiner Tenne und von deiner Kelterkufe einsammelst*.", footnotes: ["℘ 3Mo 23,34"] },
      { number: 14, text: "Und du sollst dich an deinem Fest freuen, du und dein Sohn und deine Tochter und dein Sklave und deine Sklavin und der Levit und der Fremde und die Waise und die Witwe, die in deinen Toren wohnen*.", footnotes: ["℘ Kap. 12,12; 14,29; Joe 1,16"] },
      { number: 15, text: "Sieben Tage sollst du für den HERRN, deinen Gott, das Fest feiern an der Stätte, die der HERR erwählen wird*. Denn der HERR, dein Gott, wird dich segnen in all deinem Ertrag und in allem Tun deiner Hände, und du sollst wirklich fröhlich sein*.", footnotes: ["℘ Kap. 12,5.11; Joh 2,13", "℘ Neh 8,17; Est 9,22; Joh 4,45"] },
      { number: 16, text: "Dreimal im Jahr soll alles bei dir, was männlich ist, vor dem HERRN, deinem Gott, erscheinen an der Stätte, die er erwählen wird*: am Fest der ungesäuerten Brote und am Fest der Wochen und am Fest der Laubhütten. Und man soll nicht mit leeren Händen vor dem HERRN erscheinen:", footnotes: ["℘ Esr 3,1; Ps 84,8; 122,4; Jes 33,20; Hes 36,38"] },
      { number: 17, text: "jeder nach dem, was seine Hand geben kann*, nach dem Segen des HERRN, deines Gottes, den er dir gegeben hat*.", footnotes: ["w. nach der Gabe seiner Hand", "℘ 1Chr 29,14; 2Kor 8,12"] },
      { number: 18, text: "Richter und Aufseher* sollst du dir einsetzen* in allen deinen Toren, die der HERR, dein Gott, dir nach deinen Stämmen gibt, damit sie das Volk richten mit gerechtem Gericht*.", heading: "Anweisungen zur Rechtsprechung im Tor", footnotes: ["w. Schreiber; d. i. eine Beamtenbezeichnung", "℘ 1Sam 8,1", "℘ Kap. 1,15-18; 17,9; 19,17; 1Chr 23,4; 2Chr 19,5-11"] },
      { number: 19, text: "Du sollst das Recht nicht beugen, du sollst die Person nicht ansehen* und kein Bestechungsgeschenk nehmen. Denn das Bestechungsgeschenk macht die Augen der Weisen blind und verdreht die Sache* der Gerechten*.", footnotes: ["℘ Kap. 1,17", "o. die Worte", "℘ Kap. 27,25; 2Mo 23,8; 1Sam 12,3; Hes 18,8"] },
      { number: 20, text: "Der Gerechtigkeit und nur der Gerechtigkeit sollst du nachjagen, damit du lebst und das Land in Besitz nimmst, das der HERR, dein Gott, dir gibt*.", footnotes: ["℘ Spr 11,19"] },
      { number: 21, text: "Du sollst dir keine Aschera pflanzen, irgendein Holz* neben dem Altar des HERRN, deines Gottes, den du dir machen wirst*.", heading: "Verbot von kanaanäischen Kultsymbolen, unvollständigen Opfertieren und Gestirnskulten", footnotes: ["o. irgendeinen Baum", "℘ 2Kö 21,7"] },
      { number: 22, text: "Und du sollst dir keine Gedenksteine* aufrichten, die der HERR, dein Gott, hasst*.", footnotes: ["hebr. mazzebot; das sind aufrecht hingestellte Steine, die zu Ehren eines Gottes kultisch verehrt wurden", "℘ Kap. 4,16.23.25; 2Mo 20,4; 34,13; 2Kö 17,10"] },
    ]},
    { number: 17, verses: [
      { number: 1, text: "Du sollst dem HERRN, deinem Gott, kein Rind oder Schaf opfern, an dem ein Makel ist, irgendetwas Schlimmes*; denn ein Gräuel ist das für den HERRN, deinen Gott.", footnotes: ["℘ 3Mo 22,20-25"] },
      { number: 2, text: "Wenn in deiner Mitte, in einem deiner Tore, die der HERR, dein Gott, dir gibt, jemand gefunden wird — ein Mann oder eine Frau —, der das tut, was böse ist in den Augen des HERRN, deines Gottes, indem er seinen Bund übertritt," },
      { number: 3, text: "so dass er geht und anderen Göttern dient* und sich vor ihnen niederwirft*, und zwar vor der Sonne oder vor dem Mond oder vor dem ganzen Heer des Himmels, was ich nicht befohlen habe,", footnotes: ["℘ Kap. 11,16; Jos 23,16", "℘ Kap. 4,19; 2Kö 21,3"] },
      { number: 4, text: "und es wird dir berichtet und du hörst es, dann sollst du es genau untersuchen; und siehe, wenn es sich herausstellt, es ist Wahrheit, die Sache steht fest, dieser Gräuel ist in Israel verübt worden*,", footnotes: ["℘ Kap. 13,13-15"] },
      { number: 5, text: "dann sollst du diesen Mann oder diese Frau, die diese böse Sache getan haben, zu deinen Toren hinausführen, den Mann oder die Frau, und sollst sie steinigen, dass sie sterben.*", footnotes: ["℘ 2Mo 22,19; 3Mo 20,2; Ri 6,31; Hi 31,28"] },
      { number: 6, text: "Auf die Aussage zweier Zeugen oder dreier Zeugen hin soll getötet werden, wer sterben soll. Er darf nicht auf die Aussage eines einzelnen Zeugen hin getötet werden*.", footnotes: ["℘ Kap. 19,15; 4Mo 35,30"] },
      { number: 7, text: "Die Hand der Zeugen* soll zuerst gegen ihn sein, ihn zu töten, und danach die Hand des ganzen Volkes*. Und du sollst das Böse aus deiner Mitte wegschaffen*.", footnotes: ["℘ Apg 7,58", "℘ Kap. 13,10", "℘ Kap. 13,6; Ri 20,13"] },
      { number: 8, text: "Wenn von den Streitsachen in deinen Toren eine Rechtssache zwischen Blut und Blut, zwischen Rechtsanspruch und Rechtsanspruch, zwischen Körperverletzung* und Körperverletzung für dich zu schwierig ist zum Urteil*, dann sollst du dich aufmachen und an die Stätte hinaufziehen, die der HERR, dein Gott, erwählen wird*.", heading: "Gottesurteil bei Kapitalverbrechen", footnotes: ["w. Schlag", "℘ Kap. 1,17; 2Sam 15,2", "℘ Kap. 12,5.11"] },
      { number: 9, text: "Und du sollst zu den Priestern, den Leviten, kommen und zu dem Richter, der in jenen Tagen sein wird, und dich erkundigen; und sie werden dir den Urteilsspruch* verkünden*.", footnotes: ["w. die Sache des Urteils", "℘ Kap. 16,18; 21,5; 25,1; 33,10; 2Mo 18,16; 1Chr 26,29; Hes 44,24; Sach 7,3"] },
      { number: 10, text: "Und du sollst dem Spruch gemäß handeln, den sie dir verkünden werden von jener Stätte aus, die der HERR erwählen wird, und sollst darauf achten, nach allem zu handeln, was sie dich lehren werden*.", footnotes: ["℘ Mt 23,3"] },
      { number: 11, text: "Dem Gesetz gemäß, das sie dich lehren, und nach dem Recht, das sie dir sagen werden, sollst du handeln. Von dem Spruch, den sie dir verkünden werden, sollst du weder zur Rechten noch zur Linken abweichen*.", footnotes: ["℘ V. 20; Kap. 5,32; Hebr 7,11"] },
      { number: 12, text: "Der Mann aber, der in Vermessenheit handelt, dass er nicht auf den Priester hört*, der dasteht, um dort den Dienst des HERRN, deines Gottes, zu verrichten*, oder auf den Richter: dieser Mann soll sterben*. Und du sollst das Böse aus Israel wegschaffen*.", footnotes: ["℘ Hos 4,4", "℘ Kap. 18,5", "℘ 4Mo 15,30; Jos 1,18", "℘ Kap. 13,6; Ri 20,13"] },
      { number: 13, text: "Und das ganze Volk soll es hören. Und sie sollen sich fürchten und nicht mehr vermessen handeln*.", footnotes: ["℘ Kap. 13,12; 1Tim 5,20"] },
      { number: 14, text: "Wenn du in das Land kommst, das der HERR, dein Gott, dir gibt, und es in Besitz genommen hast und darin wohnst und sagst: »Ich will einen König über mich setzen, wie alle Nationen*, die rings um mich her sind!«,", heading: "Das Königsgesetz", footnotes: ["℘ 1Sam 8,5"] },
      { number: 15, text: "dann sollst du nur den König über dich setzen, den der HERR, dein Gott, erwählen wird*. Aus der Mitte deiner Brüder sollst du einen König über dich setzen*. Du sollst nicht einen Ausländer über dich setzen, der nicht dein Bruder ist.", footnotes: ["℘ 1Sam 10,24; 16,3.12; 1Chr 28,5", "℘ Ps 89,20; 2Sam 5,1; Jer 30,21"] },
      { number: 16, text: "Nur soll er sich nicht viele Pferde anschaffen*, und er soll das Volk nicht nach Ägypten zurückführen, um sich noch mehr Pferde anzuschaffen*, denn der HERR hat euch gesagt: Ihr sollt nie wieder auf diesem Weg zurückkehren.*", footnotes: ["w. nicht die Pferde zahlreich machen\n℘ 1Kö 5,6", "w. um sich die Pferde zahlreich zu machen\n℘ Jes 31,1; Hes 17,15", "℘ 2Mo 13,17; Jer 42,19"] },
      { number: 17, text: "Und er soll sich nicht viele Frauen anschaffen*, damit sein Herz sich nicht von Gott abwendet*. Auch Silber und Gold soll er sich nicht übermäßig anschaffen*.", footnotes: ["w. nicht die Frauen zahlreich machen", "℘ 2Sam 5,13; 1Kö 11,1-8; 2Chr 11,21; Spr 31,3", "w. nicht sehr zahlreich machen\n℘ 1Kö 10,21; 1Chr 14,3"] },
      { number: 18, text: "Und es soll geschehen, wenn er auf dem Thron seines Königreiches sitzt, dann soll er sich eine Abschrift dieses Gesetzes in ein Buch schreiben, aus dem Buch, das den Priestern, den Leviten, vorliegt*.", footnotes: ["℘ Kap. 31,9; 2Kö 11,12"] },
      { number: 19, text: "Und sie soll bei ihm sein, und er soll alle Tage seines Lebens darin lesen, damit er den HERRN, seinen Gott, fürchten lernt, um alle Worte dieses Gesetzes und diese Ordnungen zu bewahren, sie zu tun,*", footnotes: ["℘ Kap. 4,10; 5,1; Jos 1,8; 2Kö 22,10"] },
      { number: 20, text: "damit sein Herz sich nicht über seine Brüder erhebt und er von dem Gebot weder zur Rechten noch zur Linken abweicht*, damit er die Tage in seiner Königsherrschaft verlängert, er und seine Söhne, in der Mitte Israels*.", footnotes: ["℘ Kap. 5,32; 2Sam 22,23; 1Kö 2,3; 15,5", "℘ 1Sam 10,25"] },
    ]},
    { number: 18, verses: [
      { number: 1, text: "Die Priester, die Leviten, der ganze Stamm Levi, sollen keinen Anteil noch ein Erbe mit Israel haben.* Die Feueropfer des HERRN und sein Erbteil* sollen sie essen.*", heading: "Versorgung der Priester", footnotes: ["℘ Kap. 10,9", "d. h. die Zehnten u. die Erstlinge", "℘ 4Mo 18,8.9; 1Kor 9,13"] },
      { number: 2, text: "Aber ein Erbteil inmitten seiner Brüder soll er nicht haben.* Der HERR ist sein Erbteil, so wie er zu ihm geredet hat*. —", footnotes: ["℘ Kap. 10,9", "℘ 4Mo 18,20; Hes 44,28"] },
      { number: 3, text: "Das aber ist der Rechtsanspruch der Priester an das Volk, an die, die ein Schlachtopfer opfern, es sei Rind oder Schaf: Man soll dem Priester die Vorderkeule geben und die Kinnbacken und den Magen*.", footnotes: ["℘ 2Mo 29,27.28; 3Mo 7,30-34"] },
      { number: 4, text: "Die Erstlinge deines Getreides, deines Mostes und deines Öles und die Erstlinge von der Schur deiner Schafe sollst du ihm geben*.", footnotes: ["℘ 4Mo 18,12"] },
      { number: 5, text: "Denn ihn hat der HERR, dein Gott, aus allen deinen Stämmen erwählt, damit er dastehe, um den Dienst im Namen des HERRN zu verrichten, er und seine Söhne, alle Tage*. —", footnotes: ["℘ Kap. 10,8; 17,12; 2Mo 28,1; 4Mo 3,10"] },
      { number: 6, text: "Und wenn der Levit aus einem deiner Tore kommen wird, aus ganz Israel, wo er sich als Fremder aufhält*, dann mag er nach Herzenslust* an die Stätte kommen, die der HERR erwählen wird*,", footnotes: ["℘ 4Mo 35,2-5", "w. nach allem Begehren seiner Seele", "℘ Kap. 12,5"] },
      { number: 7, text: "und im Namen des HERRN, seines Gottes, den Dienst verrichten wie alle seine Brüder, die Leviten, die dort vor dem HERRN stehen*.", footnotes: ["℘ 1Chr 23,32"] },
      { number: 8, text: "Zu gleichen Teilen sollen sie davon essen*; davon ausgenommen ist, was er aufgrund von Familienbesitz verkauft hat.", footnotes: ["℘ Neh 12,47"] },
      { number: 9, text: "Wenn du in das Land kommst, das der HERR, dein Gott, dir gibt, dann sollst du nicht lernen, es den Gräueln dieser Nationen gleichzutun.*", heading: "Warnung vor Zauberern und Wahrsagern", footnotes: ["℘ Kap. 12,30; 20,18; 2Kö 17,8.11.15; 2Chr 36,14; Jer 10,2; Röm 12,2"] },
      { number: 10, text: "Es soll unter dir niemand gefunden werden, der seinen Sohn oder seine Tochter durchs Feuer gehen lässt*, keiner, der Wahrsagerei treibt, kein Zauberer oder Beschwörer oder Magier*", footnotes: ["℘ Kap. 12,31; 2Chr 28,3; Jer 7,31", "℘ 2Mo 22,17; 2Kö 17,15-17; 2Chr 33,6; Jer 27,9; Apg 16,16"] },
      { number: 11, text: "oder Bannsprecher oder Totenbeschwörer oder Wahrsager oder der die Toten befragt*.", footnotes: ["℘ 3Mo 19,26.31; 20,6.27; Jes 8,19"] },
      { number: 12, text: "Denn ein Gräuel für den HERRN ist jeder, der diese Dinge tut.* Und um dieser Gräuel willen treibt der HERR, dein Gott, sie vor dir aus*.", footnotes: ["℘ Kap. 22,5; 2Kö 23,24", "℘ Kap. 9,4.5"] },
      { number: 13, text: "Du sollst dich ungeteilt an den HERRN, deinen Gott, halten*.*", footnotes: ["o. untadelig sein vor dem HERRN, deinem Gott; w. ganz sein mit dem HERRN, deinem Gott", "℘ Mt 5,48"] },
      { number: 14, text: "Denn diese Nationen, die du austreiben wirst, hören auf Zauberer und auf Wahrsager*. Du aber — so etwas hat der HERR, dein Gott, dir nicht gestattet*!", footnotes: ["℘ Jes 2,6", "℘ Eph 5,11"] },
      { number: 15, text: "Einen Propheten wie mich wird dir der HERR, dein Gott, aus deiner Mitte, aus deinen Brüdern, erstehen lassen*. Auf ihn sollt ihr hören*", heading: "Wahre und falsche Propheten", footnotes: ["℘ Kap. 34,10; 4Mo 12,6-8; Hos 12,14; Joh 1,21.45", "℘ Mt 17,5; Joh 5,46"] },
      { number: 16, text: "nach allem, was du vom HERRN, deinem Gott, am Horeb* erbeten hast am Tag der Versammlung, indem du sagtest: Ich möchte die Stimme des HERRN, meines Gottes, nicht länger hören, und dieses große Feuer möchte ich nicht mehr sehen, damit ich nicht sterbe*!", footnotes: ["℘ Kap. 1,6", "℘ Kap. 5,25-28; Jer 1,9"] },
      { number: 17, text: "Da sprach der HERR zu mir: Sie haben recht getan mit dem, was sie geredet haben.*", footnotes: ["℘ Kap. 5,25-28; Jer 1,9"] },
      { number: 18, text: "Einen Propheten wie dich will ich ihnen aus der Mitte ihrer Brüder erstehen lassen*. Ich will meine Worte in seinen Mund legen*, und er wird zu ihnen alles reden, was ich ihm befehlen werde.", footnotes: ["℘ Kap. 34,10; 4Mo 12,6-8; Hos 12,14; Joh 1,21.45", "℘ 2Mo 4,12.15; 4Mo 23,5.16; Jes 50,4; 51,16"] },
      { number: 19, text: "Und es wird geschehen, der Mann, der nicht auf meine Worte hört, die er* in meinem Namen reden wird, von dem werde ich Rechenschaft fordern*. —", footnotes: ["d. i. der Prophet", "℘ Jos 22,23; Apg 3,22.23"] },
      { number: 20, text: "Doch der Prophet, der sich vermessen sollte, in meinem Namen ein Wort zu reden*, das ich ihm nicht befohlen habe zu reden*, oder der im Namen anderer Götter reden wird: dieser Prophet muss sterben*.", footnotes: ["℘ Jer 23,31", "℘ Kap. 34,10; 4Mo 12,6-8; Hos 12,14; Joh 1,21.45", "℘ Kap. 13,1-6; Jer 14,14.15; 28,15-17; Sach 13,3"] },
      { number: 21, text: "Und wenn du in deinem Herzen sagst: »Wie sollen wir das Wort erkennen, das nicht der HERR geredet hat*?«,", footnotes: ["℘ Jer 28,9"] },
      { number: 22, text: "wenn der Prophet im Namen des HERRN redet, und das Wort geschieht nicht und trifft nicht ein, so ist das das Wort, das nicht der HERR geredet hat. In Vermessenheit hat der Prophet es geredet*; du brauchst dich nicht vor ihm zu fürchten.", footnotes: ["℘ 1Sam 3,19.20; 1Kö 22,28; Sach 2,13.15"] },
    ]},
    { number: 19, verses: [
      { number: 1, text: "*Wenn der HERR, dein Gott, die Nationen ausrotten wird, deren Land der HERR, dein Gott, dir gibt, und du sie vertreibst und in ihren Städten und in ihren Häusern wohnst*,", heading: "Zufluchtsstädte — Keine Grenzverletzung", footnotes: ["℘ V. 1-13: 4Mo 35,9-29; Jos 20,1-9", "℘ Kap. 12,29; Jos 24,13"] },
      { number: 2, text: "dann sollst du dir drei Städte aussondern* mitten in deinem Land, das der HERR, dein Gott, dir gibt, es in Besitz zu nehmen*.", footnotes: ["o. abmessen; o. festsetzen", "℘ Kap. 3,18; 4,41.42; 2Mo 21,13"] },
      { number: 3, text: "Du sollst dir den Weg dahin instand halten und das Gebiet deines Landes, das der HERR, dein Gott, dir als Erbteil geben wird*, in drei Teile teilen. Und es soll dazu geschehen, dass jeder Totschläger dahin fliehen kann.", footnotes: ["℘ Kap. 4,21; 26,1"] },
      { number: 4, text: "Das aber ist die Sache mit dem Totschläger, der dahin flieht, damit er am Leben bleibt: Wer seinen Nächsten unabsichtlich* erschlägt und ihn nicht schon vorher* hasste", footnotes: ["w. ohne Wissen", "w. seit gestern und vorgestern"] },
      { number: 5, text: "— etwa wer mit seinem Nächsten in den Wald geht, um Holz zu schlagen, und seine Hand holt mit der Axt aus, um das Holz abzuhauen, und das Eisen fährt vom Stiel und trifft seinen Nächsten, dass er stirbt —, der soll in eine dieser Städte fliehen, damit er am Leben bleibt," },
      { number: 6, text: "damit nicht der Bluträcher wutentbrannt* dem Totschläger nachjagt und ihn einholt, weil der Weg zu lang ist, und ihn totschlägt, obwohl ihn kein Todesurteil traf, weil er ihn nicht schon vorher* hasste.", footnotes: ["w. weil sein Herz heiß ist", "w. seit gestern und vorgestern"] },
      { number: 7, text: "Darum befehle ich dir: Drei Städte sollst du dir aussondern*. —", footnotes: ["℘ Kap. 3,18; 4,41.42; 2Mo 21,13"] },
      { number: 8, text: "Und wenn der HERR, dein Gott, dein Gebiet erweitern wird, wie er deinen Vätern geschworen hat, und dir das ganze Land gibt, das er deinen Vätern zu geben zugesagt hat* —", footnotes: ["℘ 1Mo 15,18"] },
      { number: 9, text: "wenn du darauf achtest, dieses ganze Gebot zu tun, das ich dir heute befehle, indem du den HERRN, deinen Gott, liebst und alle Tage auf seinen Wegen gehst* —, dann sollst du dir noch drei Städte zu diesen dreien hinzufügen,", footnotes: ["℘ Kap. 11,22"] },
      { number: 10, text: "damit nicht unschuldiges Blut vergossen wird mitten in deinem Land, das der HERR, dein Gott, dir als Erbteil gibt*, und Blutschuld auf dir ist*. —", footnotes: ["℘ Kap. 4,21; 26,1", "℘ Mt 27,25"] },
      { number: 11, text: "Wenn aber ein Mann seinen Nächsten hasst und ihm auflauert und sich gegen ihn erhebt und ihn totschlägt, so dass er stirbt, und er flieht in eine dieser Städte*,", footnotes: ["℘ Spr 28,17"] },
      { number: 12, text: "dann sollen die Ältesten seiner Stadt hinsenden und ihn von dort holen und ihn der Hand des Bluträchers übergeben, dass er sterbe*.", footnotes: ["℘ Kap. 27,24; 1Mo 9,5.6; 2Mo 21,14; 2Sam 14,7"] },
      { number: 13, text: "Du sollst seinetwegen nicht betrübt sein*, sondern du sollst unschuldig vergossenes Blut aus Israel wegschaffen*, damit es dir gut geht.", footnotes: ["w. Dein Auge soll seinetwegen nicht fließen", "℘ Kap. 21,9; 4Mo 35,31-33; 1Kö 2,31"] },
      { number: 14, text: "Du sollst nicht die Grenze deines Nächsten verrücken*, die die Vorfahren gezogen haben in deinem Erbteil, das du erben wirst in dem Land, das der HERR, dein Gott, dir gibt, es in Besitz zu nehmen*.", footnotes: ["℘ Kap. 27,17; Spr 22,28", "℘ Kap. 3,18; 4,41.42; 2Mo 21,13"] },
      { number: 15, text: "Ein einzelner Zeuge soll nicht gegen jemanden auftreten wegen irgendeiner Ungerechtigkeit* oder wegen irgendeiner Sünde, wegen irgendeiner Verfehlung, die er begeht. Nur auf zweier Zeugen Aussage oder auf dreier Zeugen Aussage hin soll eine Sache gültig sein*. —", heading: "Zeugen vor Gericht", footnotes: ["o. Schuld", "o. eine Entscheidung zustande kommen; w. sich ein Wort erheben\n℘ Kap. 17,6; Offb 11,3"] },
      { number: 16, text: "Wenn ein falscher Zeuge* gegen jemanden auftritt, um ihn des Ungehorsams* zu beschuldigen*,", footnotes: ["o. ein Zeuge der Gewalttat", "w. des Abfalls von Gott; vgl. Kap. 13,6", "℘ Kap. 5,20; 2Mo 23,1; Ps 27,12"] },
      { number: 17, text: "dann sollen die beiden Männer, die den Rechtsstreit führen, vor den HERRN treten, vor die Priester und die Richter, die in jenen Tagen da sein werden*.", footnotes: ["℘ Kap. 16,18; 2Mo 21,6"] },
      { number: 18, text: "Und die Richter sollen die Sache genau untersuchen. Und siehe, ist der Zeuge ein Lügenzeuge, hat er gegen seinen Bruder Lüge bezeugt," },
      { number: 19, text: "dann sollt ihr ihm tun, wie er seinem Bruder zu tun gedachte*. Und du sollst das Böse aus deiner Mitte wegschaffen*.", footnotes: ["℘ Spr 19,5.9; Dan 6,25", "℘ Kap. 13,6"] },
      { number: 20, text: "Und die Übrigen sollen es hören und sich fürchten und nicht mehr länger eine solch böse Sache in deiner Mitte begehen*.", footnotes: ["℘ Kap. 13,12"] },
      { number: 21, text: "Und du sollst nicht schonen*: Leben um Leben, Auge um Auge, Zahn um Zahn, Hand um Hand, Fuß um Fuß!*", footnotes: ["w. dein Auge soll nicht fließen", "℘ 2Mo 21,23.24"] },
    ]},
    { number: 20, verses: [
      { number: 1, text: "Wenn du gegen deine Feinde zum Krieg ausziehst* und siehst Pferde und Wagen, ein Volk, zahlreicher als du, dann sollst du dich nicht vor ihnen fürchten*. Denn der HERR, dein Gott, der dich aus dem Land Ägypten herausgeführt hat*, ist mit dir*.", heading: "Kriegsgesetze", footnotes: ["℘ 4Mo 10,9", "℘ Kap. 1,29.30; Jos 10,8; 2Chr 14,10.11; Ps 33,17", "℘ 2Mo 20,2; Jer 16,14", "℘ Kap. 7,21; 9,3; 31,6; Jos 1,5.9; Ri 6,12; Ps 46,8; Sach 10,5"] },
      { number: 2, text: "Und es soll geschehen, wenn ihr zum Kampf heranrückt, dann soll der Priester herantreten und zum Volk reden*", footnotes: ["℘ 4Mo 31,6"] },
      { number: 3, text: "und zu ihnen sagen: Höre, Israel! Ihr rückt heute zum Kampf gegen eure Feinde heran. Euer Herz verzage nicht, fürchtet euch nicht und ängstigt euch nicht und erschreckt nicht vor ihnen*!", footnotes: ["℘ Kap. 1,21.29; 2Mo 14,13; 4Mo 14,9; 1Sam 17,32"] },
      { number: 4, text: "Denn der HERR, euer Gott, ist es, der mit euch zieht, um für euch mit euren Feinden zu kämpfen, um euch zu retten.*", footnotes: ["℘ Kap. 1,30; Jos 10,11; 23,10; 1Sam 14,23; 1Chr 14,15; 2Chr 32,8"] },
      { number: 5, text: "Und die Aufseher* sollen zum Volk reden und sagen: Wer ist der Mann, der ein neues Haus gebaut und es noch nicht eingeweiht hat? Er mache sich auf und kehre in sein Haus zurück, damit er nicht in der Schlacht sterbe und ein anderer Mann es einweihe.", footnotes: ["w. Schreiber; d. i. eine Beamtenbezeichnung"] },
      { number: 6, text: "Und wer ist der Mann, der einen Weinberg gepflanzt und ihn noch nicht genutzt* hat*? Er mache sich auf und kehre in sein Haus zurück, damit er nicht in der Schlacht sterbe und ein anderer Mann ihn nutze*.", footnotes: ["w. entheiligt; d. h. dadurch, dass man ihn im 5. Jahr in Gebrauch nimmt; vgl. 3Mo 19,23—25", "℘ 1Kor 9,7", "w. entheilige"] },
      { number: 7, text: "Und wer ist der Mann, der sich mit einer Frau verlobt und sie noch nicht zu sich genommen hat? Er mache sich auf und kehre in sein Haus zurück, damit er nicht in der Schlacht sterbe und ein anderer Mann sie nehme*.", footnotes: ["℘ Kap. 24,5; 28,30"] },
      { number: 8, text: "Und die Aufseher* sollen weiter zum Volk reden und sagen: Wer ist der Mann, der sich fürchtet und ein verzagtes Herz hat? Er mache sich auf und kehre in sein Haus zurück, damit nicht das Herz seiner Brüder verzagt werde wie sein Herz*.", footnotes: ["w. Schreiber; d. i. eine Beamtenbezeichnung", "℘ Ri 7,3"] },
      { number: 9, text: "Und es soll geschehen, wenn die Aufseher* aufgehört haben, zum Volk zu reden, dann sollen sie Heeroberste an die Spitze des Volkes stellen*.", footnotes: ["w. Schreiber; d. i. eine Beamtenbezeichnung", "℘ 2Sam 18,1"] },
      { number: 10, text: "Wenn du dich einer Stadt näherst, um gegen sie zu kämpfen, dann sollst du ihr zunächst Frieden anbieten.*", footnotes: ["w. sollst du ihr zurufen: Zum Frieden!\n℘ Kap. 2,26; Ri 11,12"] },
      { number: 11, text: "Und es soll geschehen, wenn sie dir friedlich antwortet* und dir öffnet, dann soll alles Volk, das sich darin befindet, dir zur Zwangsarbeit unterworfen werden und dir dienen*.", footnotes: ["w. wenn sie dir antwortet: Friede!", "℘ 1Kö 5,1"] },
      { number: 12, text: "Und wenn sie mit dir nicht Frieden schließt, sondern Krieg mit dir führt, dann sollst du sie belagern." },
      { number: 13, text: "Und gibt der HERR, dein Gott, sie in deine Hand, dann sollst du all ihre Männlichen mit der Schärfe des Schwertes erschlagen.*", footnotes: ["℘ 4Mo 31,7.17; 1Kö 11,15"] },
      { number: 14, text: "Doch die Frauen und die Kinder und das Vieh und alles, was in der Stadt ist, all ihre Beute, sollst du für dich rauben. Und du sollst von der Beute deiner Feinde essen, die der HERR, dein Gott, dir gegeben hat*.", footnotes: ["℘ Kap. 2,35; 4Mo 31,9.53"] },
      { number: 15, text: "So sollst du mit allen Städten tun, die weit von dir entfernt sind*, die nicht von den Städten dieser Nationen hier sind.", footnotes: ["℘ Jos 9,9.26.27"] },
      { number: 16, text: "Jedoch von den Städten dieser Völker, die der HERR, dein Gott, dir als Erbteil gibt*, sollst du nichts leben lassen, was Odem hat*.", footnotes: ["℘ Kap. 4,21; 24,4", "℘ Kap. 7,2.16"] },
      { number: 17, text: "Sondern du sollst an ihnen unbedingt den Bann vollstrecken: an den Hetitern und an den Amoritern, den Kanaanitern und den Perisitern, den Hewitern und den Jebusitern*, wie der HERR, dein Gott, dir befohlen hat,", footnotes: ["℘ 1Mo 15,20.21"] },
      { number: 18, text: "damit sie euch nicht lehren, nach all ihren Gräueln zu tun, die sie ihren Göttern getan haben, und ihr so gegen den HERRN, euren Gott, sündigt*.", footnotes: ["℘ Kap. 7,4; 12,30.31; 18,9; 2Mo 23,32.33"] },
      { number: 19, text: "Wenn du eine Stadt viele Tage belagerst, um gegen sie zu kämpfen und sie einzunehmen, sollst du ihre Bäume nicht vernichten, indem du die Axt gegen sie schwingst. Denn du kannst von ihnen essen; du sollst sie nicht abhauen. Ist etwa der Baum des Feldes ein Mensch, dass er von dir mitbelagert werden sollte*?", footnotes: ["w. dass er vor dir in Belagerung kommen sollte\n℘ 2Kö 3,19.25"] },
      { number: 20, text: "Nur die Bäume, von denen du weißt, dass sie Bäume sind, von denen man nicht isst, die darfst du vernichten und umhauen*. Und du kannst Belagerungsgerät davon bauen gegen die Stadt, die Krieg mit dir führt, bis sie gefallen ist.", footnotes: ["℘ 2Kö 3,19.25"] },
    ]},
    { number: 21, verses: [
      { number: 1, text: "Wenn in dem Land, das der HERR, dein Gott, dir gibt, es in Besitz zu nehmen*, ein Erschlagener auf dem Feld liegend gefunden wird, ohne dass es bekannt ist, wer ihn erschlagen hat,", heading: "Totschlag durch unbekannten Täter", footnotes: ["℘ Kap. 3,18"] },
      { number: 2, text: "dann sollen deine Ältesten und deine Richter hinausgehen und die Strecke zu den Städten hin abmessen, die im Umkreis des Erschlagenen liegen." },
      { number: 3, text: "Und es soll geschehen: Die Stadt, die dem Erschlagenen am nächsten liegt — die Ältesten jener Stadt sollen eine junge Kuh nehmen, mit der noch nicht gearbeitet worden ist, die noch nicht am Joch gezogen hat*,", footnotes: ["℘ 4Mo 19,2; Kap. 10,8"] },
      { number: 4, text: "und die Ältesten jener Stadt sollen das Kalb zu einem immerfließenden Bach* hinabführen, wo nicht gearbeitet und nicht gesät wird, und sollen dem Kalb dort im Bach das Genick brechen.", footnotes: ["s. Anm. zu Kap. 2,13"] },
      { number: 5, text: "Dann sollen die Priester, die Söhne Levis, herantreten. Denn sie hat der HERR, dein Gott, erwählt, seinen Dienst zu verrichten und im Namen des HERRN zu segnen*; und nach ihrem Ausspruch soll man bei jedem Rechtsstreit und bei jeder Gewalttat* verfahren*.", footnotes: ["℘ 3Mo 9,22", "o. Körperverletzung", "℘ Kap. 17,8-10; 2Chr 19,10"] },
      { number: 6, text: "Und alle Ältesten jener Stadt, die dem Erschlagenen am nächsten sind, sollen über dem Kalb, dem das Genick im Bach gebrochen wurde, ihre Hände waschen*", footnotes: ["℘ Ps 26,6; Mt 27,24"] },
      { number: 7, text: "und sollen bezeugen und sagen: Unsere Hände haben dieses Blut nicht vergossen, und unsere Augen haben es nicht gesehen." },
      { number: 8, text: "Vergib*, HERR, deinem Volk Israel, das du erlöst hast, und lege nicht unschuldiges Blut in die Mitte deines Volkes Israel*! So wird ihnen die Blutschuld vergeben werden*.", footnotes: ["o. Schaff Sühne; w. Deck die Schuld zu", "d. h. dem Volk zur Last\n℘ Jon 1,14", "℘ 3Mo 17,4"] },
      { number: 9, text: "Und du, du sollst das unschuldige Blut aus deiner Mitte wegschaffen*; denn du sollst tun, was in den Augen des HERRN recht ist*.", footnotes: ["℘ Kap. 19,13", "℘ Kap. 12,25.28"] },
      { number: 10, text: "Wenn du gegen deine Feinde zum Krieg ausziehst und der HERR, dein Gott, sie in deine Hand gibt und du ihre Gefangenen wegführst", heading: "Ehe mit kriegsgefangenen Frauen" },
      { number: 11, text: "und du unter den Gefangenen eine Frau, schön von Gestalt, siehst und hängst an ihr und nimmst sie dir zur Frau," },
      { number: 12, text: "dann sollst du sie in das Innere deines Hauses bringen. Und sie soll ihr Haupt scheren und ihre Nägel beschneiden" },
      { number: 13, text: "und die Kleidung ihrer Gefangenschaft von sich ablegen und in deinem Haus bleiben und ihren Vater und ihre Mutter einen vollen Monat lang beweinen. Danach magst du zu ihr eingehen und sie heiraten*, so dass sie dir zur Frau wird.", footnotes: ["w. ihr Eheherr werden"] },
      { number: 14, text: "Und es soll geschehen, wenn du kein Gefallen mehr an ihr hast, dann sollst du sie nach ihrem Wunsch entlassen*. Aber du darfst sie keineswegs für Geld verkaufen; du sollst sie nicht als Sklavin behandeln*, weil du ihr Gewalt angetan hast.", footnotes: ["d. h. sie gehen lassen, wohin sie will. Andere üs. im Blick auf die zweite Vershälfte: dann sollst du sie zur freien Verfügung über sich selbst entlassen", "w. nicht gewalttätig behandeln\n℘ 2Mo 21,8"] },
      { number: 15, text: "Wenn ein Mann zwei Frauen hat, eine geliebte und eine gehasste*, und sie gebären ihm Söhne, die geliebte und die gehasste, und der erstgeborene Sohn ist von der gehassten,", heading: "Erbrecht des erstgeborenen Sohnes", footnotes: ["o. zurückgesetzte; o. nicht geliebte\n℘ 1Mo 29,30.31"] },
      { number: 16, text: "dann soll es geschehen an dem Tag, an dem er seine Söhne erben lässt, was ihm gehört, dass er nicht den Sohn der geliebten zum Erstgeborenen machen kann gegen den Sohn der gehassten, der doch der Erstgeborene ist*,", footnotes: ["℘ 2Chr 11,21.22"] },
      { number: 17, text: "vielmehr soll er den Erstgeborenen, den Sohn der gehassten, anerkennen, dass er ihm zwei Teile von allem gibt, was sich bei ihm findet*. Denn er ist der Erstling seiner Kraft*, ihm gehört das Recht der Erstgeburt*.", footnotes: ["℘ 1Chr 5,2", "℘ 1Mo 49,3", "℘ 1Mo 25,31; 2Chr 21,3"] },
      { number: 18, text: "Wenn ein Mann einen störrischen und widerspenstigen Sohn hat, der auf die Stimme seines Vaters und auf die Stimme seiner Mutter nicht hört*, und sie züchtigen ihn*, er aber hört weiterhin nicht auf sie,", heading: "Ein unverbesserlicher Sohn", footnotes: ["℘ Kap. 27,16; 2Mo 20,12", "℘ Spr 19,18"] },
      { number: 19, text: "dann sollen sein Vater und seine Mutter ihn ergreifen und ihn hinausführen zu den Ältesten seiner Stadt und zum Tor seines Ortes." },
      { number: 20, text: "Und sie sollen zu den Ältesten seiner Stadt sagen: Dieser unser Sohn ist störrisch und widerspenstig, er hört nicht auf unsere Stimme, er ist ein Schlemmer und Säufer*!", footnotes: ["℘ Spr 23,19-21"] },
      { number: 21, text: "Dann sollen ihn alle Leute seiner Stadt steinigen, dass er stirbt*; so sollst du das Böse aus deiner Mitte wegschaffen.* Und ganz Israel soll es hören und sich fürchten*.", footnotes: ["℘ 2Mo 21,17; 3Mo 20,2; Spr 30,17", "℘ Kap. 17,7.12", "℘ Kap. 13,12"] },
      { number: 22, text: "Und wenn bei einem Mann eine Sünde geschieht, auf die das Todesurteil steht, und er wird getötet, und du hängst ihn an ein Holz*,", heading: "Bestattung Hingerichteter", footnotes: ["o. an einen Baum\n℘ 1Mo 40,19; 4Mo 25,4; 2Sam 4,12; 21,9.10; Apg 2,36; 5,30"] },
      { number: 23, text: "dann darf seine Leiche nicht über Nacht an dem Holz* bleiben*, sondern du sollst ihn unbedingt am selben Tag begraben*. Denn ein Aufgehängter ist ein Fluch Gottes*. So sollst du dein Land nicht unrein machen*, das der HERR, dein Gott, dir als Erbteil gibt*.", footnotes: ["o. an dem Baum", "℘ Jos 8,29", "℘ Jos 10,26.27; Mk 15,43-46; Joh 19,31", "℘ Gal 3,13", "℘ 4Mo 35,34", "℘ Kap. 4,21; 25,19"] },
    ]},
    { number: 22, verses: [
      { number: 1, text: "Nicht darfst du zusehen, wie das Rind deines Bruders oder sein Schaf umherirrt und dich ihnen entziehen; du sollst sie deinem Bruder unbedingt zurückbringen.*", heading: "Achtung des Eigentums anderer", footnotes: ["℘ 2Mo 23,4.5"] },
      { number: 2, text: "Wenn aber dein Bruder nicht nahe bei dir wohnt oder du ihn nicht kennst, dann sollst du es in dein Haus aufnehmen, und es soll bei dir sein, bis dein Bruder es sucht. Dann gib es ihm zurück!" },
      { number: 3, text: "Und ebenso sollst du es mit seinem Esel machen, ebenso sollst du es mit seinem Gewand machen, und ebenso sollst du es mit allem Verlorenen deines Bruders machen, das ihm verloren geht und das du findest; du kannst dich nicht entziehen." },
      { number: 4, text: "Du darfst nicht zusehen, wie der Esel deines Bruders oder sein Rind auf dem Weg fallen, und dich ihnen entziehen; du sollst sie unbedingt mit ihm aufrichten." },
      { number: 5, text: "Männerzeug darf nicht auf einer Frau sein, und ein Mann darf nicht das Gewand einer Frau anziehen. Denn jeder, der dieses tut, ist ein Gräuel für den HERRN, deinen Gott*.", heading: "Verschiedene Vorschriften", footnotes: ["℘ Kap. 18,12"] },
      { number: 6, text: "Wenn sich zufällig ein Vogelnest vor dir auf dem Weg* findet, auf irgendeinem Baum oder auf der Erde, mit Jungen oder mit Eiern, und die Mutter sitzt auf den Jungen oder auf den Eiern, dann darfst du die Mutter auf den Jungen nicht nehmen.", footnotes: ["d. h. unterwegs"] },
      { number: 7, text: "Du sollst die Mutter unbedingt fliegen lassen, die Jungen aber magst du dir nehmen*, damit es dir gut geht und du deine Tage verlängerst.", footnotes: ["℘ 3Mo 22,28"] },
      { number: 8, text: "Wenn du ein neues Haus baust, dann sollst du ein Geländer um dein Dach machen, damit du nicht Blutschuld auf dein Haus bringst, wenn irgendjemand von ihm herabfällt." },
      { number: 9, text: "Du sollst deinen Weinberg nicht mit zweierlei Samen besäen*, damit nicht das Ganze dem Heiligtum verfällt: der Same, den du gesät hast, und der Ertrag des Weinberges. —", footnotes: ["℘ 3Mo 19,19; 2Kor 6,14"] },
      { number: 10, text: "Du sollst nicht mit einem Rind und einem Esel zusammen pflügen*. —", footnotes: ["℘ 3Mo 19,19; 2Kor 6,14"] },
      { number: 11, text: "Du sollst nicht Gewebe von verschiedenartigem Stoff anziehen, Wolle und Leinen zusammen*.", footnotes: ["℘ 3Mo 19,19; 2Kor 6,14"] },
      { number: 12, text: "Quasten sollst du dir machen an den vier Zipfeln deines Oberkleides, mit dem du dich kleidest.*", footnotes: ["℘ 4Mo 15,38; Mt 23,5; Lk 8,44"] },
      { number: 13, text: "Wenn ein Mann eine Frau nimmt und zu ihr eingeht, und er hasst sie*", heading: "Schutz der Frau vor Verleumdung und Vergewaltigung", footnotes: ["o. wird ihrer überdrüssig"] },
      { number: 14, text: "und legt ihr Taten zur Last, die sie ins Gerede bringen*, und bringt sie in schlechten Ruf* und sagt: Diese Frau habe ich genommen und mich ihr genaht und habe die Zeichen der Jungfrauschaft nicht an ihr gefunden!,", footnotes: ["w. legt Taten des Geredes auf sie", "w. lässt einen schlechten Namen über sie herausgehen"] },
      { number: 15, text: "dann sollen der Vater der jungen Frau und ihre Mutter die Zeichen der Jungfrauschaft der jungen Frau nehmen und zu den Ältesten der Stadt ins Tor hinausbringen." },
      { number: 16, text: "Dann soll der Vater der jungen Frau zu den Ältesten sagen: Ich habe meine Tochter diesem Mann zur Frau gegeben, und er hasst sie." },
      { number: 17, text: "Und siehe, er legt ihr Taten zur Last, die sie ins Gerede bringen*, indem er sagt: Ich habe an deiner Tochter die Zeichen der Jungfrauschaft nicht gefunden! Dies hier sind nun die Zeichen der Jungfrauschaft meiner Tochter. Und sie sollen das Tuch vor den Ältesten der Stadt ausbreiten.", footnotes: ["w. legt Taten des Geredes auf sie"] },
      { number: 18, text: "Und die Ältesten jener Stadt sollen den Mann nehmen und ihn züchtigen." },
      { number: 19, text: "Und sie sollen ihm eine Geldbuße von hundert Schekel Silber auferlegen und sie dem Vater der jungen Frau geben, weil er eine Jungfrau in Israel in schlechten Ruf gebracht hat*. Und sie soll weiterhin seine Frau sein; er kann sie nicht entlassen alle seine Tage*. —", footnotes: ["w. weil er einen schlechten Namen über eine Jungfrau Israels herausgehen ließ", "℘ Mt 19,6"] },
      { number: 20, text: "Wenn aber jene Sache Wahrheit gewesen ist, die Zeichen der Jungfrauschaft sind an der jungen Frau nicht gefunden worden," },
      { number: 21, text: "dann sollen sie die junge Frau hinausführen an den Eingang des Hauses ihres Vaters, und die Männer ihrer Stadt sollen sie steinigen*, dass sie stirbt, weil sie eine Schandtat in Israel verübt hat*, zu huren im Haus ihres Vaters*. Und du sollst das Böse aus deiner Mitte wegschaffen*.", footnotes: ["℘ 3Mo 20,2", "℘ 1Mo 34,7", "℘ 1Mo 38,24", "℘ Kap. 17,7.12"] },
      { number: 22, text: "Wenn ein Mann bei einer Frau liegend angetroffen wird, die einem Mann* gehört, dann sollen sie alle beide sterben*, der Mann, der bei der Frau lag, und die Frau. Und du sollst das Böse aus Israel wegschaffen*.", footnotes: ["w. einem Eheherrn", "℘ 3Mo 20,10; Hes 16,38", "℘ Kap. 17,7.12"] },
      { number: 23, text: "Wenn ein Mädchen, eine Jungfrau, einem Mann verlobt ist, und es trifft sie ein Mann in der Stadt und liegt bei ihr," },
      { number: 24, text: "dann sollt ihr sie beide zum Tor jener Stadt hinausführen und sie steinigen, dass sie sterben*; das Mädchen deshalb, weil es in der Stadt nicht geschrien hat, und den Mann deshalb, weil er der Frau seines Nächsten Gewalt angetan hat. Und du sollst das Böse aus deiner Mitte wegschaffen*. —", footnotes: ["℘ Kap. 17,7.12", "℘ Kap. 17,7.12"] },
      { number: 25, text: "Wenn aber der Mann das verlobte Mädchen auf dem Feld trifft, und der Mann ergreift sie und liegt bei ihr, dann soll der Mann, der bei ihr gelegen hat, allein sterben." },
      { number: 26, text: "Aber dem Mädchen sollst du nichts tun, das Mädchen hat keine Sünde begangen zum Tode*. Diese Sache ist vielmehr so, wie wenn ein Mann sich erhebt gegen seinen Nächsten und ihn totschlägt.", footnotes: ["℘ 1Jo 5,16.17"] },
      { number: 27, text: "Denn er hat sie auf dem Feld getroffen. Das verlobte Mädchen schrie, aber niemand war da, der es rettete." },
      { number: 28, text: "Wenn ein Mann ein Mädchen trifft, eine Jungfrau, die nicht verlobt ist, und ergreift sie und liegt bei ihr, und sie werden dabei angetroffen," },
      { number: 29, text: "dann soll der Mann, der bei ihr lag, dem Vater des Mädchens fünfzig Schekel Silber geben*, und es soll seine Frau werden, weil er ihr Gewalt angetan hat; er kann sie nicht entlassen all seine Tage*.", footnotes: ["℘ 2Mo 22,15.16", "℘ Mt 19,6"] },
    ]},
    { number: 23, verses: [
      { number: 1, text: "Ein Mann darf nicht die Frau seines Vaters nehmen und darf die Decke* seines Vaters nicht aufdecken.*", footnotes: ["w. den Zipfel des Obergewandes", "℘ Kap. 27,20; 3Mo 18,8"] },
      { number: 2, text: "Einer, dem die Hoden zerstoßen sind oder die Harnröhre abgeschnitten ist, darf nicht in die Versammlung des HERRN kommen*.", heading: "Zugehörigkeit zur Gemeinde des HERRN", footnotes: ["℘ 3Mo 21,20; Jes 56,3-5"] },
      { number: 3, text: "Ein Bastard darf nicht in die Versammlung des HERRN kommen; auch die zehnte Generation von ihm soll nicht in die Versammlung des HERRN kommen. —" },
      { number: 4, text: "Ein Ammoniter oder Moabiter darf nicht in die Versammlung des HERRN kommen; auch die zehnte Generation von ihnen darf nicht in die Versammlung des HERRN kommen, für ewig*;", footnotes: ["℘ Esr 9,1; Kla 1,10; Hes 44,9"] },
      { number: 5, text: "deshalb, weil sie euch nicht mit Brot und mit Wasser entgegengekommen sind auf dem Weg, als ihr aus Ägypten zogt*, und weil er* Bileam, den Sohn des Beor, aus Petor in Mesopotamien, gegen dich angeheuert hat, dich zu verfluchen.*", footnotes: ["℘ Kap. 2,29", "Gemeint ist wohl Balak.", "℘ 4Mo 22,5.6"] },
      { number: 6, text: "Aber der HERR, dein Gott, wollte nicht auf Bileam hören, und der HERR, dein Gott, wandelte dir den Fluch in Segen um*; denn der HERR, dein Gott, hatte dich lieb*.", footnotes: ["℘ 4Mo 24,10; 2Sam 16,12; Mi 6,5", "℘ Kap. 7,8"] },
      { number: 7, text: "Du sollst ihren Frieden und ihr Wohl nicht suchen alle deine Tage, für ewig*.", footnotes: ["℘ Esr 9,12; Mt 5,43"] },
      { number: 8, text: "Den Edomiter sollst du nicht verabscheuen*, denn er ist dein Bruder*. Den Ägypter sollst du nicht verabscheuen, denn du bist ein Fremder in seinem Land gewesen*.", footnotes: ["d. h. nicht als kultisch unrein verabscheuen", "℘ 1Mo 25,25.26; Ob 10-12", "℘ Kap. 10,19; 2Mo 22,20; 3Mo 19,34; 1Sam 30,11; Esr 9,1"] },
      { number: 9, text: "Kinder, die ihnen geboren werden, dürfen von ihnen in der dritten Generation* in die Versammlung des HERRN kommen*.", footnotes: ["so mit anderer Zeichensetzung; Mas. T.: Kinder, die ihnen in der dritten Generation geboren werden, mögen von ihnen", "℘ Jes 56,3"] },
      { number: 10, text: "Wenn du gegen deine Feinde ins Kriegslager ausziehst, dann sollst du dich vor allem Bösen hüten*:", heading: "Reinerhaltung des Kriegslagers", footnotes: ["℘ Jos 6,18"] },
      { number: 11, text: "Wenn ein Mann unter dir ist, der durch einen Zufall der Nacht nicht rein ist, dann soll er nach draußen vor das Lager hinausgehen. Er darf nicht ins Lager hineinkommen." },
      { number: 12, text: "Und es soll geschehen, beim Anbruch des Abends soll er sich im Wasser baden, und beim Untergang der Sonne darf er wieder ins Lager kommen*.", footnotes: ["℘ 3Mo 15,16.17"] },
      { number: 13, text: "Und du sollst einen Platz außerhalb des Lagers haben, dahin kannst du hinausgehen, um auszutreten." },
      { number: 14, text: "Und du sollst eine Schaufel bei deinem Gerät haben. Und es soll geschehen, wenn du dich draußen hinsetzt, so sollst du ein Loch damit graben und deine Ausscheidung wieder zudecken." },
      { number: 15, text: "Denn der HERR, dein Gott, lebt* mitten in deinem Lager*, um dich zu retten* und deine Feinde vor dir dahinzugeben. Und dein Lager soll heilig sein, dass er nichts Anstößiges* unter dir sieht und sich von dir abwendet*.", footnotes: ["w. geht hin und her", "℘ 3Mo 26,12; Jes 12,6", "℘ Ps 78,65; Zef 3,17", "w. die Blöße einer Sache", "℘ 4Mo 5,3; Hab 1,13"] },
      { number: 16, text: "Einen Sklaven, der sich vor seinem Herrn zu dir rettet, sollst du seinem Herrn nicht ausliefern.", heading: "Vorschriften über Sklaven, Huren, Zinsen, Gelübde und Fremdeigentum" },
      { number: 17, text: "Bei dir soll er wohnen, in deiner Mitte, an dem Ort, den er in einem deiner Tore erwählen wird, wo es ihn gut dünkt: du sollst ihn nicht unterdrücken." },
      { number: 18, text: "Eine Geweihte* soll es unter den Töchtern Israel nicht geben*, und auch einen Geweihten* soll es nicht unter den Söhnen Israel geben*.", footnotes: ["Das sind weibliche und männliche Tempelprostituierte im Dienst der Fruchtbarkeitsgöttin Astarte. Der Lohn der Kultprostitution war für den Tempel der Astarte bestimmt.", "℘ 3Mo 19,29", "Das sind weibliche und männliche Tempelprostituierte im Dienst der Fruchtbarkeitsgöttin Astarte. Der Lohn der Kultprostitution war für den Tempel der Astarte bestimmt.", "℘ 1Kö 14,24"] },
      { number: 19, text: "Du sollst keinen Hurenlohn und kein Hundegeld* in das Haus des HERRN, deines Gottes, bringen für irgendein Gelübde; denn auch diese beiden sind ein Gräuel für den HERRN, deinen Gott.", footnotes: ["Als Hunde wurden männliche Kultprostituierte bezeichnet."] },
      { number: 20, text: "Du sollst deinem Bruder keinen Zins auferlegen, Zins für Geld, Zins für Speise, Zins für irgendeine Sache, die man gegen Zins ausleiht.*", footnotes: ["℘ 2Mo 22,24; Ps 15,5; Hes 18,8"] },
      { number: 21, text: "Dem Fremden magst du Zins auferlegen, aber deinem Bruder darfst du nicht Zins auferlegen*, damit der HERR, dein Gott, dich segnet in allem Geschäft deiner Hand* in dem Land, in das du kommst, um es in Besitz zu nehmen.", footnotes: ["℘ 2Mo 22,24; Ps 15,5; Hes 18,8", "℘ Kap. 14,29; 15,3"] },
      { number: 22, text: "Wenn du für den HERRN, deinen Gott, ein Gelübde ablegst, sollst du nicht zögern, es zu erfüllen. Denn der HERR, dein Gott, wird es unbedingt von dir fordern, und Sünde würde an dir sein.*", footnotes: ["℘ 3Mo 27,2; Jos 9,18; Ps 50,14; 66,13; Spr 20,25; Mt 5,33"] },
      { number: 23, text: "Wenn du es aber unterlässt, etwas zu geloben, wird keine Sünde an dir sein.*", footnotes: ["℘ 3Mo 27,2; Jos 9,18; Ps 50,14; 66,13; Spr 20,25; Mt 5,33"] },
      { number: 24, text: "Was über deine Lippen gegangen ist, sollst du halten und ausführen, wie du dem HERRN, deinem Gott, freiwillig gelobt hast, was du mit deinem Mund geredet hast.*", footnotes: ["℘ 3Mo 27,2; Jos 9,18; Ps 50,14; 66,13; Spr 20,25; Mt 5,33"] },
      { number: 25, text: "Wenn du in den Weinberg deines Nächsten kommst, dann magst du Trauben essen nach Herzenslust*, bis du satt bist; in dein Gefäß aber darfst du nichts tun.", footnotes: ["w. deiner Kehle entsprechend"] },
      { number: 26, text: "Wenn du in das Getreidefeld deines Nächsten kommst, dann darfst du Ähren mit deiner Hand abpflücken*; aber die Sichel sollst du nicht über das Getreide deines Nächsten schwingen.", footnotes: ["℘ Mt 12,1"] },
    ]},
    { number: 24, verses: [
      { number: 1, text: "Wenn ein Mann eine Frau nimmt und sie heiratet* und es geschieht, dass sie keine Gunst in seinen Augen findet, weil er etwas Anstößiges* an ihr gefunden hat und er ihr einen Scheidebrief geschrieben, ihn in ihre Hand gegeben und sie aus seinem Haus entlassen hat*,", heading: "Vorschriften über den Scheidebrief — Kriegsdienst der Jungverheirateten", footnotes: ["w. ihr Eheherr wird", "w. die Blöße einer Sache", "℘ Jes 50,1; Jer 3,8; Mt 1,19; 5,31; Mk 10,4"] },
      { number: 2, text: "und sie ist aus seinem Haus gezogen und ist hingegangen und die Frau eines anderen Mannes geworden," },
      { number: 3, text: "wenn dann auch der andere Mann sie gehasst und ihr einen Scheidebrief geschrieben, ihn in ihre Hand gegeben und sie aus seinem Haus entlassen hat oder wenn der andere Mann stirbt, der sie sich zur Frau genommen hat," },
      { number: 4, text: "dann kann ihr erster Mann, der sie entlassen hat, sie nicht wieder nehmen, dass sie seine Frau sei, nachdem sie unrein gemacht worden ist. Denn ein Gräuel ist das vor dem HERRN*. Und du sollst das Land, das der HERR, dein Gott, dir als Erbteil gibt*, nicht zur Sünde verführen.", footnotes: ["℘ Jer 3,1", "℘ Kap. 4,21"] },
      { number: 5, text: "Wenn ein Mann erst kurz verheiratet ist*, soll er nicht mit dem Heer ausziehen*, und es soll ihm keinerlei Verpflichtung* auferlegt werden. Er soll ein Jahr lang frei sein für sein Haus und seine Frau, die er genommen hat, erfreuen.", footnotes: ["w. eine neue Frau nimmt", "℘ Kap. 20,7", "w. keinerlei Sache"] },
      { number: 6, text: "Man soll nicht Handmühle und Mühlstein* pfänden, denn damit pfändet man das Leben.", heading: "Schutz der Schwachen", footnotes: ["d. h. den oberen Stein, den Läufer"] },
      { number: 7, text: "Wenn ein Mann gefunden wird, der einen von seinen Brüdern, einen von den Söhnen Israel, geraubt hat und ihn als Sklaven* behandelt und verkauft hat, dann soll dieser Dieb sterben*. Und du sollst das Böse aus deiner Mitte wegschaffen*.", footnotes: ["w. gewalttätig", "℘ 2Mo 21,16; 1Tim 1,10", "℘ Kap. 17,7.12"] },
      { number: 8, text: "Bei der Plage des Aussatzes hüte dich, dass du sehr darauf achtest und alles tust, was euch die Priester, die Leviten, lehren werden. Ihr sollt darauf achten, zu tun, wie ich ihnen befohlen habe*.", footnotes: ["℘ 3Mo 13; 14"] },
      { number: 9, text: "Denk daran, was der HERR, dein Gott, an Mirjam getan hat auf dem Weg, als ihr aus Ägypten zogt!*", footnotes: ["℘ 4Mo 12,10"] },
      { number: 10, text: "Wenn du deinem Nächsten irgendein Darlehen leihst, dann sollst du nicht in sein Haus hineingehen, um von ihm ein Pfand zu erheben." },
      { number: 11, text: "Draußen sollst du stehen bleiben, und der Mann, dem du geliehen hast, soll das Pfand zu dir nach draußen hinausbringen." },
      { number: 12, text: "Und wenn er ein bedürftiger Mann ist, sollst du dich nicht mit seinem Pfand schlafen legen*.", footnotes: ["℘ Hi 22,6"] },
      { number: 13, text: "Du sollst ihm das Pfand unbedingt beim Untergang der Sonne zurückgeben, damit er sich in seinem Mantel schlafen lege* und dich segne*; und es wird für dich als Gerechtigkeit gelten vor dem HERRN, deinem Gott*.", footnotes: ["℘ 2Mo 22,25.26; Hi 24,7.10", "℘ Hi 29,13", "℘ Kap. 6,25"] },
      { number: 14, text: "Du sollst den bedürftigen und armen Lohnarbeiter* nicht unterdrücken, sei er einer von deinen Brüdern oder von deinen Fremden, die in deinem Land, in deinen Toren wohnen.", footnotes: ["o. Tagelöhner"] },
      { number: 15, text: "Am selben Tag sollst du ihm seinen Lohn geben, und die Sonne soll nicht darüber untergehen* — denn er ist bedürftig und verlangt sehnsüchtig danach* —, damit er nicht über dich zum HERRN schreit* und Sünde an dir ist*.", footnotes: ["℘ 3Mo 19,13; Eph 4,26", "w. und dazu erhebt er seine Seele", "℘ Jak 5,4", "℘ Kap. 15,9"] },
      { number: 16, text: "Nicht sollen Väter um der Söhne willen* getötet werden und Söhne sollen nicht um der Väter willen* getötet werden; sie sollen jeder für seine eigene Sünde getötet werden*.", footnotes: ["o. samt den Söhnen bzw. samt den Vätern", "o. samt den Söhnen bzw. samt den Vätern", "℘ 1Sam 22,16; 2Kö 14,6; Jer 31,29.30; Hes 18,4.20"] },
      { number: 17, text: "Du sollst das Recht eines Fremden und einer Waise nicht beugen*, und das Kleid einer Witwe sollst du nicht pfänden.", footnotes: ["℘ Kap. 27,19; 2Mo 22,20.21; Hi 24,3.9; Jer 22,3; Mal 3,5"] },
      { number: 18, text: "Und du sollst daran denken, dass du Sklave in Ägypten warst und dass der HERR, dein Gott, dich von dort erlöst hat; darum befehle ich dir, dieses Wort zu befolgen.*", footnotes: ["℘ Kap. 5,15"] },
      { number: 19, text: "Wenn du deine Ernte auf deinem Feld einbringst und hast eine Garbe auf dem Feld vergessen, sollst du nicht umkehren, um sie zu holen: Für den Fremden, für die Waise und für die Witwe soll sie sein*, damit der HERR, dein Gott, dich segnet in allem Tun deiner Hände*.", footnotes: ["℘ 3Mo 19,9.10", "℘ Kap. 14,29"] },
      { number: 20, text: "Wenn du deine Oliven abschlägst, sollst du nicht hinterher* die Zweige absuchen: Für den Fremden, für die Waise und für die Witwe soll es sein.", footnotes: ["w. hinter dir"] },
      { number: 21, text: "Wenn du in deinem Weinberg Lese hältst, sollst du nicht hinterher* Nachlese halten*: Für den Fremden, für die Waise und für die Witwe soll es sein.", footnotes: ["w. hinter dir", "℘ 3Mo 19,9.10"] },
      { number: 22, text: "Und du sollst daran denken, dass du Sklave warst im Land Ägypten; darum befehle ich dir, dieses Wort zu befolgen.*", footnotes: ["℘ Kap. 5,15"] },
    ]},
    { number: 25, verses: [
      { number: 1, text: "Wenn ein Rechtsstreit zwischen Männern entsteht und sie vor Gericht treten, und man richtet sie*, dann soll man den Gerechten gerecht sprechen und den Schuldigen schuldig*.", heading: "Prügelstrafe", footnotes: ["℘ Kap. 16,18; 17,9", "℘ Spr 17,15; Jes 5,20; Kla 3,35.36"] },
      { number: 2, text: "Und es soll geschehen, wenn der Schuldige Schläge verdient hat, dann soll der Richter ihn hinlegen und ihm in seiner Gegenwart nach der festgesetzten Zahl Schläge geben lassen, seiner Schuld entsprechend*.", footnotes: ["℘ Lk 12,47; Apg 5,40"] },
      { number: 3, text: "Vierzig Schläge darf er ihm geben lassen — nicht mehr* —, damit nicht, wenn er fortfährt, ihn über diese hinaus mit vielen Schlägen zu schlagen, dein Bruder in deinen Augen entehrt wird.", footnotes: ["℘ 2Kor 11,24"] },
      { number: 4, text: "Du sollst dem Ochsen* nicht das Maul verbinden, wenn er drischt.*", footnotes: ["w. dem Rind", "℘ 1Kor 9,9; 1Tim 5,18"] },
      { number: 5, text: "Wenn Brüder zusammen wohnen und einer von ihnen stirbt und hat keinen Sohn, dann soll die Frau des Verstorbenen nicht auswärts einem fremden Mann angehören. Ihr Schwager soll zu ihr eingehen und sie sich zur Frau nehmen und mit ihr die Schwagerehe vollziehen*.", heading: "Schwagerehe", footnotes: ["℘ Mt 22,24"] },
      { number: 6, text: "Und es soll geschehen: Der Erstgeborene, den sie dann gebiert, soll den Namen seines verstorbenen Bruders weiterführen*, damit dessen Name aus Israel nicht ausgelöscht wird*.", footnotes: ["w. soll sich auf den Namen seines Bruders erheben\n℘ 1Mo 38,8.9", "℘ Rt 4,10"] },
      { number: 7, text: "Wenn aber der Mann keine Lust hat, seine Schwägerin zu nehmen, dann soll seine Schwägerin ins Tor hinaufgehen zu den Ältesten* und soll sagen: Mein Schwager weigert sich, seinem Bruder den Namen in Israel aufrechtzuerhalten; er will die Schwagerehe mit mir nicht eingehen.", footnotes: ["℘ Rt 4,2.11"] },
      { number: 8, text: "Und die Ältesten seiner Stadt sollen ihn rufen und mit ihm reden. Doch stellt er sich dann hin und sagt: Ich habe keine Lust, sie zu nehmen*,", footnotes: ["℘ Rt 4,6-8"] },
      { number: 9, text: "dann soll seine Schwägerin vor den Augen der Ältesten zu ihm hintreten und ihm den Schuh von seinem Fuß abziehen* und ihm ins Gesicht spucken*. Und sie soll antworten und sagen: So soll dem Mann geschehen, der das Haus seines Bruders nicht bauen will!", footnotes: ["℘ Rt 4,6-8", "℘ 4Mo 12,14"] },
      { number: 10, text: "Und sein Name soll in Israel heißen »Haus des Barfüßers«." },
      { number: 11, text: "Wenn Männer miteinander raufen, ein Mann und sein Bruder, und die Frau des einen eilt herbei, um ihren Mann aus der Hand dessen, der ihn schlägt, zu retten, und sie streckt ihre Hand aus und greift an seine Geschlechtsteile*,", heading: "Warnung vor unzüchtigem Verhalten und falschen Gewichten", footnotes: ["o. sie greift an dessen Schamteile; d. h. dessen, der den Ehemann schlägt"] },
      { number: 12, text: "dann sollst du ihr die Hand abhauen; du sollst nicht schonen*.", footnotes: ["w. dein Auge soll nicht fließen\n℘ Kap. 13,9"] },
      { number: 13, text: "Du sollst nicht zweierlei Gewichtsteine in deinem Beutel haben, einen großen und einen kleinen." },
      { number: 14, text: "Du sollst nicht zweierlei Efa in deinem Haus haben, ein großes und ein kleines." },
      { number: 15, text: "Vollen und gerechten Gewichtstein sollst du haben, und volles und gerechtes Efa sollst du haben*, damit deine Tage lange währen in dem Land, das der HERR, dein Gott, dir gibt*.", footnotes: ["℘ 3Mo 19,35.36; Am 8,5", "℘ Kap. 4,40"] },
      { number: 16, text: "Denn ein Gräuel für den HERRN, deinen Gott, ist jeder, der dieses tut, jeder, der Unrecht tut*.", footnotes: ["℘ Spr 11,1; Mi 6,10.11"] },
      { number: 17, text: "Denk daran, was Amalek dir getan hat auf dem Weg, als ihr aus Ägypten zogt,", heading: "Gebot der Ausrottung der Amalekiter" },
      { number: 18, text: "wie er dir auf dem Weg entgegentrat und deine Nachzügler schlug*, alle Schwachen hinter dir, als du erschöpft und müde warst*, und dass er Gott nicht fürchtete*.", footnotes: ["w. den Schwanz des Zuges bei dir abschnitt (nämlich alle Marschunfähigen)", "℘ 2Mo 17,8", "℘ Röm 3,18"] },
      { number: 19, text: "Und wenn der HERR, dein Gott, dir Ruhe verschafft hat vor allen deinen Feinden ringsum in dem Land, das der HERR, dein Gott, dir als Erbteil gibt, es in Besitz zu nehmen*, dann sollst du die Erwähnung Amaleks unter dem Himmel auslöschen. Vergiss es nicht!*", footnotes: ["℘ Kap. 3,18", "℘ 2Mo 17,14-16"] },
    ]},
    { number: 26, verses: [
      { number: 1, text: "Und es soll geschehen, wenn du in das Land kommst, das der HERR, dein Gott, dir als Erbteil gibt, und du hast es in Besitz genommen und wohnst darin*,", heading: "Darbringung der Erstlingsfrüchte", footnotes: ["℘ Kap. 4,21"] },
      { number: 2, text: "dann sollst du von den Erstlingen aller Frucht des Erdbodens nehmen*, die du von deinem Land einbringst, das der HERR, dein Gott, dir gibt, und sollst sie in einen Korb legen und an die Stätte gehen, die der HERR, dein Gott, erwählen wird, um seinen Namen dort wohnen zu lassen*.", footnotes: ["℘ 2Mo 34,26; 3Mo 2,14; 4Mo 18,12", "℘ Kap. 12,5"] },
      { number: 3, text: "Und du sollst zu dem Priester kommen, der in jenen Tagen da ist, und zu ihm sagen: Ich bezeuge heute dem HERRN, deinem Gott, dass ich in das Land gekommen bin, das uns zu geben der HERR unseren Vätern geschworen hat*.", footnotes: ["℘ Kap. 1,8"] },
      { number: 4, text: "Und der Priester soll den Korb aus deiner Hand nehmen und ihn vor den Altar des HERRN, deines Gottes, niedersetzen." },
      { number: 5, text: "Du aber sollst vor dem HERRN, deinem Gott, anheben und sprechen: Ein umherirrender* Aramäer war mein Vater*, und er zog nach Ägypten hinab und hielt sich dort als Fremder auf, als ein geringes Häuflein*. Doch er wurde dort zu einer großen, starken und zahlreichen Nation*.", footnotes: ["o. umkommender", "℘ 1Mo 28,5; Hos 12,13", "w. als gezählte Männer", "℘ Kap. 10,22; 1Mo 46,3-7; 2Mo 1,7.12; Jes 51,2"] },
      { number: 6, text: "Und die Ägypter misshandelten uns, unterdrückten uns und legten uns harte Arbeit auf*.", footnotes: ["℘ 2Mo 1,11-14; 4Mo 20,15"] },
      { number: 7, text: "Da schrien wir zu dem HERRN, dem Gott unserer Väter, und der HERR hörte unsere Stimme und sah unser Elend und unsere Mühsal und unsere Bedrängnis.*", footnotes: ["℘ 2Mo 2,23-25"] },
      { number: 8, text: "Und der HERR führte uns aus Ägypten heraus mit starker Hand und mit ausgestrecktem Arm* und mit großem Schrecken und mit Zeichen und Wundern*.", footnotes: ["℘ Kap. 5,15; 2Mo 6,6; 13,3.14", "o. Wahrzeichen\n℘ Kap. 4,34"] },
      { number: 9, text: "Und er brachte uns an diese Stätte und gab uns dieses Land, ein Land, das von Milch und Honig überfließt*.", footnotes: ["℘ Kap. 6,3"] },
      { number: 10, text: "Und nun siehe, ich habe die Erstlinge der Frucht des Landes gebracht, das du, HERR, mir gegeben hast. — Und du sollst sie vor dem HERRN, deinem Gott, niederlegen* und anbeten* vor dem HERRN, deinem Gott.", footnotes: ["℘ 2Mo 23,19", "w. dich niederwerfen"] },
      { number: 11, text: "Und du sollst dich an all dem Guten freuen, das der HERR, dein Gott, dir und deinem Haus gegeben hat, du und der Levit und der Fremde, der in deiner Mitte wohnt*.", footnotes: ["℘ Kap. 12,7.12.18"] },
      { number: 12, text: "Wenn du den ganzen Zehnten deines Ertrages* im dritten Jahr, dem Jahr des Zehnten, vollständig entrichtet hast und ihn dem Leviten, dem Fremden, der Waise und der Witwe gegeben hast, damit sie in deinen Toren essen und sich sättigen*,", heading: "Gebet zur Abgabe des Zehnten für die Armen", footnotes: ["℘ 1Mo 47,24.26", "℘ Kap. 14,28.29"] },
      { number: 13, text: "dann sollst du vor dem HERRN, deinem Gott, sprechen: Ich habe das Geheiligte aus dem Haus weggeschafft und habe es auch dem Leviten und dem Fremden, der Waise und der Witwe gegeben nach all deinem Gebot, das du mir befohlen hast; ich habe deine Gebote nicht übertreten noch vergessen*.", footnotes: ["℘ Ps 18,22"] },
      { number: 14, text: "Ich habe nichts davon gegessen in meiner Trauer* und habe nichts davon in meiner Unreinheit weggeschafft und habe nichts davon für einen Toten gegeben*. Ich habe der Stimme des HERRN, meines Gottes, gehorcht*, ich habe getan nach allem, was du mir geboten hast*.", footnotes: ["℘ Hos 9,4", "℘ Jer 16,7", "℘ Kap. 13,5.19; 15,5", "℘ Ps 18,22"] },
      { number: 15, text: "Blicke herab von deiner heiligen Wohnung vom Himmel*, und segne dein Volk Israel und das Land, das du uns gegeben, wie du es unseren Vätern geschworen hast*, ein Land, das von Milch und Honig überfließt*!", footnotes: ["℘ 1Kö 8,43; Ps 80,15; 102,20; Jes 63,15", "℘ Kap. 6,3", "℘ Kap. 6,3"] },
      { number: 16, text: "Am heutigen Tag befiehlt dir der HERR, dein Gott, diese Ordnungen und Rechtsbestimmungen zu tun. So bewahre und tue sie mit deinem ganzen Herzen und mit deiner ganzen Seele!*", heading: "Bundeszuspruch und Bundestreue", footnotes: ["℘ Kap. 10,12.13"] },
      { number: 17, text: "Du hast heute den HERRN sagen lassen, dass er dein Gott sein will* und dass du auf seinen Wegen gehen und seine Ordnungen und seine Gebote und seine Rechtsbestimmungen bewahren und seiner Stimme gehorchen willst*.", footnotes: ["℘ Kap. 29,12", "℘ 2Mo 19,8; Jos 24,22"] },
      { number: 18, text: "Und der HERR hat dich heute sagen lassen, dass du ihm zum Volk seines Eigentums sein willst, wie er zu dir geredet hat*, und dass du alle seine Gebote bewahren willst*,", footnotes: ["℘ Kap. 7,6; 14,2", "℘ Kap. 27,10"] },
      { number: 19, text: "und dass er dich als höchste über alle Nationen stellen will, die er gemacht hat, zum Ruhm und zum Namen und zum Schmuck*, und dass du dem HERRN, deinem Gott, ein heiliges Volk sein willst, wie er geredet hat*.", footnotes: ["℘ Kap. 28,1.9; Jer 13,11; Zef 3,19.20; Sach 8,13", "℘ 2Mo 19,5.6"] },
    ]},
    { number: 27, verses: [
      { number: 1, text: "Und Mose und die Ältesten von Israel befahlen dem Volk*: Bewahrt das ganze Gebot, das ich euch heute befehle!*", heading: "Gesetzessteine auf dem Ebal", footnotes: ["℘ Kap. 1,1", "℘ Kap. 6,17; 1Chr 28,8"] },
      { number: 2, text: "Und es soll geschehen, an dem Tag, an dem ihr über den Jordan in das Land hinüberzieht, das der HERR, dein Gott, dir gibt, sollst du dir große Steine aufrichten und sie mit Kalk bestreichen." },
      { number: 3, text: "Und du sollst alle Worte dieses Gesetzes auf sie schreiben, wenn du hinübergezogen bist, damit du in das Land kommst, das der HERR, dein Gott, dir gibt, ein Land, das von Milch und Honig überfließt*, wie der HERR, der Gott deiner Väter, zu dir geredet hat.", footnotes: ["℘ Kap. 6,3"] },
      { number: 4, text: "Und es soll geschehen, wenn ihr über den Jordan gezogen seid, sollt ihr diese Steine, über die ich euch heute Befehl gebe, auf dem Berg Ebal aufrichten*, und du sollst sie mit Kalk bestreichen.", footnotes: ["℘ Kap. 11,29"] },
      { number: 5, text: "Und dort sollst du dem HERRN, deinem Gott, einen Altar bauen, einen Altar aus Steinen. Du sollst kein Eisen über ihnen schwingen*;", footnotes: ["℘ 2Mo 20,25"] },
      { number: 6, text: "aus unbehauenen Steinen sollst du den Altar des HERRN, deines Gottes, bauen. Und du sollst dem HERRN, deinem Gott, Brandopfer darauf opfern," },
      { number: 7, text: "und du sollst Heilsopfer* opfern und dort essen und dich vor dem HERRN, deinem Gott, freuen*. —", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer", "℘ Kap. 12,7.12"] },
      { number: 8, text: "Und auf die Steine sollst du alle Worte dieses Gesetzes deutlich und sorgfältig schreiben*.", footnotes: ["℘ Jos 8,31.32"] },
      { number: 9, text: "Und Mose und die Priester, die Leviten, redeten zu ganz Israel und sagten: Sei still und höre, Israel! Am heutigen Tag bist du dem HERRN, deinem Gott, zum Volk geworden." },
      { number: 10, text: "So gehorche der Stimme des HERRN, deines Gottes, und tue seine Gebote und seine Ordnungen, die ich dir heute befehle.*", footnotes: ["℘ Kap. 26,17.18"] },
      { number: 11, text: "*Und Mose befahl dem Volk an jenem Tag und sagte:", heading: "Die zwölf Fluchworte", footnotes: ["℘ V. 12-14: 1Mo 35,23-26"] },
      { number: 12, text: "Wenn ihr über den Jordan gezogen seid, sollen diese auf dem Berg Garizim* stehen, um das Volk zu segnen: Simeon und Levi und Juda und Issaschar und Josef und Benjamin.", footnotes: ["℘ Ri 9,7"] },
      { number: 13, text: "Und diese sollen auf dem Berg Ebal stehen zum Verfluchen: Ruben, Gad und Asser und Sebulon, Dan und Naftali*.", footnotes: ["℘ Kap. 11,29"] },
      { number: 14, text: "Und die Leviten sollen anfangen und zu allen Männern von Israel mit erhobener Stimme sprechen*:", footnotes: ["℘ Kap. 33,10"] },
      { number: 15, text: "Verflucht sei der Mann, der ein Götterbild oder ein gegossenes Bild macht*, einen Gräuel für den HERRN*, ein Werk von Künstlerhänden*, und es im Verborgenen aufstellt*! Und das ganze Volk antworte und sage: Amen!", footnotes: ["℘ Kap. 4,23.25; 2Mo 20,4", "℘ Kap. 7,25", "℘ Jes 44,9-13", "℘ Ri 17,3.4; Hes 8,7-12"] },
      { number: 16, text: "Verflucht sei, wer seinen Vater oder seine Mutter verachtet*! Und das ganze Volk sage: Amen!", footnotes: ["℘ 2Mo 21,17; Hes 22,7"] },
      { number: 17, text: "Verflucht sei, wer die Grenze seines Nächsten verrückt*! Und das ganze Volk sage: Amen!", footnotes: ["℘ Kap. 19,14; Hi 24,2; Hos 5,10"] },
      { number: 18, text: "Verflucht sei, wer einen Blinden auf dem Weg irreführt*! Und das ganze Volk sage: Amen!", footnotes: ["℘ 1Mo 27,12; 3Mo 19,14"] },
      { number: 19, text: "Verflucht sei, wer das Recht des Fremden, der Waise und der Witwe beugt*! Und das ganze Volk sage: Amen!", footnotes: ["℘ Kap. 24,17; Mal 3,5"] },
      { number: 20, text: "Verflucht sei, wer bei der Frau seines Vaters liegt, denn er hat die Decke* seines Vaters aufgedeckt*! Und das ganze Volk sage: Amen!", footnotes: ["w. den Zipfel des Obergewandes", "℘ Kap. 23,1; 1Mo 35,22; 1Kor 5,1"] },
      { number: 21, text: "Verflucht sei, wer bei irgendeinem Tier liegt*! Und das ganze Volk sage: Amen!", footnotes: ["℘ 2Mo 22,18; 3Mo 20,15"] },
      { number: 22, text: "Verflucht sei, wer bei seiner Schwester liegt, der Tochter seines Vaters oder der Tochter seiner Mutter*! Und das ganze Volk sage: Amen!", footnotes: ["℘ 3Mo 18,9"] },
      { number: 23, text: "Verflucht sei, wer bei seiner Schwiegermutter liegt*! Und das ganze Volk sage: Amen!", footnotes: ["℘ 3Mo 18,17"] },
      { number: 24, text: "Verflucht sei, wer seinen Nächsten im Verborgenen erschlägt*! Und das ganze Volk sage: Amen!", footnotes: ["℘ Kap. 19,11.12; 1Kö 2,5"] },
      { number: 25, text: "Verflucht sei, wer ein Bestechungsgeschenk nimmt, um jemanden zu erschlagen, unschuldiges Blut zu vergießen*! Und das ganze Volk sage: Amen!", footnotes: ["℘ Kap. 16,19; Hes 22,12"] },
      { number: 26, text: "Verflucht sei, wer die Worte dieses Gesetzes nicht aufrechterhält, sie zu tun*! Und das ganze Volk sage: Amen!", footnotes: ["℘ Kap. 28,15; 2Kö 22,13; Esr 7,26; Ps 119,21; Jer 11,3; Gal 3,10"] },
    ]},
    { number: 28, verses: [
      { number: 1, text: "*Und es wird geschehen, wenn du der Stimme des HERRN, deines Gottes, genau gehorchst, dass du darauf achtest, all seine Gebote zu tun, die ich dir heute befehle*, dann wird der HERR, dein Gott, dich als höchste über alle Nationen der Erde stellen*.", heading: "Segen und Fluch", footnotes: ["℘ V. 1-14: 3Mo 26,3-13", "℘ 2Mo 15,26", "℘ Kap. 26,18.19"] },
      { number: 2, text: "Und alle diese Segnungen werden über dich kommen und werden dich erreichen, wenn du der Stimme des HERRN, deines Gottes, gehorchst.*", footnotes: ["℘ Kap. 11,27"] },
      { number: 3, text: "Gesegnet wirst du sein in der Stadt, und gesegnet wirst du sein auf dem Feld*.", footnotes: ["℘ Ps 112,1-3; 128,1.2"] },
      { number: 4, text: "Gesegnet wird sein die Frucht deines Leibes* und die Frucht deines Ackerlandes und die Frucht deines Viehs, der Wurf deiner Rinder und der Zuwachs deiner Schafe*.", footnotes: ["℘ Lk 1,42", "℘ Kap. 7,13.14; Ps 107,38"] },
      { number: 5, text: "Gesegnet wird sein dein Korb und dein Backtrog." },
      { number: 6, text: "Gesegnet wirst du sein bei deinem Eingang, und gesegnet wirst du sein bei deinem Ausgang*.", footnotes: ["℘ 4Mo 22,12; Ps 121,8"] },
      { number: 7, text: "Der HERR wird deine Feinde, die sich gegen dich erheben, geschlagen vor dir dahingeben. Auf einem Weg werden sie gegen dich ausziehen, und auf sieben Wegen werden sie vor dir fliehen*.", footnotes: ["℘ 1Sam 7,10; Ps 18,38-41"] },
      { number: 8, text: "Der HERR wird dir den Segen entbieten in deine Speicher* und zu allem Geschäft deiner Hand*, und er wird dich segnen in dem Land, das der HERR, dein Gott, dir gibt.", footnotes: ["℘ Spr 3,10", "℘ Kap. 14,29; Ps 1,3"] },
      { number: 9, text: "Der HERR wird dich zu einem heiligen Volk für sich erheben*, wie er dir geschworen hat, wenn du die Gebote des HERRN, deines Gottes, hältst und auf seinen Wegen gehst*.", footnotes: ["℘ Kap. 7,6; 29,12", "℘ 2Mo 15,26"] },
      { number: 10, text: "Und alle Völker der Erde werden sehen, dass der Name des HERRN über dir ausgerufen ist*, und sie werden sich vor dir fürchten*.", footnotes: ["℘ Jes 63,19", "℘ Kap. 2,25"] },
      { number: 11, text: "Und der HERR wird dir Überfluss geben an Gutem, an der Frucht deines Leibes und an der Frucht deines Viehes und an der Frucht deines Ackerlandes*, zur Wohlfahrt* in dem Land, das dir zu geben der HERR deinen Vätern geschworen hat*.", footnotes: ["℘ Kap. 7,13.14; Ps 107,38", "℘ Kap. 30,9; Ps 127,3", "℘ Kap. 1,8"] },
      { number: 12, text: "Der HERR wird dir seinen guten Schatz, den Himmel, auftun, um deinem Land Regen zu seiner Zeit zu geben* und um alles Tun deiner Hand zu segnen. Und du wirst vielen Nationen ausleihen*, du selbst aber wirst dir nichts leihen.", footnotes: ["℘ Kap. 11,14", "℘ Kap. 15,6"] },
      { number: 13, text: "Und der HERR wird dich zum Haupt machen und nicht zum Schwanz, und du wirst nur immer aufwärtssteigen und nicht hinuntersinken*, wenn du den Geboten des HERRN, deines Gottes, gehorchst, die zu bewahren und zu tun ich dir heute befehle*,", footnotes: ["℘ V. 43.44", "℘ 2Mo 15,26"] },
      { number: 14, text: "und von all den Worten, die ich euch heute befehle, weder zur Rechten noch zur Linken abweichst*, um anderen Göttern nachzulaufen, ihnen zu dienen*.", footnotes: ["℘ Kap. 5,32", "℘ Kap. 11,16"] },
      { number: 15, text: "*Es wird aber geschehen, wenn du der Stimme des HERRN, deines Gottes, nicht gehorchst, so dass du nicht darauf achtest, all seine Gebote und seine Ordnungen zu tun, die ich dir heute gebiete*, dann werden all diese Flüche über dich kommen und dich erreichen*.", footnotes: ["℘ V. 15-68: 3Mo 26,14-39", "℘ Kap. 5,1; 2Chr 7,19; Jer 26,4", "℘ V. 45; Kap. 11,28; 27,26; 29,19; Jos 23,16; Jer 11,8; Kla 2,17; Dan 9,11; Hos 7,12; Mal 2,2"] },
      { number: 16, text: "Verflucht wirst du sein in der Stadt, und verflucht wirst du sein auf dem Feld*.", footnotes: ["℘ Spr 3,33"] },
      { number: 17, text: "Verflucht wird sein dein Korb und dein Backtrog." },
      { number: 18, text: "Verflucht wird sein die Frucht deines Leibes* und die Frucht deines Ackerlandes, der Wurf deiner Rinder und der Zuwachs deiner Schafe.", footnotes: ["℘ Hos 9,12-14"] },
      { number: 19, text: "Verflucht wirst du sein bei deinem Eingang, und verflucht wirst du sein bei deinem Ausgang*. —", footnotes: ["℘ 2Chr 15,5"] },
      { number: 20, text: "Der HERR wird den Fluch, die Bestürzung und die Verwünschung gegen dich senden in allem Geschäft deiner Hand*, das du tust, bis du vernichtet bist und bis du schnell umkommst wegen der Bosheit deiner Taten, mit denen du mich verlassen hast*.", footnotes: ["℘ Ri 2,15", "℘ Kap. 4,26; Hi 24,18; Jer 1,16"] },
      { number: 21, text: "Der HERR wird die Pest an dir haften lassen, bis er dich ausgerottet hat aus dem Land, wohin du kommst, um es in Besitz zu nehmen*.", footnotes: ["℘ Jer 24,10; Am 4,10"] },
      { number: 22, text: "Der HERR wird dich schlagen mit Schwindsucht und mit Fieberglut und mit Hitze und mit Entzündung* und mit Dürre* und mit Getreidebrand und mit Vergilben des Korns, und sie werden dich verfolgen, bis du umgekommen bist*.", footnotes: ["℘ 1Kö 8,37", "℘ 1Kö 17,7; Hag 2,17", "℘ Jer 16,4"] },
      { number: 23, text: "Und dein Himmel, der über deinem Haupt ist, wird Erz sein, und die Erde, die unter dir ist, Eisen." },
      { number: 24, text: "Der HERR wird den Regen deines Landes zu Staub und Sand machen. Vom Himmel wird es auf dich herabkommen, bis du umgekommen bist." },
      { number: 25, text: "Der HERR wird dich geschlagen vor deinen Feinden dahingeben*. Auf einem Weg wirst du gegen sie ausziehen, und auf sieben Wegen wirst du vor ihnen fliehen, und du wirst zum Schreckbild* für alle Königreiche der Erde werden*.", footnotes: ["℘ 2Chr 6,24; Jes 30,17", "nach anderen: zum Gegenstand der Misshandlung", "℘ Jer 34,17"] },
      { number: 26, text: "Und deine Leiche wird allen Vögeln des Himmels und den Tieren der Erde zum Fraß werden*, und niemand wird sie wegscheuchen*.", footnotes: ["℘ 1Sam 17,46", "℘ Ps 79,2"] },
      { number: 27, text: "Der HERR wird dich schlagen mit den Geschwüren Ägyptens* und mit Beulen* und mit Krätze und mit Grind, dass du nicht mehr geheilt werden kannst.", footnotes: ["℘ V. 60; 2Mo 9,9-11", "℘ 1Sam 5,6.9"] },
      { number: 28, text: "Der HERR wird dich schlagen mit Wahnsinn und mit Blindheit und mit Geistesverwirrung*.", footnotes: ["w. mit Verwirrung des Herzens"] },
      { number: 29, text: "Und du wirst am Mittag umhertappen, wie der Blinde im Finstern tappt*, und du wirst keinen Erfolg haben auf deinen Wegen. Und du wirst alle Tage nur unterdrückt und beraubt sein, und niemand wird helfen.", footnotes: ["℘ Hi 5,14; Jes 59,10; Zef 1,17"] },
      { number: 30, text: "Eine Frau wirst du dir verloben, aber ein anderer Mann wird mit ihr schlafen*. Ein Haus wirst du bauen, aber nicht darin wohnen. Einen Weinberg wirst du pflanzen, aber du wirst ihn nicht nutzen*.", footnotes: ["℘ Hi 31,10; Kla 5,11", "w. entweihen; d. h. dadurch, dass man ihn im 5. Jahr in Gebrauch nimmt; vgl. 3Mo 19,23—25\n℘ Kap. 20,6.7; Jes 62,8; Jer 6,12; Am 5,11; Zef 1,13"] },
      { number: 31, text: "Dein Rind wird vor deinen Augen geschlachtet, und du wirst nicht davon essen. Dein Esel wird vor deinem Gesicht geraubt und nicht zu dir zurückkehren. Deine Schafe werden deinen Feinden gegeben, und du wirst niemanden haben, der hilft*.", footnotes: ["℘ Ri 6,4"] },
      { number: 32, text: "Deine Söhne und deine Töchter werden einem anderen Volk gegeben*, und deine Augen werden es sehen und werden nach ihnen schmachten den ganzen Tag; aber du wirst machtlos sein*.", footnotes: ["℘ Hi 31,8", "w. nichts gibt es für die Kraft deiner Hand"] },
      { number: 33, text: "Die Frucht deines Ackers und all dein Erworbenes wird ein Volk verzehren, das du nicht kennst*; und du wirst nur unterdrückt und zerschlagen sein alle Tage*.", footnotes: ["℘ V. 51; Ri 6,3-5; Neh 9,37; Hi 20,18; Jes 1,7; Hos 8,7", "℘ Jes 42,22"] },
      { number: 34, text: "Und du wirst wahnsinnig werden vor dem Anblick dessen, was deine Augen erblicken müssen." },
      { number: 35, text: "Der HERR wird dich schlagen mit bösen Geschwüren an den Knien und an den Schenkeln, von deiner Fußsohle bis zu deinem Scheitel, dass du nicht mehr geheilt werden kannst*.", footnotes: ["℘ Hi 2,7; Offb 16,2"] },
      { number: 36, text: "Der HERR wird dich und deinen König, den du über dich setzen wirst, zu einer Nation wegführen, die du nicht gekannt hast, du und deine Väter. Und du wirst dort anderen Göttern, Göttern aus Holz und Stein, dienen*.", footnotes: ["℘ V. 64; Kap. 4,27.28; 1Sam 12,25; 2Kö 25,21; 2Chr 33,11; Jer 9,15; Kla 2,9; Hes 11,9"] },
      { number: 37, text: "Und du wirst zum Entsetzen werden, zum Sprichwort und zur Spottrede unter allen Völkern, wohin der HERR dich wegtreiben wird*.", footnotes: ["℘ 1Kö 9,7; Jer 24,9; Kla 3,45; Hes 5,15"] },
      { number: 38, text: "Viel Samen wirst du aufs Feld hinausbringen, aber wenig einsammeln*, denn die Heuschrecke wird es abfressen*.", footnotes: ["℘ Hag 1,6", "℘ Joe 1,4"] },
      { number: 39, text: "Weinberge wirst du pflanzen und bearbeiten; aber Wein wirst du weder trinken noch einsammeln, denn der Wurm wird ihn abfressen*.", footnotes: ["℘ Hab 3,17"] },
      { number: 40, text: "Ölbäume wirst du in deinem ganzen Gebiet haben; aber mit Öl wirst du dich nicht salben*, denn deine Oliven fallen ab.", footnotes: ["℘ Mi 6,15"] },
      { number: 41, text: "Söhne und Töchter wirst du zeugen; aber sie werden dir nicht gehören, denn sie werden in die Gefangenschaft gehen*.", footnotes: ["℘ Jes 65,23; Kla 1,5; Dan 1,3; Mi 1,16"] },
      { number: 42, text: "Alle deine Bäume und die Frucht deines Ackerlandes wird die Grille* in Besitz nehmen*.", footnotes: ["o. die Heuschrecke; w. der Schwirrende", "℘ 1Kö 8,37; Am 4,9"] },
      { number: 43, text: "Der Fremde, der in deiner Mitte wohnt, wird höher und höher über dich emporsteigen, und du, du wirst tiefer und tiefer hinabsinken." },
      { number: 44, text: "Er wird dir leihen, du aber wirst ihm nicht leihen können; er wird zum Haupt, du aber wirst zum Schwanz*.", footnotes: ["℘ V. 12.13; Kla 1,5"] },
      { number: 45, text: "Und alle diese Flüche werden über dich kommen und dich verfolgen und dich erreichen*, bis du vernichtet bist, weil du der Stimme des HERRN, deines Gottes, nicht gehorcht hast, seine Gebote und seine Ordnungen zu bewahren, die er dir befohlen hat.", footnotes: ["℘ V. 15"] },
      { number: 46, text: "Und sie werden zum Zeichen und zum Wunder* sein an dir und an deinen Nachkommen für ewig.", footnotes: ["o. Wahrzeichen"] },
      { number: 47, text: "Dafür, dass du dem HERRN, deinem Gott, nicht mit Freude und mit fröhlichem Herzen gedient hast wegen des Überflusses an allem*,", footnotes: ["℘ Kap. 32,13-15; Ps 100,2"] },
      { number: 48, text: "wirst du deinen Feinden, die der HERR gegen dich senden wird, dienen in Hunger und Durst, in Blöße und in Mangel an allem*. Und er wird ein eisernes Joch auf deinen Hals legen*, bis er dich vernichtet hat.", footnotes: ["℘ 2Chr 12,8; Neh 9,35-37", "℘ Jer 28,13.14; Kla 1,14"] },
      { number: 49, text: "Der HERR wird von ferne, vom Ende der Erde her, eine Nation über dich bringen. Wie der Adler fliegt*, so kommt sie, eine Nation, deren Sprache du nicht verstehst,", footnotes: ["℘ Jes 5,26; Jer 4,13; Hes 17,3.12; Dan 7,4; Hos 8,1; Hab 1,6.8"] },
      { number: 50, text: "eine Nation mit hartem Gesicht, die für den Alten keine Rücksicht kennt* und für den Jungen keine Gnade*,", footnotes: ["w. die das Gesicht des Alten nicht erhebt", "℘ 2Chr 36,17; Jes 47,6; Jer 21,7"] },
      { number: 51, text: "und die die Frucht deines Viehs und die Frucht deines Landes verzehren wird, bis du vernichtet bist, die dir weder Getreide, Most oder Öl noch den Wurf deiner Rinder oder den Zuwachs deiner Schafe übrig lassen wird, bis sie dich zugrunde gerichtet hat*.", footnotes: ["℘ 2Kö 25,10; Kla 4,9"] },
      { number: 52, text: "Und sie wird dich belagern in all deinen Toren, bis deine hohen und festen Mauern, auf die du vertraust, in deinem ganzen Land gefallen sind*. Und sie wird dich belagern in all deinen Toren, in deinem ganzen Land, das der HERR, dein Gott, dir gegeben hat*.", footnotes: ["℘ Kla 2,2.5", "℘ 2Kö 25,1.2; Lk 19,43"] },
      { number: 53, text: "Dann wirst du die Frucht deines Leibes essen, das Fleisch deiner Söhne und deiner Töchter, die der HERR, dein Gott, dir gegeben hat* in der Belagerung und Bedrängnis, mit der dich dein Feind bedrängen wird.", footnotes: ["℘ 2Kö 6,28.29"] },
      { number: 54, text: "Der weichlichste und am meisten verzärtelte Mann bei dir, dessen Auge wird missgünstig auf seinen Bruder blicken und auf die Frau an seinem Busen* und auf seine übrig gebliebenen Kinder, die er übrig behalten hat.", footnotes: ["w. die Frau seines Schoßes"] },
      { number: 55, text: "Keinem von ihnen gibt er etwas vom Fleisch seiner Kinder, das er isst, weil ihm nichts übrig geblieben ist in der Belagerung und Bedrängnis, mit der dein Feind dich bedrängen wird in all deinen Toren." },
      { number: 56, text: "Die Weichlichste bei dir und die Verzärteltste, die vor Verzärtelung und vor Verweichlichung nie versucht hat, ihre Fußsohle auf die Erde zu setzen*, deren Auge wird missgünstig auf den Mann an ihrem Busen* blicken und auf ihren Sohn und auf ihre Tochter", footnotes: ["℘ Jes 47,1; Kla 4,5", "w. ihres Schoßes"] },
      { number: 57, text: "wegen ihrer Nachgeburt, die zwischen ihren Beinen hervorkommt, und wegen ihrer Kinder, die sie gebiert. Denn sie wird sie aus Mangel an allem im Geheimen aufessen in der Belagerung und Bedrängnis, mit der dein Feind dich bedrängen wird in deinen Toren. —" },
      { number: 58, text: "Wenn du nicht darauf achtest, alle Worte dieses Gesetzes zu tun, die in diesem Buch geschrieben sind, dass du diesen herrlichen und furchtbaren Namen, den HERRN, deinen Gott, fürchtest*,", footnotes: ["℘ Ps 111,9; Jer 5,22"] },
      { number: 59, text: "dann wird der HERR deine Plagen und die Plagen deiner Nachkommen außergewöhnlich machen: große und andauernde Plagen und böse und andauernde Krankheiten." },
      { number: 60, text: "Und er wird alle Seuchen Ägyptens gegen dich wenden, vor denen du dich fürchtest, und sie werden an dir haften bleiben*.", footnotes: ["℘ V. 27; Kap. 7,15; 2Mo 9,14"] },
      { number: 61, text: "Auch alle Krankheiten und alle Plagen, die nicht in dem Buch dieses Gesetzes geschrieben sind, — der HERR wird sie über dich kommen lassen, bis du vernichtet bist*.", footnotes: ["℘ Kap. 29,21"] },
      { number: 62, text: "Als ein geringes Häuflein* werdet ihr übrig bleiben*, statt dass ihr wie die Sterne des Himmels an Menge geworden wärt*, weil du der Stimme des HERRN, deines Gottes, nicht gehorcht hast. —", footnotes: ["w. Als gezählte Männer", "℘ Kap. 4,27; Jes 6,11-13; Jer 42,2; Am 5,3", "℘ Kap. 1,10"] },
      { number: 63, text: "Und es wird geschehen: Wie der HERR sich über euch freute, euch Gutes zu tun und euch zahlreich werden zu lassen*, so wird der HERR sich über euch freuen, euch zugrunde zu richten und euch zu vernichten*. Und ihr werdet aus dem Land herausgerissen werden, wohin du kommst, um es in Besitz zu nehmen*.", footnotes: ["℘ Kap. 30,9", "℘ Spr 1,26; Jes 1,24.25; Hes 5,13", "℘ Kap. 4,27; Jes 6,11-13; Jer 42,2; Am 5,3"] },
      { number: 64, text: "Und der HERR wird dich unter alle Völker zerstreuen von einem Ende der Erde bis zum andern Ende der Erde*. Und du wirst dort andern Göttern dienen, die du nicht gekannt hast, weder du noch deine Väter — Göttern aus Holz und Stein*.", footnotes: ["℘ Am 9,9; Sach 2,10; Lk 21,24", "℘ V. 36; Kap. 13,8"] },
      { number: 65, text: "Und unter jenen Nationen wirst du nicht ruhig wohnen, und deine Fußsohle wird keinen Rastplatz finden*. Und der HERR wird dir dort ein zitterndes Herz geben, erlöschende Augen* und eine verzagende Seele.", footnotes: ["℘ Kla 1,3; 5,17", "℘ Kap. 4,27; Jes 6,11-13; Jer 42,2; Am 5,3"] },
      { number: 66, text: "Und dein Leben wird in Gefahr schweben*, du wirst dich Nacht und Tag fürchten und deines Lebens nicht sicher sein.", footnotes: ["w. deine Leben sind dir gegenüber aufgehängt"] },
      { number: 67, text: "Am Morgen wirst du sagen: Wäre es doch Abend!, und am Abend wirst du sagen: Wäre es doch Morgen*! — wegen des Zitterns deines Herzens, mit dem du zitterst, und wegen des Anblicks dessen, was deine Augen erblicken müssen.", footnotes: ["℘ Hi 7,4"] },
      { number: 68, text: "Und der HERR wird dich auf Schiffen nach Ägypten zurückkehren lassen*, auf dem Weg, von dem ich dir gesagt habe: Du sollst ihn nie mehr wiedersehen*! Und ihr werdet euch dort euren Feinden als Sklaven und als Sklavinnen zum Kauf anbieten, aber es wird kein Käufer da sein.", footnotes: ["℘ Hos 8,13", "℘ 2Mo 13,17"] },
      { number: 69, text: "Das sind die Worte des Bundes, von dem der HERR dem Mose befohlen hatte, er solle ihn mit den Söhnen Israel im Land Moab schließen neben dem Bund, den er am Horeb mit ihnen geschlossen hatte*.", footnotes: ["℘ Kap. 5,1-3; 29,11; Röm 9,4"] },
    ]},
    { number: 29, verses: [
      { number: 1, text: "Und Mose berief ganz Israel und sprach zu ihnen*: Ihr habt alles gesehen, was der HERR vor euren Augen im Land Ägypten getan hat an dem Pharao und an all seinen Knechten und an seinem ganzen Land*:", heading: "Gottes Bund mit Israel im Land Moab — Mahnung zur Bundestreue", footnotes: ["℘ Kap. 1,1", "℘ 2Mo 19,4; Ps 105,27-36"] },
      { number: 2, text: "die großen Prüfungen, die deine Augen gesehen haben, jene großen Zeichen und Wunder*.", footnotes: ["o. Wahrzeichen\n℘ Kap. 1,30; 11,7; Jos 24,17; 1Sam 12,24"] },
      { number: 3, text: "Aber der HERR hat euch bis zum heutigen Tag weder ein Herz gegeben zu erkennen, noch Augen zu sehen, noch Ohren zu hören*.", footnotes: ["℘ 2Chr 20,33; Jes 6,10; Jer 5,21; Hes 12,2; Mt 13,13-15; Joh 12,40; Röm 11,8"] },
      { number: 4, text: "Und ich habe euch vierzig Jahre in der Wüste geführt*: Eure Kleider sind nicht an euch zerschlissen, und dein Schuh an deinem Fuß ist nicht zerschlissen*.", footnotes: ["℘ 2Mo 16,35", "℘ Kap. 2,7"] },
      { number: 5, text: "Brot habt ihr nicht gegessen*, und Wein und Rauschtrank habt ihr nicht getrunken, damit ihr erkenntet, dass ich der HERR, euer Gott, bin*.", footnotes: ["℘ Kap. 8,3; Ps 78,24.25", "℘ 2Mo 6,7"] },
      { number: 6, text: "Und als ihr an diesen Ort kamt, da zogen Sihon, der König von Heschbon, und Og, der König von Baschan, uns zum Kampf entgegen, und wir schlugen sie.*", footnotes: ["℘ Kap. 2,33; 3,6"] },
      { number: 7, text: "Und wir nahmen ihr Land ein und gaben es den Rubenitern und den Gaditern und dem halben Stamm der Manassiter zum Erbteil.*", footnotes: ["℘ Kap. 3,12.13"] },
      { number: 8, text: "So bewahrt denn die Worte dieses Bundes und tut sie, damit ihr Erfolg habt in allem, was ihr tut!*", footnotes: ["℘ Kap. 5,32.33; Jos 1,7.8; 1Kö 2,3"] },
      { number: 9, text: "Ihr alle steht heute vor dem HERRN, eurem Gott: eure Häupter, eure Stämme, eure Ältesten und eure Aufseher*, alle Männer von Israel,", footnotes: ["w. Schreiber; d. i. eine Beamtenbezeichnung\n℘ Jos 24,1"] },
      { number: 10, text: "eure Kinder, eure Frauen und dein Fremder, der mitten in deinem Lager ist, von deinem Holzhauer bis zu deinem Wasserschöpfer*,", footnotes: ["℘ Jos 8,35; 9,21; 1Sam 3,21; 2Chr 20,13"] },
      { number: 11, text: "damit du in den Bund des HERRN, deines Gottes, eintrittst und in seine Fluchbestimmung, den der HERR, dein Gott, heute mit dir schließt*,", footnotes: ["℘ Kap. 28,69; Jos 24,25; 2Chr 15,12; Neh 10,30"] },
      { number: 12, text: "damit er dich heute zu seinem Volk erhebt* und er dein Gott ist*, wie er zu dir geredet* und wie er deinen Vätern, Abraham, Isaak und Jakob, geschworen hat*.", footnotes: ["℘ Kap. 28,9", "℘ Kap. 26,17", "℘ 2Mo 6,7", "℘ Kap. 1,8"] },
      { number: 13, text: "Doch nicht mit euch allein schließe ich diesen Bund mit dieser Fluchbestimmung," },
      { number: 14, text: "sondern sowohl mit dem, der heute hier ist, der mit uns vor dem HERRN, unserm Gott, steht, als auch mit dem, der heute nicht mit uns hier ist*.", footnotes: ["℘ Kap. 5,3; Apg 2,39"] },
      { number: 15, text: "Denn ihr wisst ja*, wie wir im Land Ägypten gewohnt haben und wie wir mitten durch die Nationen gezogen sind, durch die ihr gezogen seid.", footnotes: ["o. habt ja erkannt"] },
      { number: 16, text: "Da habt ihr ihre Scheusale gesehen und ihre Götzen* aus Holz und Stein, Silber und Gold, die bei ihnen sind.", footnotes: ["w. Mistkugeln, o. Klötze; ein verächtlicher Ausdruck"] },
      { number: 17, text: "Dass es bei euch nur ja nicht einen Mann oder eine Frau, eine Sippe oder einen Stamm gibt, dessen Herz sich heute von dem HERRN, unserm Gott, abwendet, um hinzugehen, den Göttern jener Nationen zu dienen*! Dass es ja nicht eine Wurzel unter euch gibt, die Gift und Wermut als Frucht bringt*,", footnotes: ["℘ Kap. 11,16; 3Mo 18,3; Hebr 3,12", "℘ Apg 8,23; Hebr 12,15"] },
      { number: 18, text: "— und es geschieht, wenn er die Worte dieses Fluches hört, dass er sich in seinem Herzen segnet und sagt: Ich werde Frieden haben, auch wenn ich in der Verstocktheit meines Herzens lebe*! —, so dass das bewässerte mit dem durstigen Land hinweggerafft wird.", footnotes: ["w. gehe\n℘ Ps 10,13; Jer 23,17"] },
      { number: 19, text: "Nicht wird der HERR ihm vergeben wollen*, sondern dann wird der Zorn des HERRN und sein Eifer gegen jenen Mann rauchen, und der ganze Fluch, der in diesem Buch aufgeschrieben ist, wird auf ihm liegen*, und der HERR wird seinen Namen unter dem Himmel auslöschen*.", footnotes: ["℘ 2Kö 24,4", "℘ Kap. 28,15", "℘ Hes 14,7.8"] },
      { number: 20, text: "Und der HERR wird ihn aus allen Stämmen Israels zum Unheil aussondern*, nach all den Flüchen des Bundes, der in diesem Buch des Gesetzes geschrieben ist.", footnotes: ["℘ Spr 2,22"] },
      { number: 21, text: "Und die künftige Generation, eure Kinder, die nach euch aufstehen werden, und der Ausländer, der aus fernem Land kommt, werden sagen, wenn sie die Plagen dieses Landes sehen und seine Krankheiten, mit denen der HERR es geschlagen hat* —", footnotes: ["℘ Kap. 28,59-61"] },
      { number: 22, text: "Schwefel und Salz, eine Brandstätte ist sein ganzes Land; es wird nicht besät und lässt nichts sprossen, und keinerlei Kraut kommt darin auf wie nach der Umkehrung von Sodom und Gomorra, von Adma und Zebojim, die der HERR umkehrte in seinem Zorn und in seinem Grimm* —,", footnotes: ["℘ 1Mo 19,24.25; Jer 20,16; 49,18; Hos 11,8; Zef 2,9"] },
      { number: 23, text: "*und alle Nationen werden sagen: Warum hat der HERR diesem Land so etwas getan? Weshalb diese große Zornglut?", footnotes: ["℘ V. 23-27: Jer 9,11-15"] },
      { number: 24, text: "Dann wird man sagen: Weil sie den Bund des HERRN, des Gottes ihrer Väter, verlassen haben, den er mit ihnen geschlossen hatte, als er sie aus dem Land Ägypten herausführte*,", footnotes: ["℘ 3Mo 26,32; 2Kö 17,15; 18,12; Jer 31,32; Hes 16,59"] },
      { number: 25, text: "und weil sie hingingen und andern Göttern dienten und sich vor ihnen niederwarfen, vor Göttern, die sie nicht kannten und die er ihnen nicht zugeteilt hatte*,", footnotes: ["℘ 1Kö 9,8.9; Ps 106,36; Jer 22,8.9; 44,3"] },
      { number: 26, text: "da entbrannte der Zorn des HERRN gegen dieses Land, so dass er den ganzen Fluch über es gebracht hat, der in diesem Buch aufgeschrieben ist." },
      { number: 27, text: "Und der HERR hat sie herausgerissen aus ihrem Land im Zorn und im Grimm und in großem Unwillen und hat sie in ein anderes Land geworfen*, wie es an diesem Tag der Fall ist. —", footnotes: ["℘ Kap. 30,1; 1Kö 14,15; 2Kö 17,6; 25,21; Ps 85,5.6; Jer 5,19"] },
      { number: 28, text: "Das Verborgene steht bei dem HERRN, unserm Gott*; aber das Offenbare gilt uns und unsern Kindern für ewig*, damit wir alle Worte dieses Gesetzes tun*.", footnotes: ["℘ Kap. 32,34; Spr 25,2", "℘ Dan 2,22", "℘ Ps 78,2-7"] },
    ]},
    { number: 30, verses: [
      { number: 1, text: "Und es wird geschehen, wenn all diese Worte über dich kommen, der Segen und der Fluch, die ich dir vorgelegt habe*, und du es dir zu Herzen nimmst unter all den Nationen, wohin der HERR, dein Gott, dich verstoßen hat*,", heading: "Trost und Mahnung — Wahl zwischen Leben und Tod", footnotes: ["℘ Kap. 28", "℘ Kap. 29,27; Hes 6,9"] },
      { number: 2, text: "und du umkehrst zum HERRN, deinem Gott, und seiner Stimme gehorchst nach allem, was ich dir heute befehle, du und deine Kinder, mit deinem ganzen Herzen und mit deiner ganzen Seele*,", footnotes: ["℘ 3Mo 26,40"] },
      { number: 3, text: "dann wird der HERR, dein Gott, dein Geschick wenden* und sich über dich erbarmen*. Und er wird dich wieder sammeln aus all den Völkern, wohin der HERR, dein Gott, dich zerstreut hat.*", footnotes: ["℘ Ps 126,1; Joe 4,1", "℘ Mi 7,19", "℘ 1Chr 16,35; Ps 147,2; Jes 43,5; Jer 23,3; Hes 11,17; 39,28; Sach 8,7.8; 10,9"] },
      { number: 4, text: "Wenn deine Verstoßenen am Ende des Himmels wären, selbst von dort wird der HERR, dein Gott, dich sammeln, und von dort wird er dich holen.*", footnotes: ["℘ 1Kö 8,34; 2Chr 30,9; Neh 1,9; Jes 27,12; Hes 36,24; Mt 24,31"] },
      { number: 5, text: "Und der HERR, dein Gott, wird dich in das Land bringen, das deine Väter in Besitz genommen haben, und du wirst es in Besitz nehmen. Und er wird dir Gutes tun und dich zahlreicher werden lassen als deine Väter*.", footnotes: ["℘ Jer 33,9; Hes 36,11.37"] },
      { number: 6, text: "Und der HERR, dein Gott, wird dein Herz und das Herz deiner Nachkommen beschneiden*, damit du den HERRN, deinen Gott, liebst mit deinem ganzen Herzen und mit deiner ganzen Seele*, dass du am Leben bleibst*.", footnotes: ["℘ Kap. 10,16; Jer 24,7; Hes 11,19.20; Röm 2,29", "℘ Kap. 6,5", "℘ 3Mo 18,5"] },
      { number: 7, text: "Und der HERR, dein Gott, wird all diese Flüche auf deine Feinde und auf deine Hasser legen, die dir nachgejagt sind*.", footnotes: ["℘ 4Mo 24,9; Jer 30,16"] },
      { number: 8, text: "Du aber, du wirst umkehren und der Stimme des HERRN gehorchen und wirst all seine Gebote tun, die ich dir heute befehle*.", footnotes: ["℘ Hes 36,27"] },
      { number: 9, text: "Und der HERR, dein Gott, wird dir Überfluss geben bei allem Tun deiner Hand, an der Frucht deines Leibes und an der Frucht deines Viehs und an der Frucht deines Ackerlandes, für dich zum Guten*. Denn der HERR wird sich wieder über dich freuen zum Guten, wie er sich über deine Väter gefreut hat*,", footnotes: ["℘ Kap. 7,14; 28,11; Jer 32,41", "℘ Kap. 28,63; Jes 62,4.5; Zef 3,17"] },
      { number: 10, text: "wenn* du der Stimme des HERRN, deines Gottes, gehorchst*, um seine Gebote und seine Ordnungen zu halten, die in diesem Buch des Gesetzes aufgeschrieben sind, wenn* du zum HERRN, deinem Gott, umkehrst mit deinem ganzen Herzen und mit deiner ganzen Seele*.", footnotes: ["o. weil", "℘ Sach 6,15", "o. weil", "℘ Kap. 6,5"] },
      { number: 11, text: "Denn dieses Gebot, das ich dir heute gebiete, ist nicht zu wunderbar* für dich und ist dir nicht zu fern*.", footnotes: ["w. unbegreiflich, o. rätselhaft, o. schwierig", "℘ Jes 45,19; 1Jo 5,3"] },
      { number: 12, text: "Es ist nicht im Himmel, dass du sagen müsstest: Wer wird für uns in den Himmel hinaufsteigen und es uns holen und es uns hören lassen, dass wir es tun?" },
      { number: 13, text: "Und es ist nicht jenseits des Meeres, dass du sagen müsstest: Wer wird für uns auf die andere Seite des Meeres hinüberfahren und es uns holen und es uns hören lassen, dass wir es tun?" },
      { number: 14, text: "Sondern ganz nahe ist dir das Wort, in deinem Mund und in deinem Herzen*, um es zu tun.", footnotes: ["℘ Röm 10,6-8"] },
      { number: 15, text: "Siehe, ich habe dir heute vorgelegt das Leben und das Gute, den Tod und das Böse*,", footnotes: ["℘ Kap. 11,26; Jer 21,8; 42,21"] },
      { number: 16, text: "*indem ich dir heute gebiete, den HERRN, deinen Gott, zu lieben*, auf seinen Wegen zu gehen und seine Gebote, seine Ordnungen und seine Rechtsbestimmungen zu bewahren, damit du lebst und zahlreich wirst* und der HERR, dein Gott, dich segnet in dem Land, wohin du kommst, um es in Besitz zu nehmen*.", footnotes: ["Eine griech. Handschr. überliefert: wenn du auf die Gebote des HERRN, deines Gottes, hörst, die ich dir heute gebiete . . ., dann wirst du leben und zahlreich werden", "℘ Jos 23,11", "Eine griech. Handschr. überliefert: wenn du auf die Gebote des HERRN, deines Gottes, hörst, die ich dir heute gebiete . . ., dann wirst du leben und zahlreich werden", "℘ Kap. 5,33"] },
      { number: 17, text: "Wenn aber dein Herz sich abwendet und du nicht gehorchst und du dich verführen lässt und dich vor andern Göttern niederwirfst und ihnen dienst*,", footnotes: ["℘ Kap. 11,16; 1Sam 12,21"] },
      { number: 18, text: "dann kündige ich euch heute an, dass ihr ganz gewiss umkommen werdet. Ihr werdet eure Tage nicht verlängern in dem Land, in das du über den Jordan ziehst, um hineinzukommen, es in Besitz zu nehmen*.", footnotes: ["℘ Kap. 4,25.26; 31,17.21"] },
      { number: 19, text: "Ich rufe heute den Himmel und die Erde als Zeugen gegen euch auf*: Das Leben und den Tod habe ich dir vorgelegt, den Segen und den Fluch*! So wähle das Leben, damit du lebst*, du und deine Nachkommen,", footnotes: ["℘ Kap. 11,26; Jer 21,8; 42,21", "℘ Kap. 11,26; Jer 21,8; 42,21", "℘ Spr 9,11; 12,28; Hes 20,11"] },
      { number: 20, text: "indem du den HERRN, deinen Gott, liebst* und seiner Stimme gehorchst und ihm anhängst! Denn das ist dein Leben* und die Dauer deiner Tage*, dass du in dem Land wohnst, das der HERR deinen Vätern, Abraham, Isaak und Jakob, geschworen hat, ihnen zu geben*.", footnotes: ["℘ Kap. 4,4; 6,2; 32,47", "℘ 3Mo 18,5; Lk 10,28", "℘ 3Mo 18,5; Lk 10,28", "℘ Kap. 1,8"] },
    ]},
    { number: 31, verses: [
      { number: 1, text: "Und Mose ging hin und redete diese Worte zu ganz Israel*.", heading: "Josuas Einsetzung zum Nachfolger Moses", footnotes: ["℘ V. 30; Kap. 1,1"] },
      { number: 2, text: "Und er sprach zu ihnen: 120 Jahre* bin ich heute alt, ich kann nicht mehr aus- und eingehen; und der HERR hat zu mir gesagt: Du sollst nicht über diesen Jordan gehen*.", footnotes: ["℘ Kap. 34,7; 2Mo 7,7", "℘ Kap. 1,37"] },
      { number: 3, text: "Der HERR, dein Gott, er zieht vor dir her hinüber; er selbst wird diese Nationen vor dir vernichten, dass du sie vertreiben kannst*. Josua, er zieht vor dir her hinüber, wie der HERR geredet hat*.", footnotes: ["℘ Kap. 7,1", "℘ 4Mo 27,21"] },
      { number: 4, text: "Und der HERR wird an ihnen handeln, wie er an Sihon und an Og, den Königen der Amoriter, und an ihrem Land gehandelt hat, die er vernichtet hat*.", footnotes: ["℘ 4Mo 21,24.35; Jos 24,12"] },
      { number: 5, text: "Und wenn der HERR sie vor euch dahingibt, dann sollt ihr an ihnen handeln nach dem ganzen Gebot, das ich euch geboten habe*.", footnotes: ["℘ Kap. 7,2.16; Jos 11,15"] },
      { number: 6, text: "Seid stark und mutig*, fürchtet euch nicht und erschreckt nicht vor ihnen! Denn der HERR, dein Gott, er ist es, der mit dir geht*; er wird dich nicht aufgeben und dich nicht verlassen*.", footnotes: ["℘ 4Mo 13,20; Jos 1,6; 2Sam 10,12; 1Kö 2,2; 1Kor 16,13", "℘ Kap. 1,29.30; Jer 1,8", "℘ V. 23; 1Mo 28,15; 4Mo 13,9; Jos 1,5.9; 1Sam 12,22; 1Kö 6,13; 8,57; 1Chr 22,13; 28,20; Ps 94,14"] },
      { number: 7, text: "Und Mose rief Josua und sprach zu ihm vor den Augen von ganz Israel*: Sei stark und mutig*! Denn du, du wirst mit diesem Volk in das Land kommen, das der HERR ihren Vätern geschworen hat, ihnen zu geben*; und du, du wirst es ihnen als Erbe austeilen*.", footnotes: ["℘ 4Mo 27,19", "℘ 4Mo 13,20; Jos 1,6; 2Sam 10,12; 1Kö 2,2; 1Kor 16,13", "℘ V. 21; Kap. 1,8; Hebr 4,8", "℘ Kap. 1,38"] },
      { number: 8, text: "Der HERR, er ist es, der vor dir herzieht*; er selbst wird mit dir sein; er wird dich nicht aufgeben und dich nicht verlassen. Fürchte dich nicht und sei nicht niedergeschlagen*!", footnotes: ["℘ 2Mo 32,1", "℘ V. 23; 1Mo 28,15; 4Mo 13,9; Jos 1,5.9; 1Sam 12,22; 1Kö 6,13; 8,57; 1Chr 22,13; 28,20; Ps 94,14"] },
      { number: 9, text: "Und Mose schrieb dieses Gesetz auf* und gab es den Priestern, den Söhnen Levi*, die die Lade des Bundes des HERRN trugen*, und allen Ältesten von Israel.", heading: "Gesetzeslesung alle sieben Jahre", footnotes: ["℘ V. 24; 2Mo 24,4", "℘ Kap. 17,18", "℘ V. 25.26; Kap. 10,8; Jos 3,3.17; 1Kö 8,3"] },
      { number: 10, text: "Und Mose befahl ihnen und sagte: Am Ende von sieben Jahren, zur Zeit* des Erlassjahres*, am Fest der Laubhütten*,", footnotes: ["w. zur festgesetzten Zeit", "℘ Kap. 15,1.9", "℘ 3Mo 23,34"] },
      { number: 11, text: "wenn ganz Israel kommt, um vor dem HERRN, deinem Gott, an der Stätte zu erscheinen, die er erwählen wird*, sollst du dieses Gesetz vor ganz Israel ausrufen lassen, vor ihren Ohren*.", footnotes: ["℘ Kap. 12,5", "℘ Jos 8,34; 2Kö 23,2; Neh 8,1-3"] },
      { number: 12, text: "Versammle das Volk, die Männer und die Frauen und die Kinder und deinen Fremden, der in deinen Toren wohnt*, damit sie hören und damit sie lernen und den HERRN, euren Gott, fürchten und darauf achten, alle Worte dieses Gesetzes zu tun*!", footnotes: ["℘ Jos 8,33", "℘ Kap. 4,10; 29,9.10"] },
      { number: 13, text: "Und ihre Kinder, die es nicht wissen*, sollen zuhören*, damit sie den HERRN, euren Gott, fürchten lernen alle Tage, die ihr in dem Land lebt, in das ihr über den Jordan zieht, um es in Besitz zu nehmen*.", footnotes: ["o. kennen", "℘ Ps 78,5", "℘ Kap. 32,47"] },
      { number: 14, text: "Und der HERR sprach zu Mose: Siehe, deine Tage sind herangekommen, dass du sterben wirst*. Rufe Josua, und findet euch im Zelt der Begegnung ein*, dass ich ihm Befehl erteile! Da gingen Mose und Josua hin und fanden sich im Zelt der Begegnung ein.", heading: "Gottes Befehl, das Moselied aufzuschreiben", footnotes: ["℘ Kap. 32,50; 34,5; 1Mo 47,29; 4Mo 27,13; 2Kö 20,1", "℘ 4Mo 27,18-23"] },
      { number: 15, text: "Und der HERR erschien im Zelt, in der Wolkensäule; und die Wolkensäule stand über* dem Eingang des Zeltes*.", footnotes: ["o. an", "℘ 2Mo 33,9"] },
      { number: 16, text: "Und der HERR sprach zu Mose: Siehe, du wirst dich zu deinen Vätern legen*. Und dieses Volk wird sich aufmachen und den fremden Göttern des Landes, in das es kommt*, in seiner Mitte nachhuren. Und es wird mich verlassen und meinen Bund brechen, den ich mit ihnen geschlossen habe*.", footnotes: ["℘ Kap. 32,50; 34,5; 1Mo 47,29; 4Mo 27,13; 2Kö 20,1", "℘ 2Mo 34,15; Ri 2,17; Jes 48,8", "℘ Ri 2,12; 2Kö 18,12; Hos 1,2"] },
      { number: 17, text: "Da wird mein Zorn an jenem Tag gegen es entbrennen, und ich werde sie verlassen* und mein Angesicht vor ihnen verbergen*. Und es wird zum Fraß werden, und viele Übel und Nöte werden es treffen*. Und es wird an jenem Tag sagen: Haben diese Übel mich nicht deshalb getroffen, weil mein Gott nicht mehr in meiner Mitte ist*?", footnotes: ["℘ Ri 6,13; 2Chr 21,10.11", "℘ Kap. 32,20; Jes 5,25; Jer 33,5; Hes 39,23", "℘ Kap. 30,18", "℘ Kap. 7,21; Ps 44,10; Jes 2,6; Jer 8,19; Mi 3,4"] },
      { number: 18, text: "Ich aber, ich werde an jenem Tag mein Angesicht völlig verbergen* wegen all des Bösen, das es getan, weil es sich andern Göttern zugewandt hat*.", footnotes: ["℘ 2Mo 34,15; Ri 2,17; Jes 48,8", "℘ 2Mo 34,15; Ri 2,17; Jes 48,8"] },
      { number: 19, text: "Und nun, schreibt euch dieses Lied auf*, und lehre es die Söhne Israel*! Lege es in ihren Mund, damit dieses Lied mir zum Zeugen gegen die Söhne Israel wird*!", footnotes: ["℘ Kap. 32,1-43", "℘ V. 26; Jos 24,27", "o. mir ein Zeuge unter den Söhnen Israel sei"] },
      { number: 20, text: "Denn ich werde es in das Land bringen, das von Milch und Honig überfließt*, das ich seinen Vätern zugeschworen habe, und es* wird essen und satt und fett werden. Und es wird sich andern Göttern zuwenden, und sie* werden ihnen dienen und mich verwerfen, und meinen Bund wird es* brechen*.", footnotes: ["℘ Kap. 6,3", "d. i. das Volk", "d. i. das Volk", "d. i. das Volk", "℘ Jer 31,32; Hos 6,7"] },
      { number: 21, text: "Und es wird geschehen, wenn viele Übel und Nöte es* treffen*, dann wird dieses Lied als Zeuge vor ihm* aussagen; denn es wird nicht vergessen werden im Mund seiner* Nachkommen. Denn ich kenne sein Sinnen*, mit dem es schon heute umgeht, noch bevor ich es in das Land bringe, das ich seinen Vätern zugeschworen habe.", footnotes: ["d. i. das Volk", "℘ Kap. 30,18", "d. i. das Volk", "d. i. das Volk", "℘ Ps 139,2; Joh 2,24"] },
      { number: 22, text: "Und Mose schrieb dieses Lied an jenem Tag auf, und er lehrte es die Söhne Israel*.", footnotes: ["℘ Kap. 32,44"] },
      { number: 23, text: "Und er* befahl Josua, dem Sohn des Nun, und sprach: Sei stark und mutig! Denn du, du wirst die Söhne Israel in das Land bringen, das ich ihnen zugeschworen habe. Und ich will mit dir sein.", footnotes: ["d. h. der HERR"] },
      { number: 24, text: "Und es geschah, als Mose damit fertig war, die Worte dieses Gesetzes vollständig* in ein Buch zu schreiben,", heading: "Aufbewahrung des Gesetzbuches", footnotes: ["w. bis zu ihrem Vollständigsein"] },
      { number: 25, text: "da befahl Mose den Leviten, die die Lade des Bundes des HERRN trugen:" },
      { number: 26, text: "Nehmt dieses Buch* des Gesetzes und legt es neben die Lade des Bundes des HERRN, eures Gottes, dass es dort zum Zeugen gegen dich wird!", footnotes: ["℘ 2Kö 22,8"] },
      { number: 27, text: "Denn ich kenne deine Widerspenstigkeit und deine Halsstarrigkeit wohl*. Siehe, heute schon, während ich noch bei euch lebe, seid ihr widerspenstig gegen den HERRN gewesen*; wie viel mehr nach meinem Tod!", footnotes: ["℘ 2Mo 32,9; Neh 9,29; Jes 30,9; Jer 5,23; Hes 20,21", "℘ Kap. 9,6.7.24; 1Sam 12,15; Ps 78,8; Joh 5,45"] },
      { number: 28, text: "Versammelt zu mir alle Ältesten* eurer Stämme und eure Aufseher*, dass ich diese Worte vor ihren Ohren rede und den Himmel und die Erde gegen sie als Zeugen aufrufe*!", heading: "Aufforderung zum Hören des Liedes Moses", footnotes: ["℘ 2Kö 23,1", "w. Schreiber; d. i. eine Beamtenbezeichnung", "℘ Kap. 4,26"] },
      { number: 29, text: "Denn ich habe erkannt, dass ihr nach meinem Tod ganz und gar zu eurem Verderben handeln und von dem Weg abweichen werdet*, den ich euch befohlen habe. Dann wird euch das Unheil treffen am Ende der Tage, weil ihr tun werdet, was böse ist in den Augen des HERRN, ihn zu reizen durch das Werk eurer Hände.", footnotes: ["℘ Kap. 32,5; 2Mo 32,7.8"] },
      { number: 30, text: "Und Mose redete vor den Ohren der ganzen Versammlung Israels die Worte dieses Liedes* zu Ende*:", footnotes: ["℘ 2Sam 22,1", "w. bis zu ihrem Vollständigsein\n℘ V. 1.19; Kap. 32,44"] },
    ]},
    { number: 32, verses: [
      { number: 1, text: "Horch auf, du Himmel, ich will reden, und die Erde höre die Worte meines Mundes*!", heading: "Das Lied des Mose", footnotes: ["℘ Kap. 4,26; Jes 1,2"] },
      { number: 2, text: "Wie Regen träufle meine Lehre, wie Tau riesle meine Rede, wie Regenschauer auf frisches Grün und wie Regengüsse auf welkes Kraut*!", footnotes: ["℘ Hi 29,22"] },
      { number: 3, text: "Denn den Namen des HERRN rufe ich aus*: Gebt Ehre* unserm Gott!*", footnotes: ["℘ 2Mo 34,5", "w. Größe", "℘ 1Chr 29,10-13"] },
      { number: 4, text: "Der Fels*; vollkommen ist sein Tun*, denn alle seine Wege sind recht*. Ein Gott der Treue und ohne Trug, gerecht und gerade ist er!*", footnotes: ["℘ 1Sam 2,2", "℘ 1Mo 1,31", "℘ 2Sam 22,31", "℘ Neh 9,8; Röm 9,14"] },
      { number: 5, text: "Es versündigte sich gegen ihn eine verkehrte und verdrehte Generation* — nicht seine Kinder sind sie, sondern ihr eigener Schandfleck —.", footnotes: ["℘ V. 20; Mt 17,17"] },
      { number: 6, text: "Wollt ihr so dem HERRN vergelten, törichtes und unweises Volk? Ist er nicht dein Vater*, der dich geschaffen* hat? Er hat dich gemacht* und dich bereitet.", footnotes: ["℘ Kap. 14,1; 2Mo 4,22", "o. erkauft", "℘ Ps 100,3; Jes 43,1.7"] },
      { number: 7, text: "Denk an die Tage der Vorzeit*, gebt acht auf die Jahre von Generation zu Generation! Frag deinen Vater, er wird es dir kundtun, deine Ältesten, sie werden es dir sagen*!", footnotes: ["℘ Kap. 8,2; Ps 44,2; 77,6", "℘ Hi 8,8"] },
      { number: 8, text: "Als der Höchste den Nationen das Erbe austeilte, als er die Menschenkinder voneinander schied*, da legte er fest die Grenzen der Völker* nach der Zahl der Söhne Israel*.", footnotes: ["℘ 1Mo 10,5.25.32", "℘ Apg 17,26", "LXX und die alte lat. Üs. lesen: nach der Zahl der Engel Gottes"] },
      { number: 9, text: "Denn der Anteil des HERRN ist sein Volk, Jakob das Maß* seines Erbteils*.", footnotes: ["w. die Messschnur", "℘ Kap. 9,29; 2Sam 20,19; Jes 19,25; 34,17"] },
      { number: 10, text: "Er fand ihn* im Land der Wüste und in der Öde, im Geheul der Wildnis*. Er umgab ihn, gab acht auf ihn, er behütete ihn wie seinen Augapfel*.", footnotes: ["o. es; d. i. das Volk; so im ganzen Vers", "℘ Ps 107,4; Hos 13,5", "℘ Ps 17,8; Sach 2,12"] },
      { number: 11, text: "Wie der Adler sein Nest aufstört, über seinen Jungen schwebt, *seine Flügel ausbreitet, sie* aufnimmt, sie trägt auf seinen Schwingen*,", footnotes: ["o. breitete er seine Flügel aus, nahm es auf, trug es auf seinen Fittichen; 12 der HERR allein leitete es", "w. es; d. h. das Nest", "℘ 2Mo 19,4"] },
      { number: 12, text: "so leitete ihn der HERR allein*, und kein fremder Gott war mit ihm*.", footnotes: ["o. breitete er seine Flügel aus, nahm es auf, trug es auf seinen Fittichen; 12 der HERR allein leitete es\n℘ Jos 24,17", "℘ Hi 15,19; Jes 43,12; 63,9"] },
      { number: 13, text: "Er ließ ihn einherfahren auf den Höhen der Erde,* und er aß die Früchte* des Feldes. Er ließ ihn* Honig saugen aus dem Felsen und Öl aus dem Felsenkiesel*,", footnotes: ["℘ Jes 58,14", "SamPent, LXX und syr. Üs. lesen: er speiste sie mit den Früchten", "o. es; d. i. das Volk; so im ganzen Vers", "℘ Hi 29,6"] },
      { number: 14, text: "Rahm der Kühe und Milch der Schafe samt dem Fett der Lämmer, Widder aus Baschan* und Böcke samt dem Besten* des Weizens* und das Blut der Traube trankest du, feurigen Wein.", footnotes: ["w. und Widder, und zwar Söhne Baschans", "w. Nierenfett", "℘ Kap. 28,47; Neh 9,25; Hos 11,4"] },
      { number: 15, text: "Da wurde Jeschurun* fett und schlug aus. Du wurdest fett, dick, feist! Und er verwarf den Gott*, der ihn gemacht*, und verachtete den Fels seiner Rettung*.", footnotes: ["d. h. vielleicht »der Rechtschaffene« und ist ein Ehrenname für Jakob-Israel\n℘ Kap. 33,5.26; Jes 44,2", "℘ Ps 100,3; Jes 43,1.7", "℘ Ps 100,3; Jes 43,1.7", "℘ 2Chr 12,1; Ps 89,27"] },
      { number: 16, text: "Sie reizten ihn zur Eifersucht durch fremde Götter, durch Gräuel kränkten sie ihn*.", footnotes: ["℘ 1Kö 14,9.22; 2Kö 17,11.17; 21,6; Ps 78,58; Jer 2,11; 8,19"] },
      { number: 17, text: "Sie opferten den Dämonen, die nicht Gott sind, Göttern, die sie nicht kannten, neuen, die erst vor kurzem aufgekommen waren, die eure Väter nicht verehrten*.", footnotes: ["o. von denen eure Väter nichts wussten\n℘ Kap. 13,8; 3Mo 17,7; Ri 5,8"] },
      { number: 18, text: "Den Felsen, der dich gezeugt, täuschtest* du und vergaßest den Gott, der dich geboren*.", footnotes: ["nach anderen: vergaßest; beide Üs. ergeben sich durch Veränderung eines Buchstabens", "℘ Ps 106,21; Jes 17,10; Jer 2,31.32"] },
      { number: 19, text: "Und der HERR sah es und verwarf sie aus Unwillen über* seine Söhne und seine Töchter*.", footnotes: ["o. wegen der Kränkung durch", "℘ Ps 106,40"] },
      { number: 20, text: "Er sprach: Ich will mein Angesicht vor ihnen verbergen*, will sehen, was ihr Ende ist; denn eine Generation voller Verkehrtheit sind sie, Kinder, in denen keine Treue ist.", footnotes: ["℘ Kap. 31,17; 2Kö 17,18.20.23"] },
      { number: 21, text: "Sie haben mich zur Eifersucht gereizt durch einen Nicht-Gott*, haben mich gekränkt durch ihre Nichtigkeiten*; so will auch ich sie zur Eifersucht reizen durch ein Nicht-Volk, durch eine törichte Nation will ich sie kränken*.", footnotes: ["℘ Jes 65,3; Jer 5,7; 18,15; Hes 8,3", "o. Götzen\n℘ 1Kö 14,9.22; 2Kö 17,11.17; 21,6; Ps 78,58; Jer 2,11; 8,19", "℘ Röm 10,19"] },
      { number: 22, text: "Denn ein Feuer ist entbrannt in meinem Zorn*, es brennt bis in den untersten Scheol und frisst die Erde und ihren Ertrag und entzündet die Grundfesten der Berge*.", footnotes: ["℘ Jer 15,14; Hes 19,12; 22,21; Am 5,6", "℘ Kla 2,2.4; Zef 1,18"] },
      { number: 23, text: "Ich will Unheil über sie häufen, meine Pfeile gegen sie verbrauchen*.", footnotes: ["℘ 2Kö 22,17; Ps 7,14"] },
      { number: 24, text: "Sie sind vor Hunger entkräftet und aufgezehrt von Fieberglut* und giftiger Pest, so sende ich den Zahn wilder Tiere gegen sie*, samt dem Gift der im Staub Kriechenden*.", footnotes: ["o. Seuche", "℘ Jer 15,3", "℘ Jer 8,17"] },
      { number: 25, text: "Draußen wird kinderlos machen das Schwert und drinnen* der Schrecken*: den Jüngling wie die Jungfrau, den Säugling mit dem greisen Mann*.", footnotes: ["w. in den Kammern", "℘ Kla 1,20; Hes 7,15", "℘ Jer 44,7; Hos 9,12.16; 11,6; Mi 6,14"] },
      { number: 26, text: "Ich hätte schon gesagt: Ich will sie zerschlagen, ihrer Erwähnung unter den Menschen ein Ende machen*!", footnotes: ["℘ Kap. 9,14; Ps 34,17"] },
      { number: 27, text: "Wenn ich die Kränkung durch den Feind nicht fürchtete*, dass ihre Gegner es falsch darstellten, dass sie sagten: Unsere Hand war erhaben! — und nicht: Der HERR hat dies alles gewirkt*!", footnotes: ["℘ Kap. 9,28; 2Mo 32,12", "℘ 1Kö 20,28; Ps 140,9; Jes 10,12.13; 48,11"] },
      { number: 28, text: "Denn sie sind eine Nation, die allen Rat verloren hat; keine Einsicht ist bei ihnen*.", footnotes: ["℘ Jer 4,22"] },
      { number: 29, text: "Wenn sie weise wären, würden sie das verstehen, würden ihr Ende bedenken*.", footnotes: ["℘ Jes 42,23; 47,7; Jer 5,31; Lk 19,42"] },
      { number: 30, text: "Wie könnte einer Tausend jagen und zwei Zehntausend in die Flucht schlagen*, wenn nicht deshalb, weil ihr Fels sie verkauft und der HERR sie preisgegeben hat*?", footnotes: ["℘ Jos 23,10; 2Chr 24,24; Jes 30,17", "℘ 1Kö 14,16; Jes 50,1"] },
      { number: 31, text: "Denn nicht wie unser Fels ist ihr Fels*; so haben unsere Feinde selbst geurteilt*!", footnotes: ["℘ 2Mo 8,6", "w. und unsere Feinde sind Richter"] },
      { number: 32, text: "Denn von dem Weinstock Sodoms ist ihr Weinstock und von den Terrassengärten Gomorras*; ihre Beeren sind Giftbeeren, bittere Trauben haben sie.", footnotes: ["℘ Jes 1,10; Jer 2,21; Hes 16,46"] },
      { number: 33, text: "Drachengift ist ihr Wein und grausames Viperngift*.", footnotes: ["℘ Ps 58,5"] },
      { number: 34, text: "Ist dies nicht bei mir aufbewahrt, versiegelt in meinen Schatzkammern*?", footnotes: ["℘ Kap. 29,28; Hos 13,12"] },
      { number: 35, text: "Mein ist die Rache und die Vergeltung* für die Zeit, da ihr Fuß wankt. Denn nahe ist der Tag ihres Verderbens, und was ihnen bevorsteht, eilt herbei*.", footnotes: ["T.; Mas. T.: und er hat vergolten\n℘ 2Sam 22,48; Ps 94,1; Nah 1,2; Lk 21,22; Röm 12,19", "℘ Jes 13,22; Jer 8,12; 2Petr 2,3"] },
      { number: 36, text: "Denn der HERR wird sein Volk richten*, und über seine Knechte wird er sich erbarmen*, wenn er sieht, dass geschwunden die Kraft und der Sklave und der Freie* dahin sind*.", footnotes: ["o. seinem Volk Recht schaffen\n℘ Hebr 10,30", "w. wird er es sich gereuen lassen\n℘ 2Mo 32,14; Ps 90,13; 135,14; Jer 42,10", "o. der Verheiratete und der Unverheiratete; o. der Unmündige und der Mündige; w. der Festgehaltene und der Losgelassene", "℘ 1Kö 14,10; 2Kö 14,26; Dan 12,7; Joe 2,18"] },
      { number: 37, text: "Und er wird sagen: Wo sind nun ihre Götter, der Fels, bei dem sie Zuflucht suchten*?", footnotes: ["℘ Jer 2,28; 11,12"] },
      { number: 38, text: "Die das Fett ihrer Schlachtopfer aßen, den Wein ihrer Trankopfer tranken, die sollen doch aufstehen und euch helfen, sie sollen* doch ein Schirm über euch sein*!", footnotes: ["so mit LXX, der lat. und syr. Üs.; Mas. T.: er soll", "℘ Ri 10,14"] },
      { number: 39, text: "Seht nun, dass ich, ich es bin und kein Gott neben mir ist*! Ich, ich töte, und ich mache lebendig*, ich zerschlage, und ich, ich heile*; und es gibt keinen, der aus meiner Hand rettet*!", footnotes: ["℘ Neh 9,6; Ps 102,28", "℘ 1Sam 2,6; Joh 5,21", "℘ Jes 19,22", "℘ Hi 10,7"] },
      { number: 40, text: "Denn ich erhebe meine Hand* zum Himmel und spreche: So wahr ich ewig lebe*!", footnotes: ["℘ Dan 12,7; Offb 10,5", "℘ 4Mo 14,21.28; 2Sam 22,47; 1Tim 6,16; Offb 4,9"] },
      { number: 41, text: "Wenn ich mein blitzendes Schwert geschärft habe und meine Hand zum Gericht greift, dann wende ich Rache auf meine Gegner zurück und vergelte es meinen Hassern*.", footnotes: ["℘ Kap. 7,10; Ps 149,9; Jes 59,18; Hes 32,10"] },
      { number: 42, text: "Meine Pfeile lass ich trunken werden von Blut*, und mein Schwert frisst Fleisch* vom Blut der Erschlagenen und Gefangenen, vom Haupt der Fürsten des Feindes*.", footnotes: ["℘ Ps 45,6", "℘ Jer 46,10", "o. vom behaarten Haupt des Feindes"] },
      { number: 43, text: "Lasst jauchzen, ihr Nationen, sein Volk*! Denn er rächt das Blut seiner Knechte*, und Rache wendet er auf seine Gegner zurück, und sein Land, sein Volk entsühnt er*.", footnotes: ["℘ Jes 60,6; Röm 15,10", "℘ Ps 79,10; Hes 25,14", "℘ Hes 16,63"] },
      { number: 44, text: "Und Mose kam und redete alle Worte dieses Liedes vor den Ohren des Volkes*, er und Hosea*, der Sohn des Nun*.", heading: "Moses letzte Mahnung", footnotes: ["℘ Kap. 31,22.30", "hebr. hoschea; d. h. Rettung; vgl. 3Mo 13,8", "℘ 4Mo 13,16"] },
      { number: 45, text: "Und als Mose all diese Worte zu ganz Israel zu Ende geredet hatte," },
      { number: 46, text: "da sagte er zu ihnen: Richtet euer Herz auf all die Worte, die ich euch heute bezeuge, damit ihr sie euren Kindern gebietet, dass sie darauf achten, alle Worte dieses Gesetzes zu tun*!", footnotes: ["℘ Kap. 4,9.10; Ps 78,5-7"] },
      { number: 47, text: "Denn nicht ein leeres Wort ist es für euch, sondern es ist euer Leben*. Und durch dieses Wort werdet ihr eure Tage verlängern in dem Land, in das ihr über den Jordan zieht, um es in Besitz zu nehmen*.", footnotes: ["℘ Kap. 8,3; 30,16.20; Spr 4,13; Joh 8,51", "℘ Kap. 31,13"] },
      { number: 48, text: "Und an ebendiesem Tag redete der HERR zu Mose und sprach:", heading: "Moses Vorbereitung auf den Tod" },
      { number: 49, text: "Steige auf das Gebirge Abarim* hier, auf den Berg Nebo, der im Land Moab liegt, der Jericho gegenüber ist, und sieh das Land Kanaan, das ich den Söhnen Israel zum Eigentum gebe*!", footnotes: ["℘ Jer 22,20", "℘ 1Mo 17,8; 4Mo 27,12"] },
      { number: 50, text: "Dann wirst du auf dem Berg sterben, auf den du steigst, und wirst zu deinen Völkern* versammelt werden*, ebenso wie dein Bruder Aaron auf dem Berg Hor gestorben ist und zu seinen Völkern versammelt wurde*,", footnotes: ["d. h. zu deinen Vorfahren", "℘ Kap. 31,14.16", "℘ 4Mo 20,24.28; 32,38"] },
      { number: 51, text: "weil ihr treulos gegen mich gehandelt habt mitten unter den Söhnen Israel am Wasser von Meribat-Kadesch* in der Wüste Zin, weil ihr mich nicht geheiligt habt mitten unter den Söhnen Israel*.", footnotes: ["o. am Streitwasser von Kadesch", "℘ 4Mo 20,12"] },
      { number: 52, text: "Denn von der gegenüberliegenden Seite* sollst du das Land sehen, aber du sollst nicht in das Land hineinkommen, das ich den Söhnen Israel gebe*.", footnotes: ["w. von gegenüber", "℘ Kap. 1,37"] },
    ]},
    { number: 33, verses: [
      { number: 1, text: "Und das ist der Segen, mit dem Mose, der Mann Gottes*, die Söhne Israel vor seinem Tod segnete*.", heading: "Moses Segen über die zwölf Stämme", footnotes: ["℘ Jos 14,6; 1Sam 2,27; 1Chr 23,14; 2Chr 8,14; Ps 90,1", "℘ 1Mo 49,28"] },
      { number: 2, text: "Er sprach: Der HERR kam vom Sinai und leuchtete ihnen auf von Seïr*. Er strahlte hervor vom Berg Paran* und kam von heiligen Myriaden*. Zu seiner Rechten war feuriges Gesetz* für sie*.", footnotes: ["℘ Ri 5,4", "℘ Hab 3,3", "Andere üs. mit T.: er kam von Meribat-Kadesch; vgl. dazu Kap. 32,51\n℘ Ps 50,2; 68,18; Jud 14", "Die Üs. ergibt sich aus einer anderen Wortabtrennung. Andere üs. mit Textänderung: war brennendes Feuer; Mas. T. ist kaum übersetzbar", "℘ 2Mo 19,18"] },
      { number: 3, text: "Ja, er liebt sein Volk*!* All seine Heiligen sind in deiner Hand*; und sie folgen* deinen Füßen, jeder* empfängt von deinen Worten*.", footnotes: ["so mit LXX; Mas. T.: Ja, der du die Völker liebst", "℘ Kap. 7,8; Jer 2,2; 31,3; Hos 11,1", "℘ Joh 10,28.29", "so mit Vulg. Die Bedeutung des im Mas. T. stehenden Wortes, das nur hier vorkommt, ist unbekannt.", "w. er", "℘ Lk 10,39"] },
      { number: 4, text: "Ein Gesetz hat uns Mose geboten*, einen Besitz der Versammlung Jakobs*.", footnotes: ["℘ 3Mo 26,46; Ps 147,19; Mal 3,22", "℘ Ps 119,111"] },
      { number: 5, text: "Und er wurde König in Jeschurun*, als sich die Häupter des Volkes versammelten, die Stämme Israels insgesamt. —", footnotes: ["d. h. vielleicht »der Rechtschaffene« und ist ein Ehrenname für Jakob-Israel\n℘ V. 26; Kap. 32,15; 2Mo 15,18"] },
      { number: 6, text: "*Ruben lebe und sterbe nicht, so dass seine Männer wenige würden*!", footnotes: ["℘ V. 6-25: 1Mo 35,23-26; vgl. 1Mo 49,3-27", "o. doch seine Männer seien gezählt; w. seine Männer seien eine Zahl"] },
      { number: 7, text: "Und dies für Juda: Und er sprach: Höre, HERR, die Stimme Judas und bring ihn zu seinem Volk! Seine Hände seien mächtig für ihn*, und sei ihm Helfer* vor seinen Gegnern*!", footnotes: ["o. haben für es gestritten; o. Lass seine Macht groß werden", "o. eine Hilfe", "℘ Ps 89,24"] },
      { number: 8, text: "Und für Levi sprach er: Deine Tummim und deine Urim sind für den Mann, der dir treu ist*, den du versucht hast bei Massa, mit dem du gestritten hast bei dem Wasser von Meriba*,", footnotes: ["℘ 2Mo 28,30", "℘ Kap. 9,22"] },
      { number: 9, text: "der von seinem Vater und von seiner Mutter sagte: »Ich habe ihn nicht gesehen!«, und der seine Brüder nicht kannte und von seinen Söhnen nichts wusste*. Denn sie haben dein Wort beachtet, und deinen Bund bewahren sie*.", footnotes: ["℘ 2Mo 32,26-29; Mt 10,37", "℘ Mal 2,5.6"] },
      { number: 10, text: "Sie lehren Jakob deine Rechtsbestimmungen und Israel dein Gesetz*. Sie legen Räucherwerk vor deine Nase* und Ganzopfer auf deinen Altar*.", footnotes: ["℘ Kap. 17,9.11; 27,14; 3Mo 10,11; 2Chr 30,22; Esr 7,10; Neh 8,7; Hag 2,12", "℘ 2Mo 30,7.8", "℘ Ps 51,21"] },
      { number: 11, text: "Segne, HERR, seine Kraft, und das Werk seiner Hände lass dir gefallen! Zerschmettere die Hüften derer, die sich gegen ihn erheben, und seiner Hasser, dass sie nicht mehr aufstehen*!", footnotes: ["℘ Jer 17,18"] },
      { number: 12, text: "Für Benjamin sprach er: Der Liebling des HERRN*! In Sicherheit wohnt er bei ihm. Er beschirmt ihn den ganzen Tag*, und zwischen seinen Berghängen* wohnt er.", footnotes: ["℘ 1Sam 10,20; 2Sam 12,24.25; Jer 12,7", "o. jeden Tag", "o. Schultern; d. h. in Gottes Schutz"] },
      { number: 13, text: "Und für Josef sprach er: Gesegnet vom HERRN ist sein Land! Vom Köstlichsten des Himmels, vom Tau, und von der Flut, die drunten lagert," },
      { number: 14, text: "und vom Köstlichsten der Erträge der Sonne und vom Köstlichsten der Früchte der Monate*", footnotes: ["Die Wörter Sonne und Monate bedeuten hier vielleicht die Jahreszeiten."] },
      { number: 15, text: "und vom Besten der uralten Berge und vom Köstlichsten der ewigen Hügel" },
      { number: 16, text: "und vom Köstlichsten der Erde und ihrer Fülle und das Wohlgefallen dessen, der im Dornbusch wohnt*, all das komme auf das Haupt Josefs und auf den Scheitel des Abgesonderten* unter seinen Brüdern!", footnotes: ["℘ 2Mo 3,2.4", "o. des Geweihten; o. des Fürsten; hebr. Nasir"] },
      { number: 17, text: "Er ist herrlich wie sein erstgeborener Stier*; und Hörner des Büffels sind seine Hörner*. Mit ihnen stößt er die Völker nieder, alle miteinander bis an die Enden der Erde*. Das sind die Zehntausende Ephraims, das die Tausende Manasses*.", footnotes: ["w. Die Erstgeburt seines Stieres ist ihm Pracht\n℘ 1Chr 5,1.2", "℘ 4Mo 23,22; 1Kö 22,11", "℘ Jos 17,18", "℘ 1Mo 48,19; Jos 17,14; 1Chr 5,23; 12,31.32"] },
      { number: 18, text: "Und für Sebulon sprach er: Freue dich, Sebulon, über deinen Auszug und du, Issaschar, über deine Zelte!" },
      { number: 19, text: "Sie rufen Völker zum Berg*. Dort opfern sie Opfer der Gerechtigkeit*; denn den Überfluss der Meere* saugen sie und die verborgenen Schätze des Sandes.", footnotes: ["℘ Jes 2,3", "℘ Ps 4,6", "℘ Jes 60,5"] },
      { number: 20, text: "Und für Gad sprach er: Gesegnet sei, der Gad Raum schafft! Wie eine Löwin lagert er und zerreißt den Arm und sogar den Scheitel*.", footnotes: ["℘ 1Chr 12,9"] },
      { number: 21, text: "Und er wählte sich einen Erstlingsanteil aus*; denn dort war der Anteil eines Anführers aufbewahrt. Und er zog an die Spitze* des Volkes*, er vollzog die Gerechtigkeit des HERRN und seine Gerichte mit* Israel.", footnotes: ["℘ 4Mo 32,1", "o. er kam zu den Häuptern", "℘ Jos 4,12", "o. dessen Rechtsbestimmungen zusammen mit"] },
      { number: 22, text: "Und für Dan sprach er: Dan ist ein junger Löwe; er springt aus Baschan hervor*.", footnotes: ["℘ Jos 19,47; Ri 18,27-29"] },
      { number: 23, text: "Und für Naftali sprach er: Naftali, gesättigt mit Huld und voller Segen des HERRN*! Westen und Süden nimm in Besitz!", footnotes: ["℘ Jer 31,14"] },
      { number: 24, text: "Und für Asser sprach er: Mehr als die andern Söhne sei Asser gesegnet! Er sei der Liebling seiner Brüder, er tauche in Öl seinen Fuß!" },
      { number: 25, text: "Eisen und Erz seien deine Riegel, und wie deine Tage so deine Kraft*!", footnotes: ["o. Ruhe\n℘ Jos 14,11; Jes 40,29-31"] },
      { number: 26, text: "Keiner ist wie der Gott Jeschuruns*, der auf dem Himmel einherfährt zu deiner Hilfe und in seiner Hoheit auf den Wolken*.", footnotes: ["d. h. vielleicht »der Rechtschaffene« und ist ein Ehrenname für Jakob-Israel\n℘ V. 5; 2Mo 8,6", "℘ 2Mo 15,7; Ps 104,3; Jes 19,1; Hab 3,8"] },
      { number: 27, text: "Eine Zuflucht ist der Gott der Urzeit*, und unter dir sind ewige Arme*. Und er vertrieb vor dir den Feind* und sprach: Vernichte*!", footnotes: ["℘ Ps 68,34; 90,1.2; Jes 26,4; Mi 5,1", "℘ Hos 11,3", "℘ 2Mo 23,28", "℘ Jer 50,21"] },
      { number: 28, text: "Und Israel wohnt sicher*, abgesondert der Quell Jakobs*, in einem Land von Korn und Most*; auch sein Himmel träufelt Tau*.", footnotes: ["℘ Kap. 12,10; 1Kö 5,5; Jer 23,6; Sach 14,11", "℘ 4Mo 23,9", "℘ 1Mo 27,28", "℘ Sach 8,12"] },
      { number: 29, text: "Glücklich bist du, Israel*! Wer ist wie du, ein Volk, gerettet durch den HERRN*, der der Schild deiner Hilfe* und der das Schwert deiner Hoheit ist? Schmeicheln* werden dir deine Feinde*, du aber, du wirst einherschreiten über ihre Höhen*.", footnotes: ["℘ Ps 33,12", "℘ Kap. 4,7.8", "℘ Ps 115,9-11", "w. Ergebung heucheln; d. i. eine Geste des Besiegten vor dem Sieger", "℘ Ps 18,45", "℘ Jes 33,16; Hab 3,19"] },
    ]},
    { number: 34, verses: [
      { number: 1, text: "Und Mose stieg von den Ebenen* Moabs auf den Berg Nebo, den Gipfel des Pisga, der Jericho gegenüberliegt*. Und der HERR ließ ihn das ganze Land sehen: das Land Gilead* bis nach Dan*", heading: "Moses Tod", footnotes: ["s. Anm. zu Kap. 1,1", "℘ Kap. 3,27; 4Mo 23,14", "℘ Jos 22,9", "℘ Ri 18,29"] },
      { number: 2, text: "und das ganze Land Naftali, das Land Ephraim und Manasse und das ganze Land Juda bis zum westlichen Meer*", footnotes: ["℘ 4Mo 34,6"] },
      { number: 3, text: "und den Süden und den Umkreis des Jordan, die Ebene von Jericho, der Palmenstadt*, bis hin nach Zoar*.", footnotes: ["℘ Ri 1,16; 2Chr 28,15", "℘ 1Mo 19,22"] },
      { number: 4, text: "Und der HERR sprach zu ihm: Das ist das Land, das ich Abraham, Isaak und Jakob zugeschworen habe, indem ich sprach: Deinen Nachkommen werde ich es geben*. Ich habe es dich mit deinen Augen sehen lassen, aber du sollst nicht nach dort hinübergehen.*", footnotes: ["℘ Kap. 1,8", "℘ Kap. 1,37"] },
      { number: 5, text: "Und Mose, der Knecht des HERRN*, starb dort im Land Moab nach dem Wort* des HERRN*.", footnotes: ["℘ Jos 1,1; 2Chr 1,3; Lk 9,30", "w. Mund", "℘ Kap. 31,14.16; 2Kö 1,17"] },
      { number: 6, text: "Und er begrub ihn im Tal, im Land Moab, Bet-Peor gegenüber*; und niemand kennt sein Grab bis auf diesen Tag*.", footnotes: ["℘ Kap. 4,46", "℘ Jud 9"] },
      { number: 7, text: "Mose aber war 120 Jahre alt, als er starb*. Sein Auge war nicht trübe geworden und seine Frische nicht geschwunden*.", footnotes: ["℘ Kap. 31,2", "℘ Jos 14,11; Hi 5,26; Ps 92,15"] },
      { number: 8, text: "Und die Söhne Israel beweinten Mose in den Ebenen* Moabs dreißig Tage lang*; dann waren die Tage des Weinens der Trauer um Mose zu Ende.", footnotes: ["s. Anm. zu Kap. 1,1", "℘ 1Mo 50,3; 1Sam 25,1"] },
      { number: 9, text: "Josua aber, der Sohn des Nun, war erfüllt mit dem Geist der Weisheit*; denn Mose hatte seine Hände auf ihn gelegt*. Und die Söhne Israel gehorchten ihm* und taten, wie der HERR dem Mose geboten hatte*.", footnotes: ["℘ 2Mo 28,3; 1Kö 3,12; Jes 11,2; Apg 6,3; Eph 1,17", "℘ 4Mo 27,18", "℘ Jos 1,16-18", "℘ 2Mo 12,28.35.50; 1Chr 29,23"] },
      { number: 10, text: "Und es stand in Israel kein Prophet mehr auf wie Mose*, den der HERR gekannt hätte von Angesicht zu Angesicht*,", footnotes: ["℘ Kap. 18,15-18", "℘ 2Mo 33,11; 4Mo 12,8"] },
      { number: 11, text: "mit all den Zeichen und Wundern*, mit denen der HERR ihn gesandt hatte, sie im Land Ägypten, am Pharao und an all seinen Knechten und an seinem ganzen Land zu tun*,", footnotes: ["o. Wahrzeichen", "℘ Kap. 1,30"] },
      { number: 12, text: "und mit all der starken Macht* und mit all dem Großen und Furchtbaren*, das Mose vor den Augen von ganz Israel getan hat.", footnotes: ["w. Hand", "w. mit all dem großen Furchtbaren"] },
    ]},
  ]
};
